GimCorpus.put(169,0,[[1,1,"וּקְרָא לְמשֶׁה וּמַלֵּיל יְיָ עִמֵּיהּ מִמַּשְׁכַּן זִמְנָא לְמֵימָר:",0,0],[1,2,"מַלֵּיל עִם בְּנֵי יִשְׂרָאֵל וְתֵימַר לְהוֹן אֱנַשׁ אֲרֵי יְקָרֵיב מִנְּכוֹן קֻרְבָּנָא קֳדָם יְיָ מִן בְּעִירָא מִן תּוֹרֵי וּמִן עָנָא תְּקָרְבוּן יָת קֻרְבַּנְכוֹן:",0,0],[1,3,"אִם עֲלָתָא קֻרְבָּנֵיהּ מִן תּוֹרֵי דְּכַר שְׁלִים יְקָרְבִנֵּיהּ לִתְרַע מַשְׁכַּן זִמְנָא יְקָרֵב יָתֵיהּ לְרַעֲוָא לֵיהּ קֳדָם יְיָ:",0,0],[1,4,"וְיִסְמוֹךְ יְדֵיהּ עַל רֵישׁ עֲלָתָא וְיִתְרְעֵי לֵיהּ לְכַפָּרָא עֲלוֹהִי:",0,0],[1,5,"וְיִכּוֹס יָת בַּר תּוֹרֵי קֳדָם יְיָ וִיקָרְבוּן בְּנֵי אַהֲרֹן כָּהֲנַיָּא יָת דְּמָא וְיִזְרְקוּן יָת דְּמָא עַל מַדְבְּחָא סְחוֹר סְחוֹר דִּי בִתְרַע מַשְׁכַּן זִמְנָא:",0,0],[1,6,"וְיַשְׁלַח יָת עֲלָתָא וִיפַלֵּג יָתַהּ לְאֶבְרָהָא:",0,0],[1,7,"וְיִתְּנוּן בְּנֵי אַהֲרֹן כַּהֲנָא אֶשָּׁתָא עַל מַדְבְּחָא וִיסַדְּרוּן אָעַיָּא עַל אֶשָּׁתָא:",0,0],[1,8,"וִיסַדְּרוּן בְּנֵי אַהֲרֹן כָּהֲנַיָּא יָת אֶבְרַיָּא יָת רֵישָׁא וְיָת תַּרְבָּא עַל אָעַיָּא דִּי עַל אֶשָׁתָא דִּי עַל מַדְבְּחָא:",0,0],[1,9,"וְגַוֵיהּ וּכְרָעוֹהִי יְחַלֵּל בְּמַיָּא וְיַסֵּק כַּהֲנָא יָת כּוֹלָא לְמַדְבְּחָא עֲלָתָא קֻרְבַּן דְּמִתְקַבֵּל בְּרַעֲוָא קֳדָם יְיָ:",0,0],[1,10,"וְאִם מִן עָנָא קֻרְבָּנֵיהּ מִן אִמְּרַיָּא אוֹ מִן בְּנֵי עִזַיָּא לַעֲלָתָא דְּכַר שְׁלִים יְקָרְבִינֵיהּ:",0,0],[1,11,"וְיִכּוֹס יָתֵיהּ עַל צִדָּא דְמַדְבְּחָא צִפּוּנָא קֳדָם יְיָ וְיִזְרְקוּן בְּנֵי אַהֲרֹן כָּהֲנַיָּא יָת דְּמֵיהּ עַל מַדְבְּחָא סְחוֹר סְחוֹר:",0,0],[1,12,"וִיפַלֵּג יָתֵיהּ לְאֵבָרוֹהִי וְיָת רֵישֵׁיהּ וְיָת תַּרְבֵּיהּ וְיַסְדַּר כַּהֲנָא יָתְהוֹן עַל אָעַיָּא דִּי עַל אֶשָּׁתָא דִּי עַל מַדְבְּחָא:",0,0],[1,13,"וְגַוָּא וּכְרָעַיָּא יְחַלֵּל בְּמַיָּא וִיקָרֵב כַּהֲנָא יָת כּוֹלָא וְיַסֵּק לְמַדְבְּחָא עֲלָתָא הוּא קֻרְבַּן דְּמִתְקַבֵּל בְּרַעֲוָא קֳדָם יְיָ:",0,0],[1,14,"וְאִם מִן עוֹפָא עֲלָתָא קֻרְבָּנֵיהּ קֳדָם יְיָ וִיקָרֵב מִן שַׁפְנִינַיָּא אוֹ מִן בְּנֵי יוֹנָה יָת קֻרְבָּנֵיהּ:",0,0],[1,15,"וִיקָרְבִנֵיהּ כַּהֲנָא לְמַדְבְּחָא וְיִמְלוֹק יָת רֵישֵׁיהּ וְיַסֵּק לְמַדְבְּחָא וְיִתִּמְצֵי דְמֵיהּ עַל כּוֹתֶל מַדְבְּחָא:",0,0],[1,16,"וְיַעֲדֵּי יָת זְפָקֵיהּ בְּאוּכְלֵיהּ וְיִרְמֵי יָתַהּ לִסְטַר מַדְבְּחָא קִידוּמָא לַאֲתַר דְּמוֹשְׁדִין קִטְמָא:",0,0],[1,17,"וִיפָרֵיק יָתֵיהּ בְּגַדְפוֹהִי לָא יַפְרֵישׁ וְיַסֵּק יָתֵיהּ כַּהֲנָא לְמַדְבְּחָא עַל אָעַיָּא דִּי עַל אֶשָּׁתָא עֲלָתָא הוּא קֻרְבָּן דְּמִתְקַבֵּל בְּרַעֲוָא קֳדָם יְיָ:",0,0],[2,1,"וֶאֱנַשׁ אֲרֵי יְקָרֵב קֻרְבַּן מִנְחָתָא קֳדָם יְיָ סוּלְתָּא יְהֵי קֻרְבָּנֵיהּ וִירִיק עֲלָהּ מִשְׁחָא וְיִתֵּן עֲלָהּ לְבוֹנְתָּא:",0,0],[2,2,"וְיַיְתִנָּהּ לְוָת בְּנֵי אַהֲרֹן כָּהֲנַיָּא וְיִקְמוֹץ מִתַּמָּן מְלֵי קֻמְצֵיהּ מִסֻּלְתָּא וּמִמִּשְׁחַהּ עַל כָּל לְבוֹנְתָּהּ וְיַסֵּק כַּהֲנָא יָת אַדְכַּרְתָּהּ לְמַדְבְּחָא קֻרְבַּן דְּמִתְקַבֵּל בְּרַעֲוָא קֳדָם יְיָ:",0,0],[2,3,"וּדְאִשְׁתָּאַר מִן מִנְחָתָא לְאַהֲרֹן וְלִבְנוֹהִי קוֹדֶשׁ קוּדְשִׁין מִקֻּרְבָּנַיָּא דַיְיָ:",0,0],[2,4,"וַאֲרֵי תְּקָרֵיב קֻרְבַּן מִנְחָתָא מַאֲפֵה תַנּוּרָא סוּלְתָּא גְּרִיצָן פַּטִּירָן דְּפִילָן בִּמְשַׁח וְאַסְפּוֹגִין פַּטִּירִין דִּמְשִׁיחִין בִּמְשָׁח:",0,0],[2,5,"וְאִם מִנְחָתָא עַל מַסְרֵיתָא קֻרְבָּנָךְ סוּלְתָּא דְּפִילָא בִמְשַׁח פַּטִּיר תְּהֵי:",0,0],[2,6,"בְּצַע יָתָהּ בִּיצוּעִין וּתְרִיק עֲלָהּ מִשְׁחָא מִנְחָתָא הִיא:",0,0],[2,7,"וְאִם מִנְחָתָא דְרַדְתָּא קֻרְבָּנָךְ סוּלְתָּא בִמְשַׁח תִּתְעֲבֵד:",0,0],[2,8,"וְתַיְתֵי יָת מִנְחָתָא דִּי יִתְעֲבֵד מֵאִלֵּין קֳדָם יְיָ וִיקַרְבִינָה לְוָת כַּהֲנָא וִיקַרְבִנַּהּ לְמַדְבְּחָא:",0,0],[2,9,"וְיַפְרֵישׁ כַּהֲנָא מִן מִנְחָתָא יָת אַדְכַּרְתָּה וְיַסֵּק לְמַדְבְּחָא קֻרְבַּן דְּמִתְקַבֵּל בְּרַעֲוָא קֳדָם יְיָ:",0,0],[2,10,"וּדְאִשְׁתָּאַר מִן מִנְחָתָא לְאַהֲרֹן וְלִבְנוֹהִי קוֹדֶשׁ קוּדְשִׁין מִקֻּרְבָּנַיָּא דַיְיָ:",0,0],[2,11,"כָּל מִנְחָתָא דִּי תְקָרְבוּן קֳדָם יְיָ לָא תִתְעֲבֵד חֲמִיעַ אֲרֵי כָל חֲמִיר וְכָל דְּבַשׁ לָא תַסְּקוּן מִנֵּיהּ קֻרְבָּנָא קֳדָם יְיָ:",0,0],[2,12,"קֻרְבַּן קַדְמַי תְּקָרְבוּן יָתְהוֹן קֳדָם יְיָ וּלְמַדְבְּחָא לָא יִתַּסְּקוּן לְאִתְקַבָּלָא בְרַעֲוָא:",0,0],[2,13,"וְכָל קֻרְבַּן מִנְחָתָךְ בְּמִלְחָא תִמְלַח וְלָא תְבַטֵּל מְלַח קְיַם אֱלָהָךְ מֵעַל מִנְחָתָךְ עַל כָּל קֻרְבָּנָךְ תְּקָרֵב מִלְחָא:",0,0],[2,14,"וְאִם תְּקָרֵב מִנְחַת בִּכּוּרִין קֳדָם יְיָ אָבִיב קְלֵי בְנוּר פֵּירוֹכָן רַכִּיכָן תְּקָרֵיב יָת מִנְחַת בִּכּוּרָךְ:",0,0],[2,15,"וְתִתֵּן עֲלַהּ מִשְׁחָא וּתְשַׁוֵּי עֲלַהּ לְבוֹנְתָּא מִנְחָתָא הִיא:",0,0],[2,16,"וְיַסֵּק כַּהֲנָא יָת אִדְכַּרְתַּהּ מִפֵּרוּכַהּ וּמִמִּשְׁחַהּ עַל כָּל לְבוֹנְתָּהּ קֻרְבָּנָא קֳדָם יְיָ:",0,0],[3,1,"וְאִם נִכְסַת קוּדְשַׁיָּא קֻרְבָּנֵיהּ אִם מִן תּוֹרֵי הוּא מְקָרֵב אִם דְּכַר אִם נוּקְבָא שְׁלִים יְקָרְבִינֵיהּ קֳדָם יְיָ:",0,0],[3,2,"וְיִסְמוֹךְ יְדֵיהּ עַל רֵישׁ קֻרְבָּנֵיהּ וְיִכְּסִנֵּיהּ בִּתְרַע מַשְׁכַּן זִמְנָא וְיִזְרְקוּן בְּנֵי אַהֲרֹן כָּהֲנַיָּא יָת דְּמָא עַל מַדְבְּחָא סְחוֹר סְחוֹר:",0,0],[3,3,"וִיקָרֵב מִנִּכְסַת קוּדְשַׁיָּא קֻרְבָּנָא קֳדָם יְיָ יָת תַּרְבָּא דְּחָפֵי יָת גַּוָּא וְיָת כָּל תַּרְבָּא דִּי עַל גַּוָּא:",0,0],[3,4,"וְיָת תַּרְתֵּין כָּלְיָן וְיָת תַּרְבָּא דִי עֲלֵיהֶן דִּי עַל גִּסְסַיָּא וְיָת חַצְרָא דְּעַל כַּבְדָא עַל כָּלְיֵתָא יַעֲדִּנָּהּ:",0,0],[3,5,"וְיַסְקוּן יָתֵיהּ בְּנֵי אַהֲרֹן לְמַדְבְּחָא עַל עֲלָתָא דִּי עַל אָעַיָּא דִּי עַל אֶשָּׁתָא קֻרְבַּן דְּמִתְקַבֵּל בְּרַעֲוָא קֳדָם יְיָ:",0,0],[3,6,"וְאִם מִן עָנָא קֻרְבָּנֵיהּ לְנִכְסַת קוּדְשַׁיָּא קֳדָם יְיָ דְּכַר אוֹ נֻקְבָּא שְׁלִים יְקָרְבִנֵּיהּ:",0,0],[3,7,"אִם אִימָר הוּא מְקָרֵב יָת קֻרְבָּנֵיהּ וִיקָרֵיב יָתֵיהּ קֳדָם יְיָ:",0,0],[3,8,"וְיִסְמוֹךְ יָת יְדֵיהּ עַל רֵישׁ קֻרְבָּנֵיהּ וְיִכּוֹס יָתֵיהּ קֳדָם מַשְׁכַּן זִמְנָא וְיִזְרְקוּן בְּנֵי אַהֲרֹן יָת דְּמֵיהּ עַל מַדְבְּחָא סְחוֹר סְחוֹר:",0,0],[3,9,"וִיקָרֵב מִנִּכְסַת קוּדְשַׁיָּא קֻרְבָּנָא קֳדָם יְיָ תַּרְבֵּיהּ אֲלִיתָא שְׁלִימְתָּא לָקֳבֵל שְׁזַרְתָּא יֶעְדִנַּהּ וְיָת תַּרְְבָּא דְּחָפֵי יָת גַּוָּא וְיָת כָּל תַּרְבָּא דִּי עַל גַּוָּא:",0,0],[3,10,"וְיָת תַּרְתֵּין כָּלְיָן וְיָת תַּרְבָּא דִּי עֲלֵיהֶן דִּי עַל גִּסְסַיָּא וְיָת חַצְרָא דְּעַל כַּבְדָּא עַל כָּלְיֵתָא יֶעְדִּנַּהּ:",0,0],[3,11,"וְיַסְּקִנֵּיהּ כַּהֲנָא לְמַדְבְּחָא לְחֵם קֻרְבָּנָא קֳדָם יְיָ:",0,0],[3,12,"וְאִם מִן בְּנֵי עִזַּיָּא קֻרְבָּנֵיהּ וִיקָרְבִנֵּיהּ קֳדָם יְיָ:",0,0],[3,13,"וְיִסְמוֹךְ יָת יְדֵיהּ עַל רֵישֵׁיהּ וְיִכּוֹס יָתֵיהּ קֳדָם מַשְׁכַּן זִמְנָא וְיִזְרְקוּן בְּנֵי אַהֲרֹן יָת דְּמֵיהּ עַל מַדְבְּחָא סְחוֹר סְחוֹר:",0,0],[3,14,"וִיקָרֵב מִנֵּיהּ קֻרְבָּנֵיהּ קֻרְבָּן קֳדָם יְיָ יָת תַּרְבָּא דְּחָפֵי יָת גַּוָּא וְיָת כָּל תַּרְבָּא דִּי עַל גַּוָּא:",0,0],[3,15,"וְיָת תַּרְתֵּין כָּלְיָן וְיָת תַּרְבָּא דִּי עֲלֵיהֶן דִּי עַל גִּסְסַיָּא וְיָת חַצְרָא דִּי עַל כַּבְדָא עַל כָּלְיֵתָא יֶעְדִּנַּהּ:",0,0],[3,16,"וְיַסְּקִנּוּן כַּהֲנָא לְמַדְבְּחָא לְחֵם קֻרְבָּנָא לְאִתְקַבָּלָא בְרַעֲוָא כָּל תַּרְבָּא קֳדָם יְיָ:",0,0],[3,17,"קְיָם עָלָם לְדָרָתֵיכוֹן בְּכֹל מוֹתְבָנֵיכוֹן כָּל תַּרְבָּא וְכָל דְּמָא לָא תֵיכְלוּן:",0,0],[4,1,"וּמַלִּיל יְיָ עִם משֶׁה לְמֵימָר:",0,0],[4,2,"מַלֵּל עִם בְּנֵי יִשְׂרָאֵל לְמֵימָר אֱנַשׁ אֲרֵי יֵחוֹב בְּשָׁלוּ מִכָּל פִּקּוּדַיָּא דַיְיָ דִּי לָא כַשְׁרִין לְאִתְעֲבָדָא וְיַעְבֵּד מִן חַד מִנְּהוֹן:",0,0],[4,3,"אִם כַּהֲנָא רַבָּא יֵחוֹב לְחוֹבַת עַמָּא וִיקָרֵב עַל חוֹבְתֵיהּ דִּי חָב תּוֹר בַּר תּוֹרֵי שְׁלִים קֳדָם יְיָ לְחַטָּאתָא:",0,0],[4,4,"וְיַיְתִי יָת תּוֹרָא לִתְרַע מַשְׁכַּן זִמְנָא לָקֳדָם יְיָ וְיִסְמוֹךְ יָת יְדֵיהּ עַל רֵישׁ תּוֹרָא וְיִכּוֹס יָת תּוֹרָא קָדֳם יְיָ:",0,0],[4,5,"וְיִסַּב כַּהֲנָא רַבָּא מִדְּמָא דְתוֹרָא וְיָעֵל יָתֵיהּ לְמַשְׁכַּן זִמְנָא:",0,0],[4,6,"וְיִטְבּוֹל כַּהֲנָא יָת אֶצְבְּעֵיהּ בִּדְמָא וְיַדִּי מִן דְּמָא שְׁבַע זִמְנִין קֳדָם יְיָ קֳדָם פָּרוּכְתָּא דְקוּדְשָׁא:",0,0],[4,7,"וְיִתֵּן כַּהֲנָא מִן דְּמָא עַל קַרְנַת מַדְבַּח דִקְטוֹרֶת בּוּסְמַיָא קֳדָם יְיָ דִּי בְּמַשְׁכַּן זִמְנָא וְיָת כָּל דְּמָא דְתוֹרָא יֵשׁוּד לִיסוֹדָא דְּמַדְבְּחָא דַעֲלָתָא דִּי בִתְרַע מַשְׁכַּן זִמְנָא:",0,0],[4,8,"וְיָת כָּל תְּרַב תּוֹרָא דְחַטָּאתָא יַפְרֵשׁ מִנֵּיהּ יָת תַּרְבָּא דְּחָפֵי עַל גַּוָּא וְיָת כָּל תַּרְבָּא דִּי עַל גַּוָּא:",0,0],[4,9,"וְיָת תַּרְתֵּין כָּלְיָן וְיָת תַּרְבָּא דִּי עֲלֵיהוֹן דִּי עַל גִּסְסַיָּא וְיָת חִצְרָא דְּעַל כַּבְדָא עַל כָּלְיֵתָא יֶעְדִּנַּהּ:",0,0],[4,10,"כְּמָא דִי מִתַּפְרַשׁ מִתּוֹר נִכְסַת קוּדְשַׁיָּא וְיַסֵּקִנּוּן כַּהֲנָא עַל מַדְבְּחָא דַעֲלָתָא:",0,0],[4,11,"וְיָת מְשַׁךְ תּוֹרָא וְיָת כָּל בִּסְרֵיהּ עַל רֵישֵׁיהּ וְעַל כְּרָעוֹהִי וְגַוֵּיהּ וְאוּכְלֵיהּ:",0,0],[4,12,"וְיַפֵּק יָת כָּל תּוֹרָא מִבָּרָא לְמַשְׁרִיתָא לַאֲתַר דְּכֵי לַאֲתַר בֵּית מֵישַׁד קִטְמָא וְיוֹקִיד יָתֵיהּ עַל אָעַיָּא בְּאֶשָּׁתָא עַל אֲתַר בֵּית מֵישַׁד קִטְמָא יִתּוֹקָד:",0,0],[4,13,"וְאִם כָּל כְּנִשְׁתָּא דְיִשְׂרָאֵל יִשְׁתְּלוּן וִיהֵי מְכַסָּא פִתְגָּמָא מֵעֵינֵי קְהָלָא וְיַעְבְּדוּן חָד מִכָּל פִּקּוּדַיָּא דַיְיָ דִּי לָא כָשְׁרִין לְאִתְעֲבָדָא וִיחוֹבוּן:",0,0],[4,14,"וְתִתְיְדַע חוֹבְתָא דִּי חָבוּ עֲלַהּ וִיקַרְבוּן קְהָלָא תּוֹר בַּר תּוֹרֵי לְחַטָּאתָא וְיַיְתוּן יָתֵיהּ לָקֳדָם מַשְׁכַּן זִמְנָא:",0,0],[4,15,"וְיִסְמְכוּן סָבֵי כְנִשְׁתָּא יָת יְדֵיהוֹן עַל רֵישׁ תּוֹרָא קֳדָם יְיָ וְיִכּוֹס יָת תּוֹרָא קֳדָם יְיָ:",0,0],[4,16,"וְיָעֵל כַּהֲנָא רַבָּא מִן דְּמָא דְתוֹרָא לְמַשְׁכַּן זִמְנָא:",0,0],[4,17,"וְיִטְבּוֹל כַּהֲנָא אִצְבְּעֵיהּ מִן דְּמָא וְיַדִּי שְׁבַע זִמְנִין קֳדָם יְיָ קֳדָם פָּרֻכְתָּא:",0,0],[4,18,"וּמִן דְּמָא יִתֵּן עַל קַרְנַת מַדְבְּחָא דִּי קֳדָם יְיָ דִּי בְּמַשְׁכַּן זִמְנָא וְיָת כָּל דְּמָא יֵשׁוֹד לִיסוֹדָא דְּמַדְבְּחָא דַעֲלָתָא דִּי בִתְרַע מַשְׁכַּן זִמְנָא:",0,0],[4,19,"וְיָת כָּל תַּרְבֵּיהּ יַפְרֵשׁ מִנֵּיהּ וְיַסֵּק לְמַדְבְּחָא:",0,0],[4,20,"וְיַעְבֵּד לְתוֹרָא כְּמָא דִי עֲבַד לְתוֹרָא דְחַטָּאתָא כֵּן יַעְבֵּד לֵיהּ וִיכַפֵּר עֲלֵיהוֹן כַּהֲנָא וְיִשְׁתְּבֵק לְהוֹן:",0,0],[4,21,"וְיַפֵּק יָת תּוֹרָא לְמִבָּרָא לְמַשְׁרִיתָא וְאוֹקִיד יָתֵיהּ כְּמָא דִי אוֹקִיד יָת תּוֹרָא קַדְמָאָה חַטַּאת קְהָלָא הוּא:",0,0],[4,22,"אִם רַבָּא יֵחוֹב וְיַעְבֵּד חַד מִכָּל פִּקּוּדַיָּא דַיְיָ אֱלָהֵיהּ דִּי לָא כַשְׁרִין לְאִתְעֲבָדָא בְּשָׁלוּ וְיֵחוֹב:",0,0],[4,23,"אוֹ אִתְיְדַע לֵיהּ חוֹבְתֵיהּ דִּי חַב בַּהּ וְיַיְתִי יָת קֻרְבָּנֵיהּ צְפִיר בַּר עִזִּין דְּכַר שְׁלִים:",0,0],[4,24,"וְיִסְמוֹךְ יְדֵיהּ עַל רֵישָׁא דִצְפִירָא וְיִכּוֹס יָתֵיהּ בַּאֲתַר דְּיִכּוֹס יָת עֲלָתָא לָקֳדָם יְיָ חַטָּאתָא הוּא:",0,0],[4,25,"וְיִסַּב כַּהֲנָא מִדְּמָא דְחַטָּאתָא בְּאֶצְבְּעֵיהּ וְיִתֵּן עַל קַרְנַת מַדְבְּחָא דַעֲלָתָא וְיָת דְּמֵיהּ יֵשׁוֹד לִיסוֹדָא דְמַדְבְּחָא דַעֲלָתָא:",0,0],[4,26,"וְיָת כָּל תַּרְבֵּיהּ יַסֵּק לְמַדְבְּחָא כִּתְרַב נִכְסַת קוּדְשַׁיָּא וִיכַפֵּר עֲלוֹהִי כַּהֲנָא מֵחוֹבְתֵיהּ וְיִשְׁתְּבֵק לֵיהּ:",0,0],[4,27,"וְאִם אֱנַשׁ חַד יֵחוֹב בְּשָׁלוּ מֵעַמָּא דְאַרְעָא בְּמֶעְבְּדַהּ חַד מִפִּקּוּדַיָּא דַיְיָ דִּי לָא כַשְׁרִין לְאִתְעֲבָדָא וְיֵחוֹב:",0,0],[4,28,"אוֹ אִתְיְדַע לֵיהּ חוֹבְתֵיהּ דִּי חָב וְיַיְתִי קֻרְבָּנֵיהּ צְפִירַת עִזִּין שְׁלֶמְתָּא נְקוּבְתָּא עַל חוֹבְתֵיהּ דִּי חָב:",0,0],[4,29,"וְיִסְמוֹךְ יָת יְדֵיהּ עַל רֵישׁ חַטָּאתָא וְיִכּוֹס יָת חַטָּאתָא בַּאֲתַר דַּעֲלָתָא:",0,0],[4,30,"וְיִסַּב כַּהֲנָא מִדְמַהּ בְּאֶצְבְּעֵיהּ וְיִתֵּן עַל קַרְנַת מַדְבְּחָא דַעֲלָתָא וְיָת כָּל דְּמַהּ יֵשׁוֹד לִיסוֹדָא דְּמַדְבְּחָא:",0,0],[4,31,"וְיָת כָּל תַּרְבַּהּ יֶעְדֵּי כְּמָא דִי מִתַּעְדָּא תְרַב מֵעַל נִכְסַת קוּדְשַׁיָּא וְיַסֵּק כַּהֲנָא לְמַדְבְּחָא לְאִתְקַבָּלָא בְרַעֲוָא קֳדָם יְיָ וִיכַפֵּר עֲלוֹהִי כַּהֲנָא וְיִשְׁתְּבֵק לֵיהּ:",0,0],[4,32,"וְאִם אִימַר יַיְתִי קֻרְבָּנֵיהּ לְחַטָּאתָא נֻקְבָּא שְׁלֶמְתָּא יַיְתִנַּהּ:",0,0],[4,33,"וְיִסְמוֹךְ יָת יְדֵיהּ עַל רֵישׁ חַטָּאתָא וְיִכּוֹס יָתַהּ לְחַטָּאתָא בְּאַתְרָא דִּי יִכּוֹס יָת עֲלָתָא:",0,0],[4,34,"וְיִסַּב כַּהֲנָא מִדְּמָא דְחַטָּאתָא בְּאֶצְבְּעֵיהּ וְיִתֵּן עַל קַרְנַת מַדְבְּחָא דַעֲלָתָא וְיָת כָּל דְּמַהּ יֵשׁוֹד לִיסוֹדָא דְּמַדְבְּחָא:",0,0],[4,35,"וְיָת כָּל תַּרְבַּהּ יֶעְדֵּי כְּמָא דִי מִתַּעְדָּא תְרַב אִמְּרָא מִנִּכְסַת קוּדְשַׁיָּא וְיַסֵּק כַּהֲנָא יָתְהוֹן לְמַדְבְּחָא עַל קֻרְבְּנַיָּא דַיְיָ וִיכַפֵּר עֲלוֹהִי כַּהֲנָא עַל חוֹבְתֵיהּ דִּי חָב וְיִשְׁתְּבֵק לֵיהּ:",0,0],[5,1,"וֶאֱנַשׁ אֲרֵי יֵחוֹב וְיִשְׁמַע קַל מוֹמֵי וְהוּא סָהִיד אוֹ חֲזָא אוֹ יְדָע אִם לָא יְחַוִּי וִיקַבֵּל חוֹבֵיהּ:",0,0],[5,2,"אוֹ אֱנַשׁ דִּי יִקְרַב בְּכֹל מִדַּעַם מְסָאָב אוֹ בְנִבְלַת חַיְתָא מְסָאָבָא אוֹ בְּנִבְלַת בְּעִירָא מְסָאָבָא אוֹ בְּנִבְלַת רִחֲשָׁא מְסָאָב וִיהֵי מְכַסָּא מִנֵּיהּ וְהוּא מְסָאָב וְחָב:",0,0],[5,3,"אוֹ אֲרֵי יִקְרַב בְּסוֹאֲבַת אֱנָשָׁא לְכָל סוֹבְתֵיהּ דִּי יִסְתָּאַב בַּהּ וִיהֵי מְכַסָּא מִנֵּיהּ וְהוּא יָדַע וְחָב:",0,0],[5,4,"אוֹ אֱנַשׁ אֲרֵי יְקַיֵּם לְפָרָשָׁא בְסִפְוָן לְאַבְאָשָׁא אוֹ לְאוֹטָבָא לְכֹל דִּי יְפָרֵשׁ אֱנָשָׁא בְּקִיּוּם וִיהֵי מְכַסָּא מִנֵּיהּ וְהוּא יָדַע וְחָב לַחֲדָא מֵאִלֵּין:",0,0],[5,5,"וִיהֵי אֲרֵי יֵחוֹב לַחֲדָא מֵאִלֵּין וִיוַדִּי דִּי חָב עֲלַהּ:",0,0],[5,6,"וְיַיְתִי יָת אַשְׁמֵיהּ קֳדָם יְיָ עַל חוֹבְתֵיהּ דִּי חָב נְקוּבְתָא מִן עָנָא אִמְּרָתָא אוֹ צְפִירַת עִזִּין לְחַטָאתָא וִיכַפֵּר עֲלוֹהִי כַּהֲנָא מֵחוֹבְתֵיהּ:",0,0],[5,7,"וְאִם לָא תִמְטֵי יְדֵיהּ כְּמִסַּת שֵׂיתָא וְיַיְתִי יָת חוֹבְתֵיהּ דִּי חָב תַּרְתֵּין שַׁפְנִינִין אוֹ תְרֵין בְּנֵי יוֹנָה קֳדָם יְיָ חַד לְחַטָּאתָא וְחַד לַעֲלָתָא:",0,0],[5,8,"וְיַיְתִי יָתְהוֹן לְוָת כַּהֲנָא וִיקָרֵב יָת דִּי לְחַטָּאתָא קַדְמֵיתָא וְיִמְלוֹק יָת רֵישֵׁיהּ מִלָּקֳבֵל קְדָלֵיהּ וְלָא יַפְרֵשׁ:",0,0],[5,9,"וְיַדִּי מִדְּמָא דְחַטָּאתָא עַל כֹּתֶל מַדְבְּחָא וּדְאִשְׁתָּאַר בִּדְמָא יִתִּמְצֵי לִיסוֹדָא דְמַדְבְּחָא חַטָּאתָא הוּא:",0,0],[5,10,"וְיָת תִּנְיָנָא יַעְבֵּד עֲלָתָא כִּדְחָזֵי וִיכַפֵּר עֲלוֹהִי כַּהֲנָא מֵחוֹבְתֵיהּ דִּי חָב וְיִשְׁתְּבֵק לֵיהּ:",0,0],[5,11,"וְאִם לָא תַדְבֵּק יְדֵיהּ לְתַּרְתֵּין שַׁפְנִינִין אוֹ לִתְרֵין בְּנֵי יוֹנָה וְיַיְתִי יָת קֻרְבָּנֵיהּ דִּי חָב חַד מִן עַסְרָא בִתְלַת סְאִין סֻלְתָּא לְחַטָּאתָא לָא יְשַׁוִּי עֲלַהּ מִשְׁחָא וְלָא יִתֵּן עֲלַהּ לְבֻנְתָּא אֲרֵי חַטָּאתָא הִיא:",0,0],[5,12,"וְיַיְתִנַּהּ לְוָת כַּהֲנָא וְיִקְמוֹץ כַּהֲנָא מִנַּהּ מְלֵי קֻמְצֵיהּ יָת אִדְכַּרְתַּהּ וְיַסֵּק לְמַדְבְּחָא עַל קֻרְבָּנַיָּא דַיְיָ חַטָּאתָא הִיא:",0,0],[5,13,"וִיכַפֵּר עֲלוֹהִי כַּהֲנָא עַל חוֹבְתֵיהּ דִּי חָב מֵחֲדָא מֵאִלֵּין וְיִשְׁתְּבֵק לֵיהּ וּתְהֵי לְכַהֲנָא כְּמִנְחָתָא:",0,0],[5,14,"וּמַלִּיל יְיָ עִם משֶׁה לְמֵימָר:",0,0],[5,15,"אֱנַשׁ אֲרֵי יְשַׁקַּר שְׁקַר וְיֵחוֹב בְּשָׁלוּ מִקוּדְשַׁיָּא דַיְיָ וְיַיְתִי יָת אַשְׁמֵיהּ קֳדָם יְיָ דְכַר שְׁלִים מִן עָנָא בְּפֻרְסָנֵיהּ כְּסַף סִלְעִין בְּסִלְעֵי קוּדְשָׁא לַאֲשָׁמָא:",0,0],[5,16,"וְיָת דִּי חָב מִן קוּדְשָׁא יְשַׁלֵּם וְיָת חֻמְשֵׁיהּ יוֹסֵף עֲלוֹהִי וְיִתֵּן יָתֵיהּ לְכַהֲנָא וְכַהֲנָא יְכַפֵּר עֲלוֹהִי בְּדִכְרָא דַאֲשָׁמָא וְיִשְׁתְּבֵק לֵיהּ:",0,0],[5,17,"וְאִם אֱנַשׁ אֲרֵי יֵחוֹב וְיַעְבֵּד חֲדָא מִכָּל פִּקּוֹדַיָּא דַיְיָ דִּי לָא כָשְׁרִין לְאִתְעֲבָדָא וְלָא יָדַע וְיֵחוֹב וִיקַבֵּל חוֹבֵיהּ:",0,0],[5,18,"וְיַיְתִי דְּכַר שְׁלִים מִן עָנָא בְּפֻרְסָנֵיהּ לַאֲשָׁמָא לְוָת כַּהֲנָא וִיכַפֵּר עֲלוֹהִי כַהֲנָא עַל שָׁלוּתֵיהּ דְּאִשְׁתְּלִי וְהוּא לָא יָדַע וְיִשְׁתְּבֵק לֵיהּ:",0,0],[5,19,"אֲשָׁמָא הוּא עַל חוֹבְתֵיהּ דְּהוּא חָב אֲשָׁמָא יְקָרֵב קֳדָם יְיָ:",0,0],[5,20,"וּמַלִּיל יְיָ עִם משֶׁה לְמֵימָר:",0,0],[5,21,"אֱנַשׁ אֲרֵי יֵחוֹב וִישַׁקַּר שְׁקַר קֳדָם יְיָ וִיכַדֵב בְּחַבְרֵיהּ בּפִקְּדוֹנָא אוֹ בְשֻׁתָּפוּת יְדָא אוֹ בִגְזֵלָא אוֹ אַנִּיס יָת חַבְרֵיהּ:",0,0],[5,22,"אוֹ אַשְׁכַּח אֲבֵדְתָּא וִיכַדֵּב בַּהּ וְאִשְׁתְּבַע עַל שִׁקְרָא עַל חֲדָא מִכֹּל דִּי יַעְבֵּד אֱנָשָׁא לְמֵיחַב בְּהֵן:",0,0],[5,23,"וִיהֵי אֲרֵי יֶחֱטֵי וְיֵחוֹב וְיָתֵב יָת גְּזֵלָא דִּי גְזַל אוֹ יָת עֻשְׁקָא דִּי עֲשַׁק אוֹ יָת פִּקְּדוֹנָא דִּי אִתְפָּקַּד לְוָתֵיהּ אוֹ יָת אֲבֵדְתָּא דִּי אַשְׁכַּח:",0,0],[5,24,"אוֹ מִכֹּל דִּי יִשְׁתְּבַע עֲלוֹהִי לְשִׁקְרָא וִישַׁלֵּם יָתֵיהּ בְּרֵישֵׁיהּ וְחֻמְשֵׁיהּ יוֹסֵף עֲלוֹהִי לְדִי הוּא דִילֵיהּ יִתְּנִנֵּיהּ בְּיוֹמָא דְחוֹבְתֵיהּ:",0,0],[5,25,"וְיָת אַשְׁמַהּ יַיְתִי לָקֳדָם יְיָ דְּכַר שְׁלִים מִן עָנָא בְּפֻרְסָנֵיהּ לַאֲשָׁמָא לְוָת כַּהֲנָא:",0,0],[5,26,"וִיכַפֵּר עֲלוֹהִי כַהֲנָא קֳדָם יְיָ וְיִשְׁתְּבֵק לֵיהּ עַל חֲדָא מִכֹּל דִּי יַעְבֵּד לְמֵיחַב בַּהּ:",0,0],[6,1,"וּמַלִּיל יְיָ עִם משֶׁה לְמֵימָר:",0,0],[6,2,"פַּקֵּד יָת אַהֲרֹן וְיָת בְּנוֹהִי לְמֵימָר דָּא אוֹרַיְתָא דַּעֲלָתָא הִיא עֲלָתָא עַל דְּמִתּוֹקְדָא עַל מַדְבְּחָא כָל לֵילְיָא עַד צַפְרָא וְאֶשָּׁתָא דְמַדְבְּחָא תְּהֵא יָקְדָא בֵיהּ:",0,0],[6,3,"וְיַלְבֵּשׁ כַּהֲנָא לְבוּשִׁין דְּבוּץ וּמִכְנְסִין דְּבוּץ יַלְבֵּשׁ עַל בִּסְרֵיהּ וְיַפְרֵשׁ יָת קִטְמָא דִּי תֵיכוּל אֶשָּׁתָא יָת עֲלָתָא עַל מַדְבְּחָא וִישַׁוִּנֵּיהּ בִּסְטַר מַדְבְּחָא:",0,0],[6,4,"וְיַשְׁלַח יָת לְבוּשׁוֹהִי וְיִלְבַּשׁ לְבוּשִׁין אָחֳרָנִין וְיַפֵּק יָת קִטְמָא לְמִבָּרָא לְמַשְׁרִיתָא לַאֲתַר דְּכֵי:",0,0],[6,5,"וְאֶשָּׁתָא עַל מַדְבְּחָא תְהֵי יָקְדָא בֵיהּ לָא תִטְּפֵי וְיַבְעַר עֲלַהּ כַּהֲנָא אָעַיָּא בִּצְפַר בִּצְפָר וְיַסְדַּר עֲלַּהּ עֲלָתָא וְיַסֵּק עֲלַהּ תַּרְבֵּי נִכְסַת קוּדְשַׁיָּא:",0,0],[6,6,"אֶשָּׁתָא תְּדִירָא תְּהֵי יָקְדָא עַל מַדְבְּחָא לָא תִטְּפֵי:",0,0],[6,7,"וְדָא אוֹרַיְתָא דְּמִנְחָתָא דִּיקָרְבוּן יָתַהּ בְּנֵי אַהֲרֹן קֳדָם יְיָ לָקֳדָם מַדְבְּחָא:",0,0],[6,8,"וְיַפְרֵשׁ מִנֵּיהּ בְּקֻמְצֵיהּ מִסֻּלְתָּא דְמִנְחָתָא וּמִמִּשְׁחַהּ וְיָת כָּל לְבוּנְתָּא דִּי עַל מִנְחָתָא וְיַסֵּק לְמַדְבְּחָא לְאִתְקַבָּלָא בְרַעֲוָא אַדְכַּרְתָּא קֳדָם יְיָ:",0,0],[6,9,"וּדְאִשְׁתָּאַר מִנַּה יֵכְלוּן אַהֲרֹן וּבְנוֹהִי פַּטִּיר תִּתְאָכֵל בַּאֲתַר קַדִּישׁ בְּדָרַת מִשְׁכַּן זִמְנָא יֵכְלֻנַּהּ:",0,0],[6,10,"לָא תִתְאֲפֵי חֲמִיעַ חֳלָקְהוֹן יְהָבִית יָתַהּ מִקֻּרְבָּנָי קֹדֶשׁ קוּדְשִׁין הִיא כְּחַטָּאתָא וְכַאֲשָׁמָא:",0,0],[6,11,"כָּל דְּכוּרָא בִּבְנֵי אַהֲרֹן יֵכְלֻנַּהּ קְיָם עָלָם לְדָרָתֵיכוֹן מִקֻּרְבָּנַיָּא דַיְיָ כֹּל דְּיִקְרַב בְּהוֹן יִתְקַדָּשׁ:",0,0],[6,12,"וּמַלִּיל יְיָ עִם משֶׁה לְמֵימָר:",0,0],[6,13,"דֵּין קֻרְבַּן אַהֲרֹן וּבְנוֹהִי דִּי יְקָרְבוּן קֳדָם יְיָ בְּיוֹמָא דְּרַבִּיאוּ יָתֵיהּ חַד מִן עַסְרָא בִתְלַת סְאִין סֻלְתָּא מִנְחָתָא תְּדִירָא פַּלְגּוּתַהּ בְּצַפְרָא וּפַלְגּוּתַהּ בְּרַמְשָׁא:",0,0],[6,14,"עַל מַסְרֵיתָא בִּמְשַׁח תִּתְעֲבֵד רְבִיכָא תַיְתִנַּהּ תּוּפִינֵי מִנְחַת בִּצּוּעִין תְּקָרֵב לְאִתְקַבָּלָא בְרַעֲוָא קֳדָם יְיָ:",0,0],[6,15,"וְכַהֲנָא דִמְרַבָּא תְחוֹתוֹהִי מִבְּנוֹהִי יַעְבֵּד יָתַהּ קְיָם עָלָם קֳדָם יְיָ גְּמִיר תִּתַּסָּק:",0,0],[6,16,"וְכָל מִנְחָתָא דְכַהֲנָא גְּמִיר תְּהֵי לָא תִתְאֲכֵל:",0,0],[6,17,"וּמַלִּיל יְיָ עִם משֶׁה לְמֵימָר:",0,0],[6,18,"מַלֵּל עִם אַהֲרֹן וְעִם בְּנוֹהִי לְמֵימַר דָּא אוֹרַיְתָא דְּחַטָּאתָא בְּאֲתַר דִּי תִתְנְכֵס עֲלָתָא תִּתְנְכֵס חַטָּאתָא קֳדָם יְיָ קֹדֶשׁ קוּדְשִׁין הִיא:",0,0],[6,19,"כַּהֲנָא דִּמְכַפֵּר בִּדְמַהּ יֵיכְלִנַּהּ בַּאֲתַר קַדִּישׁ תִּתְאֲכֵל בְּדָרַת מַשְׁכַּן זִמְנָא:",0,0],[6,20,"כֹּל דִּי יִקְרַב בְּבִסְרַהּ יִתְקַדַּשׁ וְדִי יַדִּי מִדְּמַהּ עַל לְבוּשׁ דִּי יַדִּי עֲלַהּ תִּתְחַוָּר בַּאֲתַר קַדִּישׁ:",0,0],[6,21,"וּמָן דַּחֲסַף דִּי תִתְבַּשֵּׁל בֵּיהּ יִתָּבָר וְאִם בְּמָנָא דִּנְחָשָׁא תִּתְבַּשֵּׁל וְיִתְמְרֵק וְיִשְׁתַּטֵּף בְּמַיָּא:",0,0],[6,22,"כָּל דְּכוּרָא בְכַהֲנַיָּא יֵכוּל יָתַהּ קֹדֶשׁ קוּדְשִׁין הִיא:",0,0],[6,23,"וְכָל חַטָּאתָא דִּי יִתָּעַל מִדְּמַהּ לְמַשְׁכַּן זִמְנָא לְכַפָּרָא בְקוּדְשָׁא לָא תִתְאֲכֵל בְּנוּרָא תִּתּוֹקָד:",0,0],[7,1,"וְדָא אוֹרַיְתָא דַּאֲשָׁמָא קֹדֶשׁ קוּדְשִׁין הוּא:",0,0],[7,2,"בְאַתְרָא דִּי יִכְּסוּן יָת עֲלָתָא יִכְּסוּן יָת אֲשָׁמָא וְיָת דְּמֵיהּ יִזְרַק עַל מַדְבְּחָא סְחוֹר סְחוֹר:",0,0],[7,3,"וְיָת כָּל תַּרְבֵּיהּ יַפְרֵשׁ מִנֵּיהּ יָת אֲלִיתָא וְיָת תַּרְבָּא דְּחָפֵי יָת גַּוָּא:",0,0],[7,4,"וְיָת תַּרְתֵּין כָּלְיָן וְיָת תַּרְבָּא דִּי עֲלֵיהֶן דִּי עַל גִּסְסַיָּא וְיָת חִצְרָא דְּעַל כַּבְדָּא עַל כָּלְיֵתָא יֶעְדִּנַּהּ:",0,0],[7,5,"וְיַסֵּק יָתְהוֹן כַּהֲנָא לְמַדְבְּחָא קֻרְבָּנָא קֳדָם יְיָ אֲשָׁמָא הוּא:",0,0],[7,6,"כָּל דְּכוּרָא בְכַהֲנַיָּא יֵיכְלִנֵּיהּ בַּאֲתַר קַדִּישׁ יִתְאֲכָל קֹדֶשׁ קוּדְשִׁין הוּא:",0,0],[7,7,"כְּחַטָּאתָא כַּאֲשָׁמָא אוֹרַיְתָא חֲדָא לְהוֹן כַּהֲנָא דִּי יְכַפֵּר בֵּיהּ דִּילֵיהּ יְהֵא:",0,0],[7,8,"וְכַהֲנָא דִּמְקָרֵב יָת עֲלַת גְּבָר מְשַׁךְ עֲלָתָא דִּי יְקָרֵב לְכַהֲנָא דִּילֵיהּ יְהֵא:",0,0],[7,9,"וְכָל מִנְחָתָא דִּי תִתְאֲפֵי בְּתַנּוּרָא וְכָל דְּתִתְעֲבֵד בְּרִדְתָּא וְעַל מַסְרֵיתָא לְכַהֲנָא דִּמְקָרֵב יָתַהּ דִּילֵיהּ תְּהֵא:",0,0],[7,10,"וְכָל מִנְחָתָא דְפִילָא בִמְשַׁח וּדְלָא פִילָא לְכָל בְּנֵי אַהֲרֹן תְּהֵי גְּבַר כְּאָחוֹהִי:",0,0],[7,11,"וְדָא אוֹרַיְתָא דְּנִכְסַת קוּדְשַׁיָּא דִּי יְקָרֵב קֳדָם יְיָ:",0,0],[7,12,"אִם עַל תּוֹדְתָא יְקָרְבִנֵּיהּ וִיקָרֵב עַל נִכְסַת תּוֹדְתָא גְּרִיצָן פַּטִּירָן דְּפִילָן בִּמְשַׁח וְאֶסְפּוֹגִין פַּטִּירִין דִּמְשִׁיחִין בִּמְשָׁח וְסֻלְתָּא רְבִיכָא גְּרִיצָן דְּפִילָן בִּמְשָׁח:",0,0],[7,13,"עַל גְּרִיצָן דִּלְחֵם חֲמִיעַ יְקָרֵב קֻרְבָּנֵיהּ עַל נִכְסַת תּוֹדַת קוּדְשׁוֹהִי:",0,0],[7,14,"וִיקָרֵב מִנֵּיהּ חַד מִכָּל קוּרְבַּן אַפְרָשׁוּתָא קֳדָם יְיָ לְכַהֲנָא דִּיזְרַק יָת דַּם נִכְסַת קוּדְשַׁיָּא דִּילֵיהּ יְהֵי:",0,0],[7,15,"וּבְסַר נִכְסַת תּוֹדַת קוּדְשׁוֹהִי בְּיוֹם קֻרְבָּנֵיהּ יִתְאֲכֵל לָא יַצְנַע מִנֵּיהּ עַד צַפְרָא:",0,0],[7,16,"וְאִם נִדְרָא אוֹ נְדַבְתָּא נִכְסַת קֻרְבְּנֵיהּ בְּיוֹמָא דִּי יְקָרֵב יָת נִכְסְתֵיהּ יִתְאֲכֵל וּבְיוֹמָא דְבַתְרוֹהִי וּדְאִשְׁתָּאַר מִנֵּיהּ יִתְאֲכֵל:",0,0],[7,17,"וּדְאִשְׁתָּאַר מִבְּסַר נִכְסְתָא בְּיוֹמָא תְּלִיתָאָה בְּנוּרָא יִתּוֹקָד:",0,0],[7,18,"וְאִם אִתְאֲכָלָא יִתְאֲכֵל מִבְּסַר נִכְסַת קוּדְשׁוֹהִי בְּיוֹמָא תְלִיתָאָה לָא יְהֵא לְרַעֲוָא דִּמְקָרֵב יָתֵיהּ לָא יִתְחֲשֵׁב לֵיהּ מְרָחָק יְהֵא וֶאֱנַשׁ דְּתֵיכוּל מִנֵּיהּ חוֹבֵיהּ יְקַבֵּל:",0,0],[7,19,"וּבְסַר קוּדְשָׁא דִּי יִקְרַב בְּכָל מְסָאָב לָא יִתְאֲכֵל בְּנוּרָא יִתּוֹקָד וּבְסַר קוּדְשָׁא כָּל דִּי דְכֵי לְקוּדְשָׁא יֵיכוּל בְּסַר קוּדְשָׁא:",0,0],[7,20,"וֶאֱנַשׁ דִּי תֵיכוּל בִּסְרָא מִנִּכְסַת קוּדְשַׁיָּא דִּי קֳדָם יְיָ וְסוֹבְתֵיהּ עֲלוֹהִי וְיִשְׁתֵּיצֵי אֱנָשָׁא הַהִיא מֵעַמַּהּ:",0,0],[7,21,"וֶאֱנַשׁ אֲרֵי תִקְרַב בְּכָל מְסָאָב בְּסוֹאֲבַת אֱנָשָׁא אוֹ בִּבְעִירָא מְסָאֲבָא אוֹ בְּכָל שִׁקְצָא מְסָאָב וְיֵיכוּל מִבְּסַר נִכְסַת קוּדְשַׁיָּא דִּי קֳדָם יְיָ וִישְׁתֵּיצֵי אֱנָשָׁא הַהִיא מֵעַמַּהּ:",0,0],[7,22,"וּמַלִּיל יְיָ עִם משֶׁה לְמֵימָר:",0,0],[7,23,"מַלֵּיל עִם בְּנֵי יִשְׂרָאֵל לְמֵימָר כָּל תְּרַב תּוֹר וְאִמָּר וְעִזָּא לָא תֵיכְלוּן:",0,0],[7,24,"וּתְרַב נְבִילָא וּתְרַב תְּבִירָא יִתְעֲבֵד לְכָל עִבִדְתָּא וּמֵיכַל לָא תֵיכְלֻנֵּיהּ:",0,0],[7,25,"אֲרֵי כָּל דְּיֵכוּל תַּרְבָּא מִן בְּעִירָא דִּי יְקָרְבוּן מִנַּהּ קֻרְבָּנָא קֳדָם יְיָ וְיִשְׁתֵּיצֵי אֱנָשָׁא דִי תֵיכוּל מֵעַמַּהּ:",0,0],[7,26,"וְכָל דְּמָא לָא תֵיכְלוּן בְּכָל מוֹתְבָנֵיכוֹן דְּעוֹפָא וְדִבְעִירָא:",0,0],[7,27,"כָּל אֱנָשָׁא דִי תֵיכוּל כָּל דְּמָא וְיִשְׁתֵּיצֵי אֱנָשָׁא הַהִיא מֵעַמַּהּ:",0,0],[7,28,"וּמַלִּיל יְיָ עִם משֶׁה לְמֵימָר:",0,0],[7,29,"מַלֵּיל עִם בְּנֵי יִשְׂרָאֵל לְמֵימָר דִּמְקָרֵב יָת נִכְסַת קוּדְשׁוֹהִי קֳדָם יְיָ יַיְתִי יָת קֻרְבָּנֵיהּ לָקֳדָם יְיָ מִנִּכְסַת קוּדְשׁוֹהִי:",0,0],[7,30,"יְדוֹהִי תַיְתוּן יָת קֻרְבָּנַיָּא דַיְיָ יָת תַּרְבָּא עַל חֶדְיָא יַיְתִנֵּיהּ יָת חֶדְיָא לַאֲרָמָא יָתֵיהּ אֲרוּמָא קֳדָם יְיָ:",0,0],[7,31,"וְיַסֵּק כַּהֲנָא יָת תַּרְבָּא לְמַדְבְּחָא וִיהֵי חֶדְיָא לְאַהֲרֹן וְלִבְנוֹהִי:",0,0],[7,32,"וְיָת שׁוֹקָא דְיַמִּינָא תִּתְּנוּן אַפְרָשׁוּתָא לְכַהֲנָא מִנִּכְסַת קוּדְשֵׁיכוֹן:",0,0],[7,33,"דִּמְקָרֵב יָת דַּם נִכְסַת קוּדְשַׁיָּא וְיָת תַּרְבָּא מִבְּנֵי אַהֲרֹן דִּילֵיהּ תְּהֵי שׁוֹקָא דְיַמִּינָא לָחֳלָק:",0,0],[7,34,"אֲרֵי יָת חֶדְיָא דַאֲרָמוּתָא וְיָת שׁוֹקָא דְאַפְרָשׁוּתָא נְסֵבִית מִן בְּנֵי יִשְׂרָאֵל מִנִּכְסַת קוּדְשֵׁיהוֹן וִיהָבִית יָתְהוֹן לְאַהֲרֹן כַּהֲנָא וְלִבְנוֹהִי לִקְיָם עָלָם מִן בְּנֵי יִשְׂרָאֵל:",0,0],[7,35,"דָּא רְבוּת אַהֲרֹן וּרְבוּת בְּנוֹהִי מִקֻּרְבָּנַיָּא דַּיְיָ בְּיוֹמָא דִּיְקָרְבוּן יָתְהוֹן לְשַׁמָּשָׁא קֳדָם יְיָ:",0,0],[7,36,"דִּי פַּקִּיד יְיָ לְמִתַּן לְהוֹן בְּיוֹמָא דְּרַבִּי יָתְהוֹן מִן בְּנֵי יִשְׂרָאֵל קְיָם עָלָם לְדָרֵיהוֹן:",0,0],[7,37,"דָּא אוֹרַיְתָא לַעֲלָתָא לְמִנְחָתָא וּלְחַטָּאתָא וְלַאֲשָׁמָא וּלְקֻרְבָּנַיָּא וּלְנִכְסַת קוּדְשַׁיָּא:",0,0],[7,38,"דִּי פַקִּיד יְיָ יָת משֶׁה בְּטוּרָא דְסִינָי בְּיוֹמָא דִפַקְּדֵיהּ יָת בְּנֵי יִשְׂרָאֵל לְקָרָבָא יָת קֻרְבָּנְהוֹן קֳדָם יְיָ בְּמַדְבְּרָא דְסִינָי:",0,0],[8,1,"וּמַלִּיל יְיָ עִם משֶׁה לְמֵימָר:",0,0],[8,2,"קָרֵב יָת אַהֲרֹן וְיָת בְּנוֹהִי עִמֵּיהּ וְיָת לְבוּשַׁיָּא וְיָת מִשְׁחָא דִרְבוּתָא וְיָת תּוֹרָא דְחַטָּאתָא וְיָת תְּרֵין דִּכְרִין וְיָת סַלָּא דְפַטִּירַיָּא:",0,0],[8,3,"וְיָת כָּל כְּנִשְׁתָּא כְּנֵשׁ לִתְרַע מַשְׁכַּן זִמְנָא:",0,0],[8,4,"וַעֲבַד משֶׁה כְּמָא דִי פַּקִּיד יְיָ יָתֵיהּ וְאִתְכְּנִישַׁת כְּנִשְׁתָּא לִתְרַע מַשְׁכַּן זִמְנָא:",0,0],[8,5,"וַאֲמַר משֶׁה לִכְנִשְׁתָּא דֵּין פִּתְגָּמָא דִּי פַקִּיד יְיָ לְמֶעְבָּד:",0,0],[8,6,"וְקָרִיב משֶׁה יָת אַהֲרֹן וְיָת בְּנוֹהִי וְאַסְחֵי יָתְהוֹן בְּמַיָּא:",0,0],[8,7,"וִיהַב עֲלוֹהִי יָת כִּתּוּנָא וְזָרֵז יָתֵיהּ בְּהֶמְיָנָא וְאַלְבֵּשׁ יָתֵיהּ יָת מְעִילָא וִיהַב עֲלוֹהִי יָת אֵפוֹדָא וְזָרֵז יָתֵיהּ בְּהֶמְיַן אֵפוֹדָא וְאַתְקֵן לֵיהּ בֵּיהּ:",0,0],[8,8,"וְשַׁוִּי עֲלוֹהִי יָת חוּשְׁנָא וִיהַב בְּחוּשְׁנָא יָת אוּרַיָּא וְיָת תֻּמַיָּא:",0,0],[8,9,"וְשַׁוִּי יָת מִצְנֶפְתָּא עַל רֵישֵׁיהּ וְשַׁוִּי עַל מִצְנֶפְתָּא לָקֳבֵל אַפּוֹהִי יָת צִיצָא דְדַהֲבָא כְּלִילָא דְקוּדְשָׁא כְּמָא דִי פַקִּיד יְיָ יָת משֶׁה:",0,0],[8,10,"וּנְסִיב משֶׁה יָת מִשְׁחָא דִרְבוּתָא וְרַבִּי יָת מַשְׁכְּנָא וְיָת כָּל דִּי בֵיהּ וְקַדִּישׁ יָתְהוֹן:",0,0],[8,11,"וְאַדִּי מִנֵּיהּ עַל מַדְבְּחָא שְׁבַע זִמְנִין וְרַבִּי יָת מַדְבְּחָא וְיָת כָּל מָנוֹהִי וְיָת כִּיּוֹרָא וְיָת בְּסִיסֵיהּ לְקַדָּשׁוּתְהוֹן:",0,0],[8,12,"וַאֲרִיק מִמִּשְׁחָא דִרְבוּתָא עַל רֵישָׁא דְאַהֲרֹן וְרַבִּי יָתֵיהּ לְקַדָּשׁוּתֵיהּ:",0,0],[8,13,"וְקָרִיב משֶׁה יָת בְּנֵי אַהֲרֹן וְאַלְבֵּשִׁנּוּן כִּתּוּנִין וְזָרֵז יָתְהוֹן הֶמְיָנִין וְאַתְקֵן לְהוֹן כּוֹבָעִין כְּמָא דִי פַקִּיד יְיָ יָת משֶׁה:",0,0],[8,14,"וְקָרֵב יָת תּוֹרָא דְחַטָּאתָא וּסְמַךְ אַהֲרֹן וּבְנוֹהִי יָת יְדֵיהוֹן עַל רֵישׁ תּוֹרָא דְחַטָּאתָא:",0,0],[8,15,"וּנְכֵס וּנְסִיב משֶׁה יָת דְּמָא וִיהַב עַל קַרְנַת מַדְבְּחָא סְחוֹר סְחוֹר בְּאֶצְבְּעֵיהּ וְדַכִּי יָת מַדְבְּחָא וְיָת דְּמָא אֲרִיק לִיסוֹדָא דְמַדְבְּחָא וְקַדְּשֵׁיהּ לְכַפָּרָא עֲלוֹהִי:",0,0],[8,16,"וּנְסִיב יָת כָּל תַּרְבָּא דִּי עַל גַּוָּא וְיָת חֲצַר כַּבְדָּא וְיָת תַּרְתֵּין כָּלְיָן וְיָת תַּרְבְּהֶן וְאַסֵּק משֶׁה לְמַדְבְּחָא:",0,0],[8,17,"וְיָת תּוֹרָא וְיָת מַשְׁכֵּיהּ וְיָת בִּסְרֵיהּ וְיָת אָכְלֵיהּ אוֹקִיד בְּנוּרָא מִבָּרָא לְמַשְׁרִיתָא כְּמָא דִי פַקִּיד יְיָ יָת משֶׁה:",0,0],[8,18,"וְקָרִיב יָת דִּכְרָא דַעֲלָתָא וּסְמָכוּ אַהֲרֹן וּבְנוֹהִי יָת יְדֵיהוֹן עַל רֵישׁ דִּכְרָא:",0,0],[8,19,"וּנְכֵס וּזְרַק משֶׁה יָת דְּמָא עַל מַדְבְּחָא סְחוֹר סְחוֹר:",0,0],[8,20,"וְיָת דִּכְרָא פַּלֵּיג לְאֶבְרוֹהִי וְאַסֵּק משֶׁה יָת רֵישָׁא וְיָת אֵבָרַיָּא וְיָת תַּרְבָּא:",0,0],[8,21,"וְיָת גַּוָּא וְיָת כְּרָעַיָּא חַלִּיל בְּמַיָּא וְאַסֵּק משֶׁה יָת כָּל דִּכְרָא לְמַדְבְּחָא עֲלָתָא הוּא לְאִתְקַבָּלָא בְרַעֲוָא קֻרְבָּנָא הוּא קֳדָם יְיָ כְּמָא דִי פַקִּיד יְיָ יָת משֶׁה:",0,0],[8,22,"וְקָרִיב יָת דִּכְרָא תִנְיָנָא דְּכַר קֻרְבָּנַיָּא וּסְמָכוּ אַהֲרֹן וּבְנוֹהִי יָת יְדֵיהוֹן עַל רֵישׁ דִּכְרָא:",0,0],[8,23,"וּנְכֵס וּנְסִיב משֶׁה מִן דְּמָא וִיהַב עַל רוּם אוּדְנָא דְאַהֲרֹן דְּיַמִּינָא וְעַל אִלְיוֹן יְדֵיהּ דְּיַמִּינָא וְעַל אִלְיוֹן רַגְלֵיהּ דְּיַמִּינָא:",0,0],[8,24,"וְקָרִיב יָת בְּנֵי אַהֲרֹן וִיהַב משֶׁה מִן דְּמָא עַל רוּם אוּדְנֵהוֹן דְּיַמִּינָא וְעַל אִלְיוֹן יְדֵיהוֹן דְּיַמִּינָא וְעַל אִלְיוֹן רַגְלֵהוֹן דְּיָמִּינָא וּזְרַק משֶׁה יָת דְּמָא עַל מַדְבְּחָא סְחוֹר סְחוֹר:",0,0],[8,25,"וּנְסִיב יָת תַּרְבָּא וְיָת אֲלִיתָא וְיָת כָּל תַּרְבָּא דִּי עַל גַּוָּא וְיָת חֲצַר כַּבְדָּא וְיָת תַּרְתֵּין כָּלְיָן וְיָת תַּרְבְּהֶן וְיָת שׁוֹקָא דְיַמִּינָא:",0,0],[8,26,"וּמִסַּלָּא דְפַטִּירַיָּא דִּי קֳדָם יְיָ נְסִיב גְּרִצְתָּא פַטִּירָא חֲדָא וּגְרִצְתָּא דִלְחֵם מְשַׁח חֲדָא וְאֶסְפּוֹג חָד וְשַׁוִּי עַל תַּרְבַּיָּא וְעַל שׁוֹקָא דְיַמִּינָא:",0,0],[8,27,"וִיהַב יָת כֹּלָּא עַל יְדֵי אַהֲרֹן וְעַל יְדֵי בְנוֹהִי וַאֲרֵם יָתְהוֹן אֲרָמָא קֳדָם יְיָ:",0,0],[8,28,"וּנְסִיב משֶׁה יָתְהוֹן מֵעַל יְדֵיהוֹן וְאַסֵּק לְמַדְבְּחָא עַל עֲלָתָא קֻרְבָּנַיָּא אִנּוּן לְאִתְקַבָּלָא בְרַעֲוָא קֻרְבָּנָא הוּא קֳדָם יְיָ:",0,0],[8,29,"וּנְסִיב משֶׁה יָת חֶדְיָא וַאֲרִימֵיהּ אֲרָמָא קֳדָם יְיָ מִדְּכַר קֻרְבָּנַיָּא לְמשֶׁה הֲוָה לָחֳלָק כְּמָא דִי פַקִּיד יְיָ יָת משֶׁה:",0,0],[8,30,"וּנְסִיב משֶׁה מִמִּשְׁחָא דִרְבוּתָא וּמִן דְּמָא דִּי עַל מַדְבְּחָא וְאַדִּי עַל אַהֲרֹן עַל לְבוּשׁוֹהִי וְעַל בְּנוֹהִי וְעַל לְבוּשֵׁי בְנוֹהִי עִמֵּיהּ וְקַדִּישׁ יָת אַהֲרֹן יָת לְבוּשׁוֹהִי וְיָת בְּנוֹהִי וְיָת לְבוּשֵׁי בְנוֹהִי עִמֵּיהּ:",0,0],[8,31,"וַאֲמַר משֶׁה לְאַהֲרֹן וְלִבְנוֹהִי בַּשִּׁילוּ יָת בִּסְרָא בִּתְרַע מַשְׁכַּן זִמְנָא וְתַמָּן תֵּיכְלוּן יָתֵיהּ וְיָת לַחְמָא דִּי בְּסַל קֻרְבָּנַיָּא כְּמָא דִי פַקֵּדִית לְמֵימַר אַהֲרֹן וּבְנוֹהִי יֵיכְלֻנֵּיהּ:",0,0],[8,32,"וּדְאִשְׁתָּאַר בְּבִשְׂרָא וּבְלַחְמָא בְּנוּרָא תּוֹקְדוּן:",0,0],[8,33,"וּמִתְּרַע מַשְׁכַּן זִמְנָא לָא תִפְּקוּן שִׁבְעָא יוֹמִין עַד יוֹם מִשְׁלַם יוֹמֵי קֻרְבָּנֵיכוֹן אֲרֵי שִׁבְעָא יוֹמִין יְקָרֵב יָת קֻרְבָּנְכוֹן:",0,0],[8,34,"כְּמָא דִי עֲבַד בְּיוֹמָא הָדֵין פַּקִּיד יְיָ לְמֶעְבַּד לְכַפָּרָא עֲלֵיכוֹן:",0,0],[8,35,"וּבִתְרַע מַשְׁכַּן זִמְנָא תֵּיתְבוּן יְמָם וְלֵילֵי שִׁבְעָא יוֹמִין וְתִטְּרוּן יָת מַטְּרַת מֵימְרָא דַיְיָ וְלָא תְמוּתוּן אֲרֵי כֵן אִתְפַּקָּדִית:",0,0],[8,36,"וַעֲבַד אַהֲרֹן וּבְנוֹהִי יָת כָּל פִּתְגָּמַיָּא דִּי פַקִּיד יְיָ בִּידָא דְמשֶׁה:",0,0],[9,1,"וַהֲוָה בְּיוֹמָא תְמִינָאָה קְרָא משֶׁה לְאַהֲרֹן וְלִבְנוֹהִי וּלְסָבֵי יִשְׂרָאֵל:",0,0],[9,2,"וַאֲמַר לְאַהֲרֹן סַב לָךְ עֶגַל בַּר תּוֹרֵי לְחַטָּאתָא וּדְכַר לַעֲלָתָא שַׁלְמִין וְקָרֵב קֳדָם יְיָ:",0,0],[9,3,"וְעִם בְּנֵי יִשְׂרָאֵל תְּמַלֵּל לְמֵימָר סִיבוּ צְפִיר בַּר עִזִּין לְחַטָּאתָא וְעֵגָל וְאִמָּר בְּנֵי שְׁנָא שַׁלְמִין לַעֲלָתָא:",0,0],[9,4,"וְתוֹר וּדְכָר לְנִכְסַת קוּדְשַׁיָּא לְדַבָּחָא קֳדָם יְיָ וּמִנְחָתָא דְּפִילָא בִמְשָׁח אֲרֵי יוֹמָא דֵין יְקָרָא דַיְיָ מִתְגְּלִי לְכוֹן:",0,0],[9,5,"וּנְסִיבוּ יָת דִּי פַקִּיד משֶׁה לָקֳדָם מַשְׁכַּן זִמְנָא וּקְרִיבוּ כָּל כְּנִשְׁתָּא וְקָמוּ קֳדָם יְיָ:",0,0],[9,6,"וַאֲמַר משֶׁה דֵּין פִּתְגָּמָא דִּי פַקִּיד יְיָ תַּעְבְּדוּן וְיִתְגְּלִי לְכוֹן יְקָרָא דַיְיָ:",0,0],[9,7,"וַאֲמַר משֶׁה לְאַהֲרֹן קְרַב לְמַדְבְּחָא וְעִבֵד יָת חַטָּאתָךְ וְיָת עֲלָתָךְ וְכַפַּר עֲלָךְ וְעַל עַמָּא וְעִבֵד יָת קֻרְבַּן עַמָּא וְכַפַּר עֲלֵיהוֹן כְּמָא דִי פַּקִּיד יְיָ:",0,0],[9,8,"וּקְרֵב אַהֲרֹן לְמַדְבְּחָא וּנְכֵס יָת עֶגְלָא דְחַטָּאתָא דִּי לֵיהּ:",0,0],[9,9,"וְקָרִיבוּ בְּנֵי אַהֲרֹן יָת דְּמָא לֵיהּ וּטְבַל אֶצְבְּעֵיהּ בִּדְמָא וִיהַב עַל קַרְנַת מַדְבְּחָא וְיָת דְּמָא אֲרִיק לִיסוֹדָא דְמַדְבְּחָא:",0,0],[9,10,"וְיָת תַּרְבָּא וְיָת כָּלְיְתָא וְיָת חִצְרָא מִן כַּבְדָּא מִן חַטָּאתָא אַסֵּק לְמַדְבְּחָא כְּמָא דִי פַּקִּיד יְיָ יָת משֶׁה:",0,0],[9,11,"וְיָת בִּשְׂרָא וְיָת מַשְׁכָּא אוֹקִיד בְּנוּרָא מִבָּרָא לְמַשְׁרִיתָא:",0,0],[9,12,"וּנְכֵס יָת עֲלָתָא וְאַמְטִיאוּ בְּנֵי אַהֲרֹן לֵיהּ יָת דְּמָא וּזְרָקֵיהּ עַל מַדְבְּחָא סְחוֹר סְחוֹר:",0,0],[9,13,"וְיָת עֲלָתָא אַמְטִיאוּ לֵיהּ לְאֵבָרָהָא וְיָת רֵישָׁא וְאַסֵּק עַל מַדְבְּחָא:",0,0],[9,14,"וְחַלִּיל יָת גַּוָּא וְיָת כְּרָעַיָּא וְאַסֵּק עַל עֲלָתָא לְמַדְבְּחָא:",0,0],[9,15,"וְקָרֵב יָת קֻרְבַּן עַמָּא וּנְסִיב יָת צְפִירָא דְחַטָּאתָא דִּי לְעַמָּא וְנָכְסֵיהּ וְכַפֵּר בִּדְמֵיהּ כְּקַדְמָאָה:",0,0],[9,16,"וְקָרֵב יָת עֲלָתָא וְעָבְדַהּ כִּדְחָזֵי:",0,0],[9,17,"וְקָרֵב יָת מִנְחָתָא וּמְלָא יְדֵיהּ מִנַּהּ וְאַסֵּק עַל מַדְבְּחָא בַּר מֵעֲלַת צַפְרָא:",0,0],[9,18,"וּנְכֵס יָת תּוֹרָא וְיָת דִּכְרָא נִכְסַת קוּדְשַׁיָּא דִּי לְעַמָּא וְאַמְטִיאוּ בְּנֵי אַהֲרֹן יָת דְּמָא לֵיהּ וּזְרָקֵיהּ עַל מַדְבְּחָא סְחוֹר סְחוֹר:",0,0],[9,19,"וְיָת תַּרְבַּיָּא מִן תּוֹרָא וּמִן דִּכְרָא אֲלִיתָא וְחָפֵי גַוָּא וְכָלְיְתָא וַחֲצַר כַּבְדָּא:",0,0],[9,20,"וְשַׁוִּיאוּ יָת תַּרְבַּיָּא עַל חֶדְוָתָא וְאַסֵּק תַּרְבַּיָּא לְמַדְבְּחָא:",0,0],[9,21,"וְיָת חֶדְוָתָא וְיָת שׁוֹקָא דְיַמִּינָא אֲרֵם אַהֲרֹן אֲרָמָא קֳדָם יְיָ כְּמָא דִי פַּקִּיד משֶׁה:",0,0],[9,22,"וַאֲרֵם אַהֲרֹן יָת יְדוֹהִי עַל עַמָּא וּבָרֵכִנּוּן וּנְחַת מִלְּמֶעְבַּד חַטָּאתָא וַעֲלָתָא וְנִכְסַת קוּדְשַׁיָּא:",0,0],[9,23,"וְעַל משֶׁה וְאַהֲרֹן לְמַשְׁכַּן זִמְנָא וּנְפָקוּ וּבָרִיכוּ יָת עַמָּא וְאִתְגְּלִי יְקָרָא דַיְיָ לְכָל עַמָּא:",0,0],[9,24,"וּנְפָקַת אֶשָּׁתָא מִן קֳדָם יְיָ וַאֲכָלַת עַל מַדְבְּחָא יָת עֲלָתָא וְיָת תַּרְבַּיָּא וַחֲזָא כָּל עַמָּא וְשַׁבָּחוּ וּנְפָלוּ עַל אַפֵּיהוֹן:",0,0],[10,1,"וּנְסִיבוּ בְנֵי אַהֲרֹן נָדָב וַאֲבִיהוּא גְּבַר מַחְתִּיתֵיהּ וִיהָבוּ בְהוֹן אֶשָּׁתָא וְשַׁוִּיאוּ עֲלַהּ קְטוֹרֶת וְקָרִיבוּ קֳדָם יְיָ אֶשָּׁתָא נוּכְרֵיתָא דִּי לָא פַּקִּיד יָתְהוֹן:",0,0],[10,2,"וּנְפָקַת אֶשָּׁתָא מִן קֳדָם יְיָ וַאֲכָלַת יָתְהוֹן וּמִיתוּ קֳדָם יְיָ:",0,0],[10,3,"וַאֲמַר משֶׁה לְאַהֲרֹן הוּא דִי מַלִּיל יְיָ לְמֵימַר בְּקָרִיבַי אִתְקַדַּשׁ וְעַל אַפֵּי כָל עַמָּא אִתְיַקָּר וּשְׁתִיק אַהֲרֹן:",0,0],[10,4,"וּקְרָא משֶׁה לְמִישָׁאֵל וּלְאֶלְצָפָן בְּנֵי עֻזִּיאֵל אַח אֲבוּהִי דְאַהֲרֹן וַאֲמַר לְהוֹן קְרִיבוּ טוּלוּ יָת אֲחוּכוֹן מִן קֳדָם אַפֵּי קוּדְשָׁא לְמִבָּרָא לְמַשְׁרִיתָא:",0,0],[10,5,"וּקְרִיבוּ וּנְטָלֻנּוּן בְּכִתֻּנֵּיהוֹן לְמִבָּרָא לְמַשְׁרִיתָא כְּמָא דִי מַלִּיל משֶׁה:",0,0],[10,6,"וַאֲמַר משֶׁה לְאַהֲרֹן וּלְאֶלְעָזָר וּלְאִיתָמָר בְּנוֹהִי רֵישֵׁיכוֹן לָא תְרַבּוּן פֵּרוּעַ וּלְבוּשֵׁיכוֹן לָא תְבַזְּעוּן וְלָא תְמוּתוּן וְעַל כָּל כְּנִשְׁתָּא יְהֵי רוּגְזָא וַאֲחֵיכוֹן כָּל בֵּית יִשְׂרָאֵל יִבְכּוּן יָת יְקִדְתָּא דִּי אוֹקִיד יְיָ:",0,0],[10,7,"וּמִתְּרַע מַשְׁכַּן זִמְנָא לָא תִפְּקוּן דִּילְמָא תְמוּתוּן אֲרֵי מְשַׁח רְבוּתָא דַיְיָ עֲלֵיכוֹן וַעֲבָדוּ כְּפִתְגָּמָא דְמשֶׁה:",0,0],[10,8,"וּמַלִּיל יְיָ לְאַהֲרֹן לְמֵימָר:",0,0],[10,9,"חֲמַר וּמְרַוֵּי לָא תִשְׁתֵּי אַתְּ וּבְנָיךְ עִמָּךְ בְּמֵעַלְכוֹן לְמַשְׁכַּן זִמְנָא וְלָא תְמוּתוּן קְיַם עָלָם לְדָרֵיכוֹן:",0,0],[10,10,"וּלְאַפְרָשָׁא בֵּין קוּדְשָׁא וּבֵין חֻלָּא וּבֵין מְסָאָבָא וּבֵין דַּכְיָא:",0,0],[10,11,"וּלְאַלָּפָא יָת בְּנֵי יִשְׂרָאֵל יָת כָּל קְיָמַיָּא דִּי מַלִּיל יְיָ לְהוֹן בִּידָא דְמשֶׁה:",0,0],[10,12,"וּמַלִּיל משֶׁה עִם אַהֲרֹן וְעִם אֶלְעָזָר וְעִם אִיתָמָר בְּנוֹהִי דְּאִשְׁתָּאֲרוּ סִיבוּ יָת מִנְחָתָא דְאִשְׁתָּאָרַת מִקֻּרְבָּנַיָּא דַיְיָ וְאִכְלוּהָ פַטִּיר בִּסְטַר מַדְבְּחָא אֲרֵי קֹדֶשׁ קוּדְשִׁין הִיא:",0,0],[10,13,"וְתֵיכְלוּן יָתַהּ בַּאֲתַר קַדִּישׁ אֲרֵי חֳלָקָךְ וָחֳלַק בְּנָיךְ הִיא מִקֻּרְבָּנַיָּא דַּיְיָ אֲרֵי כֵן אִתְפַּקָּדִית:",0,0],[10,14,"וְיָת חֶדְיָא דַאֲרָמוּתָא וְיָת שׁוֹקָא דְאַפְרָשׁוּתָא תֵּיכְלוּן בַּאֲתַר דְּכֵי אַתְּ וּבְנָיךְ וּבְנָתָיךְ עִמָּךְ אֲרֵי חֳלָקָךְ וָחֳלַק בְּנָיךְ אִתְיְהִבוּ מִנִּכְסַת קוּדְשַׁיָּא דִּבְנֵי יִשְׂרָאֵל:",0,0],[10,15,"שׁוֹקָא דְאַפְרָשׁוּתָא וְחֶדְיָא דַאֲרָמוּתָא עַל קֻרְבָּנֵי תַרְבַּיָּא יַיְתוּן לַאֲרָמָא אֲרָמָא קֳדָם יְיָ וִיהֵי לָךְ וְלִבְנָיךְ עִמָּךְ לִקְיַם עָלָם כְּמָא דִי פַּקִּיד יְיָ:",0,0],[10,16,"וְיָת צְפִירָא דְחַטָּתָא מִתְבַּע תָּבְעֵי משֶׁה וְהָא אִתּוֹקָד וּרְגֵז עַל אֶלְעָזָר וְעַל אִיתָמָר בְּנֵי אַהֲרֹן דְּאִשְׁתָּאָרוּ לְמֵימָר:",0,0],[10,17,"מָדֵין לָא אֲכַלְתּוּן יָת חַטָּאתָא בַּאֲתַר קַדִּישׁ אֲרֵי קֹדֶשׁ קוּדְשִׁין הִיא וְיָתַהּ יָהֵב לְכוֹן לְסַלָּחָא עַל חוֹבֵי כְנִשְׁתָּא לְכַפָּרָא עַלֵיהוֹן קֳדָם יְיָ:",0,0],[10,18,"הָא לָא אִתָּעַל יָת דְּמַהּ לְבֵית קֻדְשָׁא גַּוָּאָה מֵיכַל תֵּיכְלוּן יָתַהּ בְּקֻדְשָׁא כְּמָא דִי פַקֵּדִית:",0,0],[10,19,"וּמַלִּיל אַהֲרֹן עִם משֶׁה הָא יוֹמָא דֵין קָרִיבוּ יָת חַטָּאתְהוֹן וְיָת עֲלָתְהוֹן קֳדָם יְיָ וַעֲרָעָא יָתִי עָקָן כְּאִלֵּין וְאִלּוּפוֹן אֲכָלִית חַטָּאתָא יוֹמָא דֵין הֲתַקֵּן קֳדָם יְיָ:",0,0],[10,20,"וּשְׁמַע משֶׁה וּשְׁפַר בְּעֵינוֹהִי:",0,0],[11,1,"וּמַלִּיל יְיָ עִם משֶׁה וּלְאַהֲרֹן לְמֵימַר לְהוֹן:",0,0],[11,2,"מַלִּילוּ עִם בְּנֵי יִשְׂרָאֵל לְמֵימָר דָּא חַיְתָא דִּי תֵיכְלוּן מִכָּל בְּעִירָא דִּי עַל אַרְעָא:",0,0],[11,3,"כָּל דִּי סְדִיקָן פַּרְסָתָא וּמַטִּלְפָן טִלְפִין פַּרְסָתָא מַסְּקָא פִשְׁרָא בִּבְעִירָא יָתַהּ תֵּיכְלוּן:",0,0],[11,4,"בְּרַם יָת דֵּין לָא תֵיכְלוּן מִמַּסְּקֵי פִשְׁרָא וּמִמַּסְדִּיקֵי פַּרְסָתָא יָת גַּמְלָא אֲרֵי מַסִּיק פִּשְׁרָא הוּא וּפַרְסָתָא לָא סְדִיקָא מְסָאָב הוּא לְכוֹן:",0,0],[11,5,"וְיָת טַפְזָא אֲרֵי מַסִּיק פִּשְׁרָא הוּא וּפַרְסָתָא לָא סְדִיקָא מְסָאָב הוּא לְכוֹן:",0,0],[11,6,"וְיָת אַרְנְבָא אֲרֵי מַסְּקָא פִשְׁרָא הִיא וּפַרְסָתָא לָא סְדִיקָא מְסָאָבָא הִיא לְכוֹן:",0,0],[11,7,"וְיָת חֲזִירָא אֲרֵי סְדִיק פַּרְסָתָא הוּא וּמַטִּילְפָן טִלְפִין פַּרְסָתֵיהּ וְהוּא פִּשְׁרָא לָא פָשָׁר מְסָאָב הוּא לְכוֹן:",0,0],[11,8,"מִבִּסְרְהוֹן לָא תֵיכְלוּן וּבִנְבִלְתְּהוֹן לָא תִקְרְבוּן מְסַאֲבִין אִנּוּן לְכוֹן:",0,0],[11,9,"יָת דֵּין תֵּיכְלוּן מִכָּל דִּי בְמַיָּא כֹּל דִּי לֵיהּ צִיצִין וְקַלְפִין בְּמַיָּא בְּיָמְמַיָּא וּבְנַחֲלַיָּא יָתְהוֹן תֵּיכְלוּן:",0,0],[11,10,"וְכֹל דִּי לֵית לֵיהּ צִיצִין וְקַלְפִין בְּיַמְמַיָּא וּבְנַחֲלַיָּא מִכֹּל רִחֲשָׁא דְמַיָּא וּמִכָּל נַפְשָׁא חַיְתָא דִּי בְמַיָּא שִׁקְצָא אִנּוּן לְכוֹן:",0,0],[11,11,"וְשִׁקְצָא יְהוֹן לְכוֹן מִבִּסְרְהוֹן לָא תֵיכְלוּן וְיָת נְבִלְתְּהוֹן תְּשַׁקְּצוּן:",0,0],[11,12,"כֹּל דִּי לֵית לֵיהּ צִיצִין וְקַלְפִין בְּמַיָּא שִׁקְצָא הוּא לְכוֹן:",0,0],[11,13,"וְיָת אִלֵּין תַּשַׁקְּצוּן מִן עוֹפָא לָא יִתְאַכְלוּן שִׁקְצָא אִנּוּן נִשְׁרָא וְעַר וְעַזְיָא:",0,0],[11,14,"וְדַיְתָא וְטָרָפִיתָא לִזְנַהּ:",0,0],[11,15,"יָת כָּל עוּרְבָא לִזְנֵיהּ:",0,0],[11,16,"וְיָת בַּת נַעֲמִיתָא וְצִיצָא וְצִפַּר שַׁחְפָּא וְנָצָא לִזְנוֹהִי:",0,0],[11,17,"וְקַרְיָא וְשָׁלֵינוּנָא וְקִפּוֹפָא:",0,0],[11,18,"וּבַוְתָא וְקָאתָא וִירַקְרֵקָא:",0,0],[11,19,"וְחַוָּרִיתָא וְאִבּוּ לִזְנַהּ וְנַגַּר טוּרָא וַעֲטַלֵּפָא:",0,0],[11,20,"כֹּל רִחֲשָׁא דְעוֹפָא דִּמְהַלֵּךְ עַל אַרְבַּע שִׁקְצָא הוּא לְכוֹן:",0,0],[11,21,"בְּרַם יָת דֵּין תֵּיכְלוּן מִכֹּל רִחֲשָׁא דְעוֹפָא דִּמְהַלֵּךְ עַל אַרְבַּע דִּי לֵיהּ קַרְצוּלִין מֵעִלָּוֵי רַגְלוֹהִי לְקַפָּצָא בְהוֹן עַל אַרְעָא:",0,0],[11,22,"יָת אִלֵּין מִנְּהוֹן תֵּיכְלוּן יָת גּוֹבָא לִזְנַהּ וְיָת רָשׁוּנָא לִזְנוֹהִי וְיָת חַרְגּוֹלָא לִזְנוֹהִי וְיָת חֲגָבָא לִזְנוֹהִי:",0,0],[11,23,"וְכֹל רִחֲשָׁא דְעוֹפָא דִּי לֵיהּ אַרְבַּע רַגְלִין שִׁקְצָא הוּא לְכוֹן:",0,0],[11,24,"וּלְאִלֵּין תִּסְתָּאָבוּן כָּל דְּיִקְרַב בִּנְבִלְתְּהוֹן יְהֵי מְסָאָב עַד רַמְשָׁא:",0,0],[11,25,"וְכָל דְּיִטוֹל מִנְּבִלְתְּהוֹן יְצַבַּע לְבוּשׁוֹהִי וִיהֵי מְסָאָב עַד רַמְשָׁא:",0,0],[11,26,"לְכָל בְּעִירָא דִּי הִיא סְדִיקָא פַרְסָתָא וְטִלְפִין לֵיתָהָא מַטִּלְפָא וּפִשְׁרָא לֵיתָהָא מַסְּקָא מְסַאֲבִין אִנּוּן לְכוֹן כָּל דְּיִקְרַב בְּהוֹן יְהֵי מְסָאָב:",0,0],[11,27,"וְכֹל דִּמְהַלֵּךְ עַל יְדוֹהִי בְּכָל חַיְתָא דִּמְהַלְכָא עַל אַרְבַּע מְסַאֲבִין אִנּוּן לְכוֹן כָּל דְּיִקְרַב בִּנְבִלְתְּהוֹן יְהֵי מְסָאָב עַד רַמְשָׁא:",0,0],[11,28,"וּדְיִטּוֹל יָת נְבִלְתְּהוֹן יְצַבַּע לְבוּשׁוֹהִי וִיהֵי מְסָאָב עַד רַמְשָׁא מְסַאֲבִין אִנּוּן לְכוֹן:",0,0],[11,29,"וְדֵין לְכוֹן מְסָאָבָא בְּרִחֲשָׁא דְּרָחֵשׁ עַל אַרְעָא חֻלְדָא וְעַכְבָּרָא וְצָבָא לִזְנוֹהִי:",0,0],[11,30,"וְיָלָא וְכֹחָא וְחֻלְטֵיתָא וְחֻמְטָא וְאָשׁוּתָא:",0,0],[11,31,"אִלֵּין דִּמְסַאֲבִין לְכוֹן בְּכָל רִחֲשָׁא כָּל דְּיִקְרַב בְּהוֹן בְּמוֹתְהוֹן יְהֵי מְסָאָב עַד רַמְשָׁא:",0,0],[11,32,"וְכֹל דִּי יִפֵּל עֲלוֹהִי מִנְּהוֹן בְּמוֹתְהוֹן יְהֵי מְסָאָב מִכָּל מָאן דְּאָעָא אוֹ לְבוּשׁ אוֹ מְשַׁךְ אוֹ שָׂק כָּל מָאן דִּי תִתְעֲבֵד עִבִידָא בְּהוֹן בְּמַיָּא יִתָּעַל וִיהֵי מְסָאָב עַד רַמְשָׁא וְיִדְכֵּי:",0,0],[11,33,"וְכָל מָאן דַּחֲסַף דִּי יִפֵּל מִנְּהוֹן לְגַוֵּיהּ כֹּל דִּי בְגַוֵּיהּ יִסְתָּאַב וְיָתֵיהּ תְּתַבְּרוּן:",0,0],[11,34,"מִכָּל מֵיכְלָא דְּמִתְאֲכֵל דִּי יַעֲלוּן עֲלוֹהִי מַיָּא יְהֵי מְסָאָב וְכָל מַשְׁקֵה דִי יִשְׁתֵּתֵי בְּכָל מָאן יְהֵי מְסָאָב:",0,0],[11,35,"וְכֹל דִּי יִפֵּל מִנְּבִלְתְּהוֹן עֲלוֹהִי יְהֵי מְסָאָב תַּנּוּר וְכִירַיִם יִתָּרְעוּן מְסַאֲבִין אִנּוּן וּמְסַאֲבִין יְהוֹן לְכוֹן:",0,0],[11,36,"בְּרַם מַעְיָן וְגוֹב בֵּית כְּנִישׁוּת מַיָּא יְהֵי דְכֵי וּדְיִקְרַב בִּנְבִלְתְּהוֹן יְהֵי מְסָאָב:",0,0],[11,37,"וַאֲרֵי יִפֵּל מִנְּבִלְתְּהוֹן עַל כָּל בַּר זְרַע זֵרוּעַ דִּי יִזְדְּרָע דְּכֵי הוּא:",0,0],[11,38,"וַאֲרֵי יִתְיַהֲבוּן מַיָּא עַל בַּר זַרְעָא וְיִפֵּל מִנְּבִלְתְּהוֹן עֲלוֹהִי מְסָאָב הוּא לְכוֹן:",0,0],[11,39,"וַאֲרֵי יְמוּת מִן בְּעִירָא דִּי הִיא לְכוֹן לְמֵיכָל דְּיִקְרַב בִּנְבִלְתַּהּ יְהֵי מְסָאָב עַד רַמְשָׁא:",0,0],[11,40,"וּדְיֵכוּל מִנְּבִלְתַּהּ יְצַבַּע לְבוּשׁוֹהִי וִיהֵי מְסָאָב עַד רַמְשָׁא וּדְיִטּוֹל יָת נְבִלְתַּהּ יְצַבַּע לְבוּשׁוֹהִי וִיהֵי מְסָאָב עַד רַמְשָׁא:",0,0],[11,41,"וְכָל רִחֲשָׁא דְּרָחֵשׁ עַל אַרְעָא שִׁקְצָא הוּא לָא יִתְאָכֵל:",0,0],[11,42,"כֹּל דִּמְהַלֵּךְ עַל מְעוֹהִי וְכֹל דִּמְהַלֵּךְ עַל אַרְבַּע עַד כָּל סְגִיאוּת רַגְלָאִין לְכָל רִחֲשָׁא דְּרָחֵשׁ עַל אַרְעָא לָא תֵיכְלֻנּוּן אֲרֵי שִׁקְצָא אִנּוּן:",0,0],[11,43,"לָא תְשַׁקְּצוּ יָת נַפְשָׁתֵיכוֹן בְּכָל רִחֲשָׁא דְּרָחֵשׁ וְלָא תִסְתַּאֲבוּן בְּהוֹן וְתִסְתַּאֲבוּן פּוֹן בְּהוֹן:",0,0],[11,44,"אֲרֵי אֲנָא יְיָ אֱלָהָכוֹן וְתִתְקַדְּשׁוּן וּתְהוֹן קַדִּישִׁין אֲרֵי קַדִּישׁ אֲנָא וְלָא תְסַאֲבוּן יָת נַפְשָׁתֵיכוֹן בְּכָל רִחֲשָׁא דְּרָחֵשׁ עַל אַרְעָא:",0,0],[11,45,"אֲרֵי אֲנָא יְיָ דְּאַסֵּק יָתְכוֹן מֵאַרְעָא דְמִצְרַיִם לְמֶהֱוֵי לְכוֹן לֶאֱלָהּ וּתְהוֹן קַדִּישִׁין אֲרֵי קַדִּישׁ אֲנָא:",0,0],[11,46,"דָּא אוֹרַיְתָא דִבְעִירָא וּדְעוֹפָא וּדְכֹל נַפְשָׁתָא חַיְתָא דִּרְחֵשָׁא בְּמַיָּא וּלְכָל נַפְשָׁא דִּרְחֵשָׁא עַל אַרְעָא:",0,0],[11,47,"לְאַפְרָשָׁא בֵּין מְסָאָבָא וּבֵין דַּכְיָא וּבֵין חַיְתָא דְּמִתְאַכְלָא וּבֵין חַיְתָא דִּי לָא מִתְאַכְלָא:",0,0],[12,1,"וּמַלִּיל יְיָ עִם משֶׁה לְמֵימָר:",0,0],[12,2,"מַלֵּיל עִם בְּנֵי יִשְׂרָאֵל לְמֵימַר אִתְּתָא אֲרֵי תְעַדִּי וּתְלִיד דְּכָר וּתְהֵי מְסָאָבָא שִׁבְעַת יוֹמִין כְּיוֹמֵי רִחוּק סוֹבְתַהּ תְּהֵי מְסָאָבָא:",0,0],[12,3,"וּבְיוֹמָא תְּמִינָאָה יִגְזַר בִּסְרָא דְעָרְלְתֵיהּ:",0,0],[12,4,"וּתְלָתִין וּתְלָתָא יוֹמִין תֵּיתֵב בְּדַם דְּכוּ בְּכָל קוּדְשָׁא לָא תִקְרַב וּלְמִקְדְּשָׁא לָא תֵעוֹל עַד מִשְׁלַם יוֹמֵי דָכוּתַהּ:",0,0],[12,5,"וְאִם נְקוּבְתָא תְלִיד וּתְהֵי מְסָאָבָא אַרְבְּעָה עֲסַר כְּרִחוּקַהּ וְשִׁתִּין וְשִׁתָּא יוֹמִין תֵּיתֵב עַל דַּם דְּכוּ:",0,0],[12,6,"וּבְמִשְׁלַם יוֹמֵי דָכוּתַהּ לִבְרָא אוֹ לִבְרַתָּא תַּיְתִי אִמָּר בַּר שַׁתֵּיהּ לַעֲלָתָא וּבַר יוֹנָה אוֹ שַׁפְנִינָא לְחַטָּאתָא לִתְרַע מַשְׁכַּן זִמְנָא לְוָת כַּהֲנָא:",0,0],[12,7,"וִיקָרְבִנֵּיהּ קֳדָם יְיָ וִיכַפֵּר עֲלַהּ וְתִדְכֵּי מִסּוֹאֲבַת דְּמָהָא דָּא אוֹרַיְתָא דְיַלֶּדְתָּא לְדוּכְרָא אוֹ לִנְקֻבְתָא:",0,0],[12,8,"וְאִם לָא תַשְׁכַּח יְדַהּ כְּמִסַּת אִמְּרָא וְתִסַּב תַּרְתֵּין שַׁפְנִינִין אוֹ תְרֵין בְּנֵי יוֹנָה חַד לַעֲלָתָא וְחַד לְחַטָּאתָא וִיכַפֵּר עֲלַהּ כַּהֲנָא וְתִדְכֵּי:",0,0],[13,1,"וּמַלִּיל יְיָ עִם משֶׁה וְעִם אַהֲרֹן לְמֵימָר:",0,0],[13,2,"אֱנַשׁ אֲרֵי יְהֵי בִמְשַׁךְ בִּסְרֵיהּ עַמְקָא אוֹ עַדְיָא אוֹ בַהֲרָא וִיהֵי בִמְשַׁךְ בִּסְרֵיהּ לְמַכְתַּשׁ סְגִירוּ וְיִתֵּתֵי לְוָת אַהֲרֹן כַּהֲנָא אוֹ לְוָת חַד מִבְּנוֹהִי כָּהֲנַיָּא:",0,0],[13,3,"וֶיֶחֱזֵי כַהֲנָא יָת מַכְתָּשָׁא בִמְשַׁךְ בִּסְרָא וְשֵׂעָר בְּמַכְתָּשָׁא אִתְהֲפִיךְ לְמֶחֱוָר וּמֶחֱזֵי מַכְתָּשָׁא עַמִּיק בִּמְשַׁךְ בִּסְרֵיהּ מַכְתַּשׁ סְגִירוּתָא הוּא וְיֶחֱזִנֵּיהּ כַּהֲנָא וִיסָאֵב יָתֵיהּ:",0,0],[13,4,"וְאִם בַּהֲרָא חַוְּרָא הִיא בִּמְשַׁךְ בִּסְרֵיהּ וְעַמִּיק לֵית מֶחֱזָהָא מִן מַשְׁכָא וּשְׂעָרָא לָא אִתְהֲפִיךְ לְמֶחֱוָר וְיַסְגַּר כַּהֲנָא יָת מַכְתָּשָׁא שִׁבְעָא יוֹמִין:",0,0],[13,5,"וְיֶחֱזִנֵּיהּ כַּהֲנָא בְּיוֹמָא שְׁבִיעָאָה וְהָא מַכְתְּשָׁא קָם כַּד הֲוָה לָא אוֹסֵף מַכְתָּשָׁא בְּמַשְׁכָּא וְיַסְגְּרִנֵּיהּ כַּהֲנָא שִׁבְעָא יוֹמִין תִּנְיָנוּת:",0,0],[13,6,"וְיֶחֱזֵי כַהֲנָא יָתֵיהּ בְּיוֹמָא שְׁבִיעָאָה תִּנְיָנוּת וְהָא עַמְיָא מַכְתָּשָׁא וְלָא אוֹסֵף מַכְתָּשָׁא בְּמַשְׁכָּא וִידַכִּנֵּיהּ כַּהֲנָא עֲדִיתָא הִיא וִיצַבַּע לְבוּשׁוֹהִי וְיִדְכֵּי:",0,0],[13,7,"וְאִם אוֹסָפָא תוֹסֵף עֲדִיתָא בְּמַשְׁכָּא בָּתַר דִּאִתַּחֲזִי לְכַהֲנָא לְדַכּוּתֵיהּ וְיִתַּחֲזִי תִנְיָנוּת לְכַהֲנָא:",0,0],[13,8,"וְיֶחֱזֵי כַהֲנָא וְהָא אוֹסֵפַת עֲדִיתָא בְּמַשְׁכָּא וִיסָאֵבִנֵּיהּ כַּהֲנָא סְגִירוּתָא הִיא:",0,0],[13,9,"מַכְתַּשׁ סְגִירוּ אֲרֵי תְהֵי בֶּאֱנָשָׁא וְיִתֵּתֵי לְוָת כַּהֲנָא:",0,0],[13,10,"וְיֶחֱזֵי כַהֲנָא וְהָא עַמְקָא חַוְּרָא בְּמַשְׁכָּא וְהִיא הֲפָכַת שֵׂעָר לְחִוָּר וְרשֶׁם בִּסְרָא חַיְתָא בְּעַמִּקְתָּא:",0,0],[13,11,"סְגִירוּת עַתִּיקָא הִיא בִּמְשַׁךְ בִּסְרֵיהּ וִיסָאֵבִנֵּיהּ כַּהֲנָא לָא יַסְגְּרִנֵיהּ אֲרֵי מְסָאָב הוּא:",0,0],[13,12,"וְאִם מִסְגָּא תִסְגֵּי סְגִירוּתָא בְּמַשְׁכָּא וְתַחֲפֵי סְגִירוּתָא יָת כָּל מְשַׁךְ מַכְתָּשָׁא מֵרֵישֵׁיהּ וְעַד רַגְלוֹהִי לְכָל חֵיזוּ עֵינֵי כַהֲנָא:",0,0],[13,13,"וְיֶחֱזֵי כַהֲנָא וְהָא חֲפַת סְגִירוּתָא יָת כָּל בִּסְרֵיהּ וִידַכִּי יָת מַכְתָּשָׁא כֻּלֵּיהּ אִתְהֲפִיךְ לְמֶחֱוַר דְּכֵי הוּא:",0,0],[13,14,"וּבְיוֹמָא דְאִתַּחֲזִי בֵיהּ בִּסְרָא חַיָּא יְהֵי מְסָאָב:",0,0],[13,15,"וְיֶחֱזֵי כַהֲנָא יָת בִּסְרָא חַיָּא וִיסָאֵבִנֵּיהּ בִּסְרָא חַיָּא מְסָאָב הוּא סְגִירוּת הוּא:",0,0],[13,16,"אוֹ אֲרֵי יְתוּב בִּסְרָא חַיָּא וְיִתְהֲפִיךְ לְמֶחֱוָר וְיִתֵּתֵי לְוָת כַּהֲנָא:",0,0],[13,17,"וְיֶחֱזִנֵּיהּ כַּהֲנָא וְהָא אִתְהֲפִיךְ מַכְתָּשָׁא לְמֶחֱוָר וִידַכֵּי כַהֲנָא יָת מַכְתָּשָׁא דְּכֵי הוּא:",0,0],[13,18,"וּבִסְרָא אֲרֵי יְהֵי בֵיהּ בְּמַשְׁכֵּיהּ שִׁחֲנָא וְיִתַּסֵּי:",0,0],[13,19,"וִיהֵי בַּאֲתַר שִׁחֲנָא עַמְקָא חַוְּרָא אוֹ בַהֲרָא חַוְּרָא סַמְקָא וְיִתַּחֲזִי לְכַהֲנָא:",0,0],[13,20,"וְיֶחֱזֵי כַהֲנָא וְהָא מֶחֱזָהָא מַכִּיךְ מִן מַשְׁכָּא וּשְׂעָרַהּ אִתְהֲפִיךְ לְמֶחֱוָר וִיסָאֵבִינֵיהּ כַּהֲנָא מַכְתַּשׁ סְגִירוּתָא הִיא בְּשִׁחֲנָא סְגִיאַת:",0,0],[13,21,"וְאִם יֶחֱזִנַּהּ כַּהֲנָא וְהָא לֵית בַּהּ שֵׂעָר חִוָּר וּמַכִּיכָא לֵיתָהָא מִן מַשְׁכָּא וְהִיא עָמְיָא וְיַסְגְּרִנֵּיהּ כַּהֲנָא שִׁבְעָא יוֹמִין:",0,0],[13,22,"וְאִם אוֹסָפָא תוֹסֵף בְּמַשְׁכָּא וִיסָאֵב כַּהֲנָא יָתֵיהּ מַכְתָּשָׁא הִיא:",0,0],[13,23,"וְאִם בְּאַתְרָהָא קָמַת בֶּהַרְתָּא לָא אוֹסֵפַת רשֶׁם שִׁחֲנָא הִיא וִידַכִּנֵּיהּ כַּהֲנָא:",0,0],[13,24,"אוֹ בִסְרָא אֲרֵי יְהֵי בְמַשְׁכֵּיהּ כְּוָאָה דְנוּר וּתְהֵי רשֶׁם כְּוָאָה בַּהֲרָא חַוְּרָא סַמְקָא אוֹ חַוְּרָא:",0,0],[13,25,"וְיֶחֱזֵי יָתַהּ כַּהֲנָא וְהָא אִתְהֲפִיךְ שֵׂעָר חִוָּר בְּבַהֶרְתָּא וּמֶחֱזָהָא עַמִּיק מִן מַשְׁכָּא סְגִירוּתָא הִיא בִּכְוָאָה סְגִיאָה וִיסָאֵב יָתֵיהּ כַּהֲנָא מַכְתַּשׁ סְגִירוּתָא הִיא:",0,0],[13,26,"וְאִם יֶחֱזִנַּהּ כַּהֲנָא וְהָא לֵית בְּבַהֶרְתָּא שֵׂעָר חִוָּר וּמַכִּיכָא לֵיתָהָא מִן מַשְׁכָּא וְהִיא עָמְיָא וְיַסגְּרִנֵּיהּ כַּהֲנָא שִׁבְעָא יוֹמִין:",0,0],[13,27,"וְיֶחֱזִנֵּיהּ כַּהֲנָא בְּיוֹמָא שְׁבִיעָאָה אִם אוֹסָפָא תוֹסֵף בְּמַשְׁכָּא וִיסָאֵב כַּהֲנָא יָתֵיהּ מַכְתַּשׁ סְגִירוּתָא הִיא:",0,0],[13,28,"וְאִם בְּאַתְרָהָא קָמַת בַּהֶרְתָּא לָא אוֹסֵפַת בְּמַשְׁכָּא וְהִיא עָמְיָא עֹמֶק כְּוָאָה הִיא וִידַכִּנֵּיהּ כַּהֲנָא אֲרֵי רשֶׁם כְּוָאָה הִיא:",0,0],[13,29,"וּגְבַר אוֹ אִתְּתָא אֲרֵי יְהֵי בֵיהּ מַכְתָּשָׁא בְּרֵישָׁא אוֹ בִדְקָן:",0,0],[13,30,"וְיֶחֱזֵי כַהֲנָא יָת מַכְתָּשָׁא וְהָא מֶחֱזוֹהִי עַמִּיק מִן מַשְׁכָּא וּבֵיהּ שֵׂעָר סֻמָּק דַּעְדָּק וִיסָאֵב יָתֵיהּ כַּהֲנָא נִתְקָא הוּא סְגִירוּת רֵישָׁא אוֹ דִקְנָא הוּא:",0,0],[13,31,"וַאֲרֵי יֶחֱזֵי כַהֲנָא יָת מַכְתַּשׁ נִתְקָא וְהָא לֵית מֶחֱזוֹהִי עַמִּיק מִן מַשְׁכָּא וְשֵׂעָר אֻכָּם לֵית בֵּיהּ וְיַסְגַּר כַּהֲנָא יָת מַכְתַּשׁ נִתְקָא שִׁבְעַת יוֹמִין:",0,0],[13,32,"וְיֶחֱזֵי כַהֲנָא יָת מַכְתָּשָׁא בְּיוֹמָא שְׁבִיעָאָה וְהָא לָא אוֹסֵף נִתְקָא וְלָא הֲוָה בֵיהּ שֵׂעָר סֻמָּק וּמֶחֱזֵי נִתְקָא לֵית עַמִּיק מִן מַשְׁכָּא:",0,0],[13,33,"וִיגַלַּח סָחֳרָנֵי נִתְקָא וּדְעִם נִתְקָא לָא יְגַלַּח וְיַסְגַּר כַּהֲנָא יָת נִתְקָא שִׁבְעָא יוֹמִין תִּנְיָנוּת:",0,0],[13,34,"וְיֶחֱזֵי כַהֲנָא יָת נִתְקָא בְּיוֹמָא שְׁבִיעָאָה וְהָא לָא אוֹסֵף נִתְקָא בְּמַשְׁכָּא וּמֶחֱזוֹהִי לֵיתוֹהִי עַמִּיק מִן מַשְׁכָּא וִידַכֵּי יָתֵיהּ כַּהֲנָא וִיצַבַּע לְבוּשׁוֹהִי וְיִדְכֵּי:",0,0],[13,35,"וְאִם אוֹסָפָא יוֹסֵף נִתְקָא בְּמַשְׁכָּא בָּתַר דָּכוּתֵיהּ:",0,0],[13,36,"וְיֶחֱזִנֵּיהּ כַּהֲנָא וְהָא אוֹסֵף נִתְקָא בְּמַשְׁכָּא לָא יְבַקֵּר כַּהֲנָא לְשֵׂעָר סֻמָּק מְסָאָב הוּא:",0,0],[13,37,"וְאִם כַּד הֲוָה קָם נִתְקָא וְשֵׂעָר אֻכָּם צְמַח בֵּיהּ אִתַּסִּי נִתְקָא דְּכֵי הוּא וִידַכִּנֵּיהּ כַּהֲנָא:",0,0],[13,38,"וּגְבַר אוֹ אִתְּתָא אֲרֵי יְהֵי בִמְשַׁךְ בִּסְרְהוֹן בַּהֲרָן בַּהֲרָן חַוְּרָן:",0,0],[13,39,"וְיֶחֱזֵי כַהֲנָא וְהָא בִמְשַׁךְ בִּסְרְהוֹן בַּהֲרָן עָמְיָן חַוְּרָן בָּהֲקָא הוּא סָגֵי בְמַשְׁכָּא דְּכֵי הוּא:",0,0],[13,40,"וּגְבַר אֲרֵי יַתַּר שְׂעַר רֵישֵׁיהּ קְרַח הוּא דְּכֵי הוּא:",0,0],[13,41,"וְאִם מִלָּקֳבֵל אֲפּוֹהִי יַתַּר שְׂעַר רֵישֵׁיהּ גְּלוֹשׁ הוּא דְּכֵי הוּא:",0,0],[13,42,"וַאֲרֵי יְהֵי בְקָרָחוּתֵיהּ אוֹ בִגְלוֹשׁוּתֵיהּ מַכְתַּשׁ חִוָּר סַמּוֹק סְגִירוּת סָגְיָא הִיא בְּקָרָחוּתֵיהּ אוֹ בִגְלוֹשׁוּתֵיהּ:",0,0],[13,43,"וְיֶחֱזֵי יָתֵיהּ כַּהֲנָא וְהָא עַמִּיק מַכְתָּשָׁא חַוְּרָא סַמְּקָא בְּקָרָחוּתֵיהּ אוֹ בִגְלוֹשׁוּתֵיהּ כְּמֶחֱזֵי סְגִירוּתָא מְשַׁךְ בִּסְרָא:",0,0],[13,44,"גְּבַר סְגִיר הוּא מְסָאָב הוּא סָאֳבָא יְסָאֵבִנֵּיהּ כַּהֲנָא בְּרֵישֵׁיהּ מַכְתָּשֵׁיהּ:",0,0],[13,45,"וּסְגִירָא דִּי בֵיהּ מַכְתָּשָׁא לְבוּשׁוֹהִי יְהוֹן מְבַזְּעִין וְרֵישֵׁיהּ יְהֵי פְרִיעַ וְעַל שָׂפָם כַּאֲבֵלָא יִתְעַטָּף וְלָא תִסְתַּאֲבוּן וְלָא תִסְתַּאֲבוּן יִקְרֵי:",0,0],[13,46,"כָּל יוֹמֵי דִּי מַכְתָּשָׁא בֵיהּ יְהֵי מְסָאָב מְסָאָב הוּא בִּלְחוֹדוֹהִי יֵיתֵב מִבָּרָא לְמַשְׁרִיתָא מוֹתְבֵיהּ:",0,0],[13,47,"וּלְבוּשָׁא אֲרֵי יְהֵי בֵיהּ מַכְתַּשׁ סְגִירוּ בִּלְבוּשׁ עֲמַר אוֹ בִּלְבוּשׁ כִּתָּן:",0,0],[13,48,"אוֹ בְשִׁתְיָא אוֹ בְעַרְבָא לְכִתָּנָא וּלְעַמְרָא אוֹ בְמַשְׁכָּא אוֹ בְּכָל עֲבִידַת מְשָׁךְ:",0,0],[13,49,"וִיהֵי מַכְתָּשָׁא יָרוֹק אוֹ סַמּוֹק בִּלְבוּשָׁא אוֹ בְמַשְׁכָּא אוֹ בְשִׁתְיָא אוֹ בְעַרְבָא אוֹ בְכָל מַאן דִּמְשַׁךְ מַכְתַּשׁ סְגִירוּתָא הוּא וְיִתַּחֲזֵי לְכַהֲנָא:",0,0],[13,50,"וְיֶחֱזֵי כַהֲנָא יָת מַכְתָּשָׁא וְיַסְגַּר יָת מַכְתָּשָׁא שִׁבְעַת יוֹמִין:",0,0],[13,51,"וְיֶחֱזֵי יָת מַכְתָּשָׁא בְּיוֹמָא שְׁבִיעָאָה אֲרֵי אוֹסֵף מַכְתָּשָׁא בִּלְבוּשָׁא אוֹ בְשִׁתְיָא אוֹ בְעַרְבָא אוֹ בְמַשְׁכָּא לְכֹל דִּי יִתְעֲבֵד מַשְׁכָּא לְעִבִידָא סְגִירוּת מְחַסְרָא מַכְתָּשָׁא מְסָאָב הוּא:",0,0],[13,52,"וְיוֹקִיד יָת לְבוּשָׁא אוֹ יָת שִׁתְיָא אוֹ יָת עַרְבָא בְּעַמְרָא אוֹ בְכִתָּנָא אוֹ יָת כָּל מָאן דִּמְשַׁךְ דִּי יְהֵי בֵיהּ מַכְתָּשָׁא אֲרֵי סְגִירוּת מְחַסְרָא הִיא בְּנוּרָא תִּתּוֹקָד:",0,0],[13,53,"וְאִם יֶחֱזֵי כַהֲנָא וְהָא לָא אוֹסֵף מַכְתָּשָׁא בִּלְבוּשָׁא אוֹ בְשִׁתְיָא אוֹ בְעַרְבָא אוֹ בְּכָל מָאן דִּמְשָׁךְ:",0,0],[13,54,"וִיפַקֵּד כַּהֲנָא וִיחַוְּרוּן יָת דִּי בֵיהּ מַכְתָּשָׁא וְיַסְגְּרִנֵּיהּ שִׁבְעַת יוֹמִין תִּנְיָנוּת:",0,0],[13,55,"וְיֶחֱזֵי כַהֲנָא בָּתַר דְּחַוָּרוּ יָת מַכְתָּשָׁא וְהָא לָא שְׁנָא מַכְתָּשָׁא מִן כַּד הֲוָה וּמַכְתָּשָׁא לָא אוֹסֵף מְסָאָב הוּא בְּנוּרָא תּוֹקְדִנֵּיהּ תַּבְרָא הִיא בְּשְׁחִיקוּתֵיהּ אוֹ בְחַדָּתוּתֵיהּ:",0,0],[13,56,"וְאִם חֲזָא כַהֲנָא וְהָא עָמְיָא מַכְתָּשָׁא בָּתַר דְּחַוָּרוּ יָתֵיהּ וּבְזַע יָתֵיהּ מִן לְבוּשָׁא אוֹ מִן מַשְׁכָּא אוֹ מִן שִׁתְיָא אוֹ מִן עַרְבָא:",0,0],[13,57,"וְאִם תִּתְחֲזֵי עוֹד בִּלְבוּשָׁא אוֹ בְשִׁתְיָא אוֹ בְעַרְבָא אוֹ בְכָל מָאן דִּמְשַׁךְ סָגְיָא הִיא בְּנוּרָא תוֹקְדִנֵּיהּ יָת דִּי בֵיהּ מַכְתָּשָׁא:",0,0],[13,58,"וּלְבוּשָׁא אוֹ שִׁתְיָא אוֹ עַרְבָא אוֹ כָל מָאן דִּמְשַׁךְ דִּי יִתְחַוַּר וְיֶעְדֵּי מִנְּהוֹן מַכְתָּשָׁא וְיִצְטַבַּע תִּנְיָנוּת וְיִדְכֵּי:",0,0],[13,59,"דָּא אוֹרַיְתָא דְמַכְתַּשׁ סְגִירוּ בִּלְבוּשׁ עֲמַר אוֹ כִתָּנָא אוֹ שִׁתְיָא אוֹ עַרְבָא אוֹ כָּל מָאן דִּמְשָׁךְ לְדַכָּיוּתֵיהּ אוֹ לְסַאֲבוּתֵיהּ:",0,0],[14,1,"וּמַלִּיל יְיָ עִם משֶׁה לְמֵימָר:",0,0],[14,2,"דָּא תְהֵי אוֹרַיְתָא דִסְגִירָא בִּיוֹמָא דְדָכוּתֵיהּ וְיִתֵּתֵי לְוָת כַּהֲנָא:",0,0],[14,3,"וְיִפּוֹק כַּהֲנָא לְמִבָּרָא לְמַשְׁרִיתָא וְיֶחֱזֵי כַהֲנָא וְהָא אִתַּסִּי מַכְתַּשׁ סְגִירוּתָא מִן סְגִירָא:",0,0],[14,4,"וִיפַקֵּד כַּהֲנָא וְיִסַּב לְמִדַּכֵּי תַּרְתֵּין צִפְּרִין חַיִּין דָּכְיָן וְאָעָא דְאַרְזָא וּצְבַע זְהוֹרִי וְאֵזוֹבָא:",0,0],[14,5,"וִיפַקֵּד כַּהֲנָא וְיִכּוֹס יָת צִפְּרָא חֲדָא לְמַאן דַּחֲסַף עַל מֵי מַבּוּעַ:",0,0],[14,6,"יָת צִפְּרָא חַיְתָא יִסַּב יָתַהּ וְיָת אָעָא דְאַרְזָא וְיָת צְבַע זְהוֹרִי וְיָת אֵזוֹבָא וְיִטְבּוֹל יָתְהוֹן וְיָת צִפְּרָא חַיְתָא בִּדְמָא דְּצִפְּרָא דִּנְכִיסָא עַל מֵי מַבּוּעַ:",0,0],[14,7,"וְיַדִּי עַל דְּמִדַּכֵּי מִן סְגִירוּתָא שְׁבַע זִמְנִין וִידַכִּנֵּיהּ וִישַׁלַּח יָת צִפְּרָא חַיְתָא עַל אַפֵּי חַקְלָא:",0,0],[14,8,"וִיצַבַּע דְּמִדַּכֵּי יָת לְבוּשׁוֹהִי וִיגַלַּח יָת כָּל שַׂעֲרֵיהּ וְיַסְחֵי בְמַיָּא וְיִדְכֵּי וּבָתַר כֵּן יֵעוֹל לְמַשְׁרִיתָא וִיתֵב מִבָּרָא לְמַשְׁכְּנֵיהּ שַׁבְעָא יוֹמִין:",0,0],[14,9,"וִיהֵי בְיוֹמָא שְׁבִיעָאָה יְגַלַּח יָת כָּל שַׂעֲרֵיהּ יָת רֵישֵׁיהּ וְיָת דִּקְנֵיהּ וְיָת גְּבִינֵי עֵינוֹהִי וְיָת כָּל שַׂעֲרֵיהּ יְגַלָּח וִיצַבַּע יָת לְבוּשׁוֹהִי וְיַסְחֵי יָת בִּסְרֵיהּ בְּמַיָּא וְיִדְכֵּי:",0,0],[14,10,"וּבְיוֹמָא תְמִינָאָה יִסַּב תְּרֵין אִמְּרִין שַׁלְמִין וְאִמַּרְתָּא חֲדָא בַּת שַׁתָּא שְׁלֶמְתָּא וּתְלָתָא עֶסְרוֹנִין סֻלְתָּא מִנְחָתָא דְּפִילָא בִמְשַׁח וְלֻגָּא חַד דְּמִשְׁחָא:",0,0],[14,11,"וִיקִים כַּהֲנָא דִמְדַּכֵּי יָת גַּבְרָא דְּמִדַּכֵּי וְיָתְהוֹן קֳדָם יְיָ בִּתְרַע מַשְׁכַּן זִמְנָא:",0,0],[14,12,"וְיִסַּב כַּהֲנָא יָת אִמְּרָא חֲדָא וִיקָרֵב יָתֵיהּ לַאֲשָׁמָא וְיָת לֻגָּא דְמִשְׁחָא וִירִים יָתְהוֹן אֲרָמָא קֳדָם יְיָ:",0,0],[14,13,"וְיִכּוֹס יָת אִמְּרָא בַּאֲתַר דִּי יִכּוֹס יָת חַטָּאתָא וְיָת עֲלָתָא בַּאֲתַר קַדִּישׁ אֲרֵי כְּחַטָּאתָא אֲשָׁמָא הוּא לְכַהֲנָא קֹדֶשׁ קוּדְשִׁין הוּא:",0,0],[14,14,"וְיִסַּב כַּהֲנָא מִדְּמָא דַאֲשָׁמָא וְיִתֵּן כַּהֲנָא עַל רוּם אוּדְנָא דְמִדַּכֵּי דְּיַמִּינָא וְעַל אִלְיוֹן יְדֵיהּ דְּיַמִּינָא וְעַל אִלְיוֹן רַגְלֵיהּ דְּיַמִּינָא:",0,0],[14,15,"וְיִסַּב כַּהֲנָא מִלֻּגָּא דְמִשְׁחָא וִירִיק עַל יְדָא דְכַהֲנָא דִּשְׂמָאלָא:",0,0],[14,16,"וְיִטְבּוֹל כַּהֲנָא יָת אֶצְבְּעֵיהּ דְיַמִּינָא מִן מִשְׁחָא דִּי עַל יְדֵיהּ דִּשְׂמָאלָא וְיַדִּי מִן מִשְׁחָא בְּאֶצְבְּעֵיהּ שְׁבַע זִמְנִין קֳדָם יְיָ:",0,0],[14,17,"וּמִשְּׁאָר מִשְׁחָא דִּי עַל יְדֵיהּ יִתֵּן כַּהֲנָא עַל רוּם אוּדְנָא דְּמִדַּכֵּי דְּיַמִּינָא וְעַל אִלְיוֹן יְדֵיהּ דְּיַמִּינָא וְעַל אִלְיוֹן רַגְלֵיהּ דְּיַמִּינָא עַל דְּמָא דַאֲשָׁמָא:",0,0],[14,18,"וּדְאִשְׁתָּאַר בְּמִשְׁחָא דִּי עַל יְדָא דְכַהֲנָא יִתֵּן עַל רֵישָׁא דְּמִדַּכֵּי וִיכַפֵּר עֲלוֹהִי כַּהֲנָא קֳדָם יְיָ:",0,0],[14,19,"וְיַעְבֵּד כַּהֲנָא יָת חַטָּאתָא וִיכַפֵּר עַל דְּמִדַּכֵּי מְסּוֹבְתֵיהּ וּבָתַר כֵּן יִכּוֹס יָת עֲלָתָא:",0,0],[14,20,"וְיַסֵּק כַּהֲנָא יָת עֲלָתָא וְיָת מִנְחָתָא לְמַדְבְּחָא וִיכַפֵּר עֲלוֹהִי כַּהֲנָא וְיִדְכֵּי:",0,0],[14,21,"וְאִם מִסְכֵּן הוּא וְלֵית יְדֵיהּ מַדְבְּקָא וְיִסַּב אִמַּר חַד אֲשָׁמָא לַאֲרָמָא לְכַפָּרָא עֲלוֹהִי וְעִסְרוֹנָא סֻלְתָּא חַד דְּפִיל בִּמְשַׁח לְמִנְחָא וְלֻגָּא דְמִשְׁחָא:",0,0],[14,22,"וְתַרְתֵּין שַׁפְנִינִין אוֹ תְרֵין בְּנֵי יוֹנָה דִּי תַדְבֵּק יְדֵיהּ וִיהֵי חַד חַטָּאתָא וְחַד עֲלָתָא:",0,0],[14,23,"וְיַיְתִי יָתְהוֹן בְּיוֹמָא תְמִינָאָה לְדַכָּיוּתֵיהּ לְוָת כַּהֲנָא לִתְרַע מַשְׁכַּן זִמְנָא קֳדָם יְיָ:",0,0],[14,24,"וְיִסַּב כַּהֲנָא יָת אִמְּרָא דַאֲשָׁמָא וְיָת לֻגָּא דְמִשְׁחָא וִירִים יָתְהוֹן כַּהֲנָא אֲרָמָא קֳדָם יְיָ:",0,0],[14,25,"וְיִכּוֹס יָת אִמְּרָא דַאֲשָׁמָא וְיִסַּב כַּהֲנָא מִדְּמָא דַאֲשָׁמָא וְיִתֵּן עַל רוּם אוּדְנָא דְמִדַּכֵּי דְּיַמִּינָא וְעַל אִלְיוֹן יְדֵיהּ דְּיַמִּינָא וְעַל אִלְיוֹן רַגְלֵיהּ דְּיַמִּינָא:",0,0],[14,26,"וּמִן מִשְׁחָא יְרִיק כַּהֲנָא עַל יְדָא דְכַהֲנָא דִּשְׂמָאלָא:",0,0],[14,27,"וְיַדִּי כַהֲנָא בְּאֶצְבְּעֵיהּ דְּיַמִּינָא מִן מִשְׁחָא דִּי עַל יְדֵיהּ דִּשְׂמָאלָא שְׁבַע זִמְנִין קֳדָם יְיָ:",0,0],[14,28,"וְיִתֵּן כַּהֲנָא מִן מִשְׁחָא דִּי עַל יְדֵיהּ עַל רוּם אוּדְנָא דְמִדַּכֵּי דְּיַמִּינָא וְעַל אִלְיוֹן יְדֵיהּ דְּיַמִּינָא וְעַל אִלְיוֹן רַגְלֵיהּ דְיַמִּינָא עַל אֲתַר דְּמָא דַאֲשָׁמָא:",0,0],[14,29,"וּדְיִשְׁתָּאַר מִן מִשְׁחָא דִּי עַל יְדָא דְכַהֲנָא יִתֵּן עַל רֵישָׁא דְמִדַּכֵּי לְכַפָּרָא עֲלוֹהִי קֳדָם יְיָ:",0,0],[14,30,"וְיַעְבֵּד יָת חַד מִן שַׁפְנִינַיָּא אוֹ מִן בְּנֵי יוֹנָה מִדִּי תַדְבֵּק יְדֵיהּ:",0,0],[14,31,"יָת דִּי תַדְבֵּק יְדֵיהּ יָת חַד חַטָּאתָא וְיָת חַד עֲלָתָא עַל מִנְחָתָא וִיכַפֵּר כַּהֲנָא עַל דְּמִדַּכֵּי קֳדָם יְיָ:",0,0],[14,32,"דָּא אוֹרַיְתָא דִּי בֵיהּ מַכְתַּשׁ סְגִירוּ דִּי לָא תַדְבֵּק יְדֵיהּ בְּדָכוּתֵיהּ:",0,0],[14,33,"וּמַלִּיל יְיָ עִם משֶׁה וְעִם אַהֲרֹן לְמֵימָר:",0,0],[14,34,"אֲרֵי תֵעֲלוּן לְאַרְעָא דִכְנַעַן דִּי אֲנָא יָהֵב לְכוֹן לְאַחֲסָנָא וְאֶתֵּן מַכְתַּשׁ סְגִירוּ בְּבֵית אַרְעָא אַחֲסְנְתְּכוֹן:",0,0],[14,35,"וְיֵיתֵי דְּדִילֵיהּ בֵּיתָא וִיחַוִּי לְכַהֲנָא לְמֵימָר כְּמַכְתָּשָׁא אִתְחֲזִי לִי בְּבֵיתָא:",0,0],[14,36,"וִיפַקֵּד כַּהֲנָא וִיפַנּוּן יָת בֵּיתָא עַד לָא יֵעוֹל כַּהֲנָא לְמֶחֱזֵי יָת מַכְתָּשָׁא וְלָא יִסְתָּאַב כָּל דִּי בְּבֵיתָא וּבָתַר כֵּן יֵעוֹל כַּהֲנָא לְמֶחֱזֵי יָת בֵּיתָא:",0,0],[14,37,"וְיֶחֱזֵי יָת מַכְתָּשָׁא וְהָא מַכְתָּשָׁא בְּכָתְלֵי בֵיתָא פַּחֲתִין יַרְקָן אוֹ סַמְקָן וּמֶחֱזֵיהוֹן מַכִּיךְ מִן כָּתְלָא:",0,0],[14,38,"וְיִפּוֹק כַּהֲנָא מִן בֵּיתָא לִתְרַע בֵּיתָא וְיַסְגַּר יָת בֵּיתָא שִׁבְעָא יוֹמִין:",0,0],[14,39,"וִיתוּב כַּהֲנָא בְּיוֹמָא שְׁבִיעָאָה וְיֶחֱזֵי וְהָא אוֹסִיף מַכְתָּשָׁא בְּכָתְלֵי בֵיתָא:",0,0],[14,40,"וִיפַקֵּד כַּהֲנָא וִישַׁלְּפוּן יָת אַבְנַיָּא דִּי בְהוֹן מַכְתָּשָׁא וְיִרְמוּן יָתְהוֹן לְמִבָּרָא לְקַרְתָּא לַאֲתַר מְסָאָב:",0,0],[14,41,"וְיָת בֵּיתָא יְקַלְּפוּן מִגָּיו סְחוֹר סְחוֹר וְיִרְמוּן יָת עַפְרָא דִּי קַלִּיפוּ לְמִבָּרָא לְקַרְתָּא לַאֲתַר מְסָאָב:",0,0],[14,42,"וְיִסְּבוּן אַבְנַיָּא אָחֳרָנִין וְיַעֲלוּן לַאֲתַר אַבְנַיָּא וַעֲפַר אָחֳרָן יִסַּב וִישׁוּעַ יָת בֵּיתָא:",0,0],[14,43,"וְאִם יְתוּב מַכְתָּשָׁא וְיִסְגֵּי בְּבֵיתָא בָּתַר דְּשַׁלִּיפוּ יָת אַבְנַיָּא וּבָתַר דְקַלִּיפוּ יָת בֵּיתָא וּבָתַר דְּאִתְּשָׁע:",0,0],[14,44,"וְיֵיעוֹל כַּהֲנָא וְיֶחֱזֵי וְהָא אוֹסֵף מַכְתָּשָׁא בְּבֵיתָא סְגִירוּת מְחַסְרָא הִיא בְּבֵיתָא מְסָאָב הוּא:",0,0],[14,45,"וִיתָרַע יָת בֵּיתָא יָת אַבְנוֹהִי וְיָת אָעוֹהִי וְיָת כָּל עֲפַר בֵּיתָא וְיַפֵּק לְמִבָּרָא לְקַרְתָּא לַאֲתַר מְסָאָב:",0,0],[14,46,"וּדְיֵיעוֹל לְבֵיתָא כָּל יוֹמִין דְּיַסְגַּר יָתֵיהּ יְהֵי מְסָאָב עַד רַמְשָׁא:",0,0],[14,47,"וּדְיִשְׁכּוּב בְּבֵיתָא יְצַבַּע יָת לְבוּשׁוֹהִי וּדְיֵיכוּל בְּבֵיתָא יְצַבַּע יָת לְבוּשׁוֹהִי:",0,0],[14,48,"וְאִם מֵעַל יֵיעוֹל כַּהֲנָא וְיֶחֱזֵי וְהָא לָא אוֹסֵף מַכְתָּשָׁא בְּבֵיתָא בָּתַר דְּאִתְּשַׁע יָת בֵּיתָא וִידַכֵּי כַהֲנָא יָת בֵּיתָא אֲרֵי אִתַּסִּי מַכְתָּשָׁא:",0,0],[14,49,"וְיִסַּב לְדַכָּאָה יָת בֵּיתָא תַּרְתֵּין צִפְּרִין וְאָעָא דְאַרְזָא וּצְבַע זְהוֹרִי וְאֵזוֹבָא:",0,0],[14,50,"וְיִכּוֹס יָת צִפֲּרָא חֲדָא לְמַאן דַּחֲסַף עַל מֵי מַבּוּעַ:",0,0],[14,51,"וְיִסַּב יָת אָעָא דְאַרְזָא וְיָת אֵזוֹבָא וְיָת צְבַע זְהוֹרִי וְיָת צִפֲּרָא חַיְתָא וְיִטְבּוֹל יָתְהוֹן בִּדְמָא דְּצִפֲּרָא דִנְכִיסָא וּבְמֵי מַבּוּעַ וְיַדִּי לְבֵיתָא שְׁבַע זִמְנִין:",0,0],[14,52,"וִידַכֵּי יָת בֵּיתָא בִּדְמָא דְּצִפֲּרָא וּבְמֵי מַבּוּעַ וּבְצִפֲּרָא חַיְתָא וּבְאָעָא דְאַרְזָא וּבְאֵזוֹבָא וּבִצְבַע זְהוֹרִי:",0,0],[14,53,"וִישַׁלַּח יָת צִפֲּרָא חַיְתָא לְמִבָּרָא לְקַרְתָּא לְאַפֵּי חַקְלָא וִיכַפַּר עַל בֵּיתָא וְיִדְכֵּי:",0,0],[14,54,"דָּא אוֹרַיְתָא לְכָל מַכְתַּשׁ סְגִירוּתָא וּלְנִתְקָא:",0,0],[14,55,"וְלִסְגִירוּת לְבוּשָׁא וּלְבֵיתָא:",0,0],[14,56,"וּלְעַמְקָא וּלְעַדְיָא וּלְבַהֲרָא:",0,0],[14,57,"לְאַלָּפָא בְּיוֹמָא מְסָאָבָא וּבְיוֹמָא דַכְיָא דָּא אוֹרַיְתָא דִּסְגִירוּתָא:",0,0],[15,1,"וּמַלִּיל יְיָ עִם משֶׁה וְעִם אַהֲרֹן לְמֵימָר:",0,0],[15,2,"מַלִּילוּ עִם בְּנֵי יִשְׂרָאֵל וְתֵימְרוּן לְהוֹן גְּבַר גְּבַר אֲרֵי יְהֵי דָּאִיב מִבִּשְׂרֵיהּ דּוֹבֵיהּ מְסָאָב הוּא:",0,0],[15,3,"וְדָא תְּהֵי סוֹבְתֵיהּ בְּדוֹבֵיהּ רָר בִּשְׂרֵיהּ יָת דּוֹבֵיהּ אוֹ חָתִים בִּשְׂרֵיהּ מִדּוֹבֵיהּ סוֹבְתֵיהּ הִיא:",0,0],[15,4,"כָּל מִשְׁכְּבָא דִּי יִשְׁכּוּב עֲלוֹהִי דּוֹבָנָא יְהֵי מְסָאָב וְכָל מָנָא דְיֵיתֵב עֲלוֹהִי יְהֵי מְסָאָב:",0,0],[15,5,"וּגְבַר דִּי יִקְרַב בּמִשְׁכְּבֵיהּ יְצַבַּע לְבוּשׁוֹהִי וְיַסְחֵי בְמַיָּא וִיהֵי מְסָאָב עַד רַמְשָׁא:",0,0],[15,6,"וּדְיֵיתֵב עַל מָנָא דְּיֵיתֵב עֲלוֹהִי דּוֹבָנָא יְצַבַּע לְבוּשׁוֹהִי וְיַסְחֵי בְמַיָּא וִיהֵי מְסָאָב עַד רַמְשָׁא:",0,0],[15,7,"וּדְיִקְרַב בִּבְסַר דּוֹבָנָא יְצַבַּע לְבוּשׁוֹהִי וְיַסְחֵי בְמַיָּא וִיהֵי מְסָאָב עַד רַמְשָׁא:",0,0],[15,8,"וַאֲרֵי יֵרוֹק דּוֹבָנָא בְּדַכְיָא וִיצַבַּע לְבוּשׁוֹהִי וְיַסְחֵי בְמַיָּא וִיהֵי מְסָאָב עַד רַמְשָׁא:",0,0],[15,9,"וְכָל מֶרְכְּבָא דִּי יִרְכּוּב עֲלוֹהִי דּוֹבָנָא יְהֵי מְסָאָב:",0,0],[15,10,"וְכָל דְּיִקְרַב בְּכֹל דִּי יְהֵי תְחוֹתוֹהִי יְהֵי מְסָאָב עַד רַמְשָׁא וּדְיִטּוֹל יָתְהוֹן יְצַבַּע לְבוּשׁוֹהִי וְיַסְחֵי בְמַיָּא וִיהֵי מְסָאָב עַד רַמְשָׁא:",0,0],[15,11,"וְכֹל דִּי יִקְרַב בֵּיהּ דּוֹבָנָא וִידוֹהִי לָא שְׁטַף בְּמַיָּא וִיצַבַּע לְבוּשׁוֹהִי וְיַסְחֵי בְמַיָּא וִיהֵי מְסָאָב עַד רַמְשָׁא:",0,0],[15,12,"וּמַאן דַּחֲסַף דִּי יִקְרַב בֵּיהּ דּוֹבָנָא יִתָּבַר וְכָל מַאן דְּאָע יִשְׁתַּטַּף בְּמַיָּא:",0,0],[15,13,"וַאֲרֵי יִדְכֵּי דּוֹבָנָא מִדּוֹבֵיהּ וְיִמְנֵי לֵיהּ שִׁבְעַת יוֹמִין לְדָכוּתֵיהּ וִיצַבַּע לְבוּשׁוֹהִי וְיַסְחֵי בִשְׂרֵיהּ בְּמֵי מַבּוּעַ וְיִדְכֵּי:",0,0],[15,14,"וּבְיוֹמָא תְמִינָאָה יִסַּב לֵיהּ תַּרְתֵּין שַׁפְנִינִין אוֹ תְרֵין בְּנֵי יוֹנָה וְיֵיתֵי לָקֳדָם יְיָ לִתְרַע מַשְׁכַּן זִמְנָא וְיִתְּנִנּוּן לְכַהֲנָא:",0,0],[15,15,"וְיַעְבֵּד יָתְהוֹן כַּהֲנָא חַד חַטָּאתָא וְחַד עֲלָתָא וִיכַפֵּר עֲלוֹהִי כַּהֲנָא קֳדָם יְיָ מִדּוֹבֵיהּ:",0,0],[15,16,"וּגְבַר אֲרֵי תִפּוֹק מִנֵּיהּ שִׁכְבַת זַרְעָא וְיַסְחֵי בְמַיָּא יָת כָּל בִּשְׂרֵיהּ וִיהֵי מְסָאָב עַד רַמְשָׁא:",0,0],[15,17,"וְכָל לְבוּשׁ וְכָל מְשַׁךְ דִּי יְהֵי עֲלוֹהִי שִׁכְבַת זַרְעָא וְיִצְטַבַּע בְּמַיָּא וִיהֵי מְסָאָב עַד רַמְשָׁא:",0,0],[15,18,"וְאִתְּתָא דִּי יִשְׁכּוּב גְּבַר יָתַהּ שִׁכְבַת זַרְעָא וְיַסְחוּן בְּמַיָּא וְיִסְאֲבוּן עַד רַמְשָׁא:",0,0],[15,19,"וְאִתְּתָא אֲרֵי תְהֵי דָיְבָא דָּם יְהֵי דוֹבַהּ בְּבִשְׂרַהּ שִׁבְעָא יוֹמִין תְּהֵי בְרִיחוּקַהּ וְכָל דְּיִקְרַב בַּהּ יְהֵי מְסָאָב עַד רַמְשָׁא:",0,0],[15,20,"וְכֹל דִּי תִשְׁכּוּב עֲלוֹהִי בְּרִחוּקַהּ יְהֵי מְסָאָב וְכֹל דִּי תֵיתֵב עֲלוֹהִי יְהֵי מְסָאָב:",0,0],[15,21,"וְכָל דְּיִקְרַב בְּמִשְׁכְּבַהּ יְצַבַּע לְבוּשׁוֹהִי וְיַסְחֵי בְמַיָּא וִיהֵי מְסָאָב עַד רַמְשָׁא:",0,0],[15,22,"וְכָל דְּיִקְרַב בְּכָל מָנָא דִּי תֵיתֵב עֲלוֹהִי יְצַבַּע לְבוּשׁוֹהִי וְיַסְחֵי בְמַיָּא וִיהֵי מְסָאָב עַד רַמְשָׁא:",0,0],[15,23,"וְאִם עַל מִשְׁכְּבָא הוּא אוֹ עַל מָנָא דִּי הִא יָתְבָא עֲלוֹהִי בְּמִקְרְבֵיהּ בֵּיהּ יְהֵי מְסָאָב עַד רַמְשָׁא:",0,0],[15,24,"וְאִם מִשְׁכַּב יִשְׁכּוּב גְּבַר יָתַהּ וּתְהֵי רִחוּקַהּ עֲלוֹהִי וִיהֵי מְסָאָב שִׁבְעַת יוֹמִין וְכָל מִשְׁכְּבָא דִּי יִשְׁכּוּב עֲלוֹהִי יְהֵי מְסָאָב:",0,0],[15,25,"וְאִתְּתָא אֲרֵי יְדוּב דּוֹב דְּמַהּ יוֹמִין סַגִּיאִין בְּלָא עִדַּן רִחוּקַהּ אוֹ אֲרֵי תְדוּב עַל רִחוּקַהּ כָּל יוֹמֵי דּוֹב סוֹבְתַהּ כְּיוֹמֵיהּ רִחוּקַהּ תְּהֵי מְסָאֳבָא הִיא:",0,0],[15,26,"כָּל מִשְׁכְּבָא דִּי תִשְׁכּוּב עֲלוֹהִי כָּל יוֹמֵי דוֹבַהּ כְּמִשְׁכַּב רִחוּקַהּ יְהֵי לַהּ וְכָל מָנָא דִּי תֵתֵב עֲלוֹהִי מְסָאָב יְהֵי כְּסוֹאֲבַת רִחוּקַהּ:",0,0],[15,27,"וְכָל דְּיִקְרַב בְּהוֹן יְהֵי מְסָאָב וִיצַבַּע לְבוּשׁוֹהִי וְיַסְחֵי בְמַיָּא וִיהֵי מְסָאָב עַד רַמְשָׁא:",0,0],[15,28,"וְאִם דְּכִיאַת מִדּוֹבַהּ וְתִמְנֵי לַהּ שִׁבְעַת יוֹמִין וּבָתַר כֵּן תִּדְכֵּי:",0,0],[15,29,"וּבְיוֹמָא תְמִינָאָה תִּסַּב לַהּ תַּרְתֵּין שַׁפְנִינִין אוֹ תְּרֵין בְּנֵי יוֹנָה וְתַיְתִי יָתְהוֹן לְוָת כַּהֲנָא לִתְרַע מַשְׁכַּן זִמְנָא:",0,0],[15,30,"וְיַעְבֵּד כַּהֲנָא יָת חַד חַטָּאתָא וְיָת חַד עֲלָתָא וִיכַפֵּר עֲלַהּ כַּהֲנָא קֳדָם יְיָ מִדּוֹב סוֹבְתַהּ:",0,0],[15,31,"וְתַפְרְשׁוּן יָת בְּנֵי יִשְׂרָאֵל מִסּוֹאֲבַתְהוֹן וְלָא יְמוּתוּן בְּסוֹאֲבַתְהוֹן בְּסָאָבְהוֹן יָת מַשְׁכְּנִי דִּי בֵינֵיהוֹן:",0,0],[15,32,"דָּא אוֹרַיְתָא דְּדוֹבְנָא וְדִי תִפּוֹק מִנֵּיהּ שִׁכְבַת זַרְעָא לְאִסְתָּאָבָא בַהּ:",0,0],[15,33,"וְלִדְסָאוּבְתָּא בְּרִיחוּקַהּ וְלִדְדָאִיב יָת דּוֹבֵיהּ לִדְכַר וּלְנֻקְבָּא וְלִגְבַר דִּי יִשְׁכּוּב עִם מְסָאָבָא:",0,0],[16,1,"וּמַלִּיל יְיָ עִם משֶׁה בָּתַר דְּמִיתוּ תְּרֵין בְּנֵי אַהֲרֹן בְּקָרוֹבֵיהוֹן אֶשָּׁתָא נוּכְרֵיתָא קֳדָם יְיָ וּמִיתוּ:",0,0],[16,2,"וַאֲמַר יְיָ לְמשֶׁה מַלֵּל עִם אַהֲרֹן אָחוּךְ וְלָא יְהֵי עָלֵל בְּכָל עִדָּן לְקוּדְשָׁא מִגָּיו לְפָרֻכְתָּא לָקֳדָם כַּפֻּרְתָּא דִּי עַל אֲרוֹנָא וְלָא יְמוּת אֲרֵי בַּעֲנָנָא אֲנָא מִתְגְּלִי עַל בֵּית כַּפֻּרְתָּא:",0,0],[16,3,"בְּדָא יְהֵי עָלֵל אַהֲרֹן לְקוּדְשָׁא בְּתוֹר בַּר תּוֹרֵי לְחַטָּאתָא וּדְכַר לַעֲלָתָא:",0,0],[16,4,"כִּתּוּנָא דְבוּצָא קוּדְשָׁא יִלְבָּשׁ וּמִכְנְסִין דְּבוּץ יְהוֹן עַל בִּסְרֵיהּ וּבְהֶמְיָנָא דְבוּצָא יֵסַר וּבְמִצְנֶפְתָּא דְבוּצָא יָחֵת בְּרֵישֵׁיהּ לְבוּשֵׁי קוּדְשָׁא אִנּוּן וְיַסְחֵי בְמַיָּא יָת בִּסְרֵיהּ וְיַלְבְּשִׁנּוּן:",0,0],[16,5,"וּמִין כְּנִשְׁתָּא דִּבְנֵי יִשְׂרָאֵל יִסַּב תְּרֵין צְפִירֵי עִזִּין לְחַטָּאתָא וּדְכַר חַד לַעֲלָתָא:",0,0],[16,6,"וִיקָרֵב אַהֲרֹן יָת תּוֹרָא דְחַטָּאתָא דִּי לֵיהּ וִיכַפֵּר עֲלוֹהִי וְעַל אֱנַשׁ בֵּיתֵיהּ:",0,0],[16,7,"וְיִסַּב יָת תְּרֵין צְפִירִין וִיקִים יָתְהוֹן קֳדָם יְיָ בִּתְרַע מַשְׁכַּן זִמְנָא:",0,0],[16,8,"וְיִתֵּן אַהֲרֹן עַל תְּרֵין צְפִירִין עַדְבִין עַדְבָא חַד לִשְׁמָא דַיְיָ וְעַדְבָא חַד לַעֲזָאזֵל:",0,0],[16,9,"וִיקָרֵב אַהֲרֹן יָת צְפִירָא דִּי סְלִיק עֲלוֹהִי עַדְבָא לִשְׁמָא דַיְיָ וְיַעְבִּדִנֵיהּ חַטָּאתָא:",0,0],[16,10,"וּצְפִירָא דִּי סְלִיק עֲלוֹהִי עַדְבָא לַעֲזָאזֵל יִתָּקַם כַּד חַי קֳדָם יְיָ לְכַפָּרָא עֲלוֹהִי לְשַׁלַּח יָתֵיהּ לַעֲזָאזֵל לְמַדְבְּרָא:",0,0],[16,11,"וִיקָרֵב אַהֲרֹן יָת תּוֹרָא דְחַטָּאתָא דִּי לֵיהּ וִיכַפֵּר עֲלוֹהִי וְעַל אֱנַשׁ בֵּיתֵיהּ וְיִכּוֹס יָת תּוֹרָא דְחַטָּאתָא דִּי לֵיהּ:",0,0],[16,12,"וְיִסַּב מְלֵי מַחְתִּיתָא גּוּמְרִין דְּאֶשָּׁא מֵעִלַּוֵי מַדְבְּחָא מִן קֳדָם יְיָ וּמְלֵי חָפְנוֹהִי קְטוֹרֶת בּוּסְמִין דַּקִּיקִין וְיָעֵל מִגָּיו לְפָרֻכְתָּא:",0,0],[16,13,"וְיִתֵּן יָת קְטוֹרֶת בּוּסְמַיָּא עַל אֶשָּׁתָא לָקֳדָם יְיָ וְחָפֵי עֲנָנָא קְטָרְתָּא יָת כַּפֻּרְתָּא דִּי עַל סַהֲדוּתָא וְלָא יְמוּת:",0,0],[16,14,"וְיִסַּב מִדְּמָא דְתוֹרָא וְיַדִּי בְאֶצְבְּעֵיהּ עַל אַפֵּי כַּפֻּרְתָּא קִדּוּמָא וְלָקֳדָם כַּפֻּרְתָּא יַדִּי שְׁבַע זִמְנִין מִן דְּמָא בְּאֶצְבְּעֵיהּ:",0,0],[16,15,"וְיִכּוֹס יָת צְפִירָא דְחַטָּאתָא דִּי לְעַמָּא וְיָעֵל יָת דְּמֵיהּ לְמִגָּיו לְפָרֻכְתָּא וְיַעְבֵּד לִדְמֵיהּ כְּמָא דִי עֲבַד לִדְמָא דְתוֹרָא וְיַדִּי יָתֵיהּ עַל כַּפֻּרְתָּא וְלָקֳדָם כַּפֻּרְתָּא:",0,0],[16,16,"וִיכַפֵּר עַל קוּדְשָׁא מִסּוֹאֲבַת בְּנֵי יִשְׂרָאֵל וּמִמֶּרְדֵּיהוֹן לְכָל חֲטָאֵיהוֹן וְכֵן יַעְבֵּד לְמַשְׁכַּן זִמְנָא דְּשָׁרֵי עִמְּהוֹן בְּגוֹ סוֹאֲבָתְהוֹן:",0,0],[16,17,"וְכָל אֱנַשׁ לָא יְהֵי בְּמַשְׁכַּן זִמְנָא בְּמֵעֲלֵיהּ לְכַפָּרָא בְקוּדְשָׁא עַד מִפְּקֵיהּ וִיכַפֵּר עֲלוֹהִי וְעַל אֱנַשׁ בֵּיתֵיהּ וְעַל כָּל קְהָלָא דְיִשְׂרָאֵל:",0,0],[16,18,"וְיִפּוֹק לְמַדְבְּחָא דִּי קֳדָם יְיָ וִיכַפֵּר עֲלוֹהִי וְיִסַּב מִדְּמָא דְתוֹרָא וּמִדְּמָא דִצְפִירָא וְיִתֵּן עַל קַרְנַת מַדְבְּחָא סְחוֹר סְחוֹר:",0,0],[16,19,"וְיַדֵּי עֲלוֹהִי מִן דְּמָא בְּאֶצְבְּעֵיהּ שְׁבַע זִמְנִין וִידַכִּנֵּיהּ וִיקַדְּשִׁנֵּיהּ מִסּוֹאֲבַת בְּנֵי יִשְׂרָאֵל:",0,0],[16,20,"וִישֵׁצֵי מִלְּכַפָּרָא עַל קוּדְשָׁא וְעַל מַשְׁכַּן זִמְנָא וְעַל מַדְבְּחָא וִיקָרֵב יָת צְפִירָא חַיָּא:",0,0],[16,21,"וְיִסְמוֹךְ אַהֲרֹן יָת תַּרְתֵּין יְדוֹהִי עַל רֵישׁ צְפִירָא חַיָּא וְיִוַדֵּי עֲלוֹהִי יָת כָּל עֲוָיַת בְּנֵי יִשְׂרָאֵל וְיָת כָּל מֶרְדֵּיהוֹן לְכָל חֲטָאֵיהוֹן וְיִתֵּן יָתְהוֹן עַל רֵישׁ צְפִירָא וִישַׁלַּח בְּיַד גְּבַר דִּזְמִין לִמְהַךְ לְמַדְבְּרָא:",0,0],[16,22,"וְיִטּוֹל צְפִירָא עֲלוֹהִי יָת כָּל חוֹבֵיהוֹן לְאַרְעָא דְלָא יָתְבָא וִישַׁלַּח יָת צְפִירָא בְּמַדְבְּרָא:",0,0],[16,23,"וְיֵיעוֹל אַהֲרֹן לְמַשְׁכַּן זִמְנָא וְיַשְׁלַח יָת לְבוּשֵׁי בוּצָא דִּי לְבַשׁ בְּמֵעֲלֵיהּ לְקוּדְשָׁא וְיַצְנְעִנּוּן תַּמָּן:",0,0],[16,24,"וְיַסְחֵי יָת בִּסְרֵיהּ בְּמַיָּא בַּאֲתַר קַדִּישׁ וְיִלְבַּשׁ יָת לְבוּשׁוֹהִי וְיִפּוֹק וְיַעְבֵּד יָת עֲלָתֵיהּ וְיָת עֲלַת עַמָּא וִיכַפַּר עֲלוֹהִי וְעַל עַמָּא:",0,0],[16,25,"וְיָת תַּרְבָּא דְחַטָּאתָא יַסֵּק לְמַדְבְּחָא:",0,0],[16,26,"וּדְמוֹבִיל יָת צְפִירָא לַעֲזָאזֵל יְצַבַּע לְבוּשׁוֹהִי וְיַסְחֵי יָת בִּסְרֵיהּ בְּמַיָּא וּבָתַר כֵּן יֵיעוֹל לְמַשְׁרִיתָא:",0,0],[16,27,"וְיָת תּוֹרָא דְחַטָּאתָא וְיָת צְפִירָא דְחַטָּאתָא דִּי אִתָּעַל מִדִּמְהוֹן לְכַפָּרָא בְקוּדְשָׁא יִתַּפְּקוּן לְמִבָּרָא לְמַשְׁרִיתָא וְיוֹקְדוּן בְּנוּרָא יָת מַשְׁכֵּיהוֹן וְיָת בִּסְרְהוֹן וְיָת אָכְלֵיהוֹן:",0,0],[16,28,"וּדְמוֹקִיד יָתְהוֹן יְצַבַּע לְבוּשׁוֹהִי וְיַסְחֵי יָת בִּסְרֵיהּ בְּמַיָּא וּבָתַר כֵּן יֵיעוֹל לְמַשְׁרִיתָא:",0,0],[16,29,"וּתְהֵי לְכוֹן לִקְיַם עָלָם בְּיַרְחָא שְׁבִיעָאָה בְּעַשְׂרָא לְיַרְחָא תְּעַנּוּן יָת נַפְשָׁתֵיכוֹן וְכָל עִבִידָא לָא תַעְבְּדוּן יַצִּיבָא וְגִיּוֹרָא דְּיִתְגַּיְּרוּן בֵּינֵיכוֹן:",0,0],[16,30,"אֲרֵי בְיוֹמָא הָדֵין יְכַפֵּר עֲלֵיכוֹן לְדַכָּאָה יָתְכוֹן מִכֹּל חוֹבֵיכוֹן קֳדָם יְיָ תִּדְכּוּן:",0,0],[16,31,"שְׁבַת שְׁבָתָא הִיא לְכוֹן וּתְעַנּוּן יָת נַפְשָׁתֵיכוֹן קְיַם עֲלָם:",0,0],[16,32,"וִיכַפַּר כַּהֲנָא דִּי רַבִּי יָתֵיהּ וְדִי יְקָרֵב יָת קֻרְבָּנֵיהּ לְשַׁמָּשָׁא תְּחוֹת אֲבוּהִי וְיִלְבַּשׁ יָת לְבוּשֵׁי בוּצָא לְבוּשֵׁי קוּדְשָׁא:",0,0],[16,33,"וִיכַפַּר עַל מִקְדַּשׁ קוּדְשָׁא וְעַל מַשְׁכַּן זִמְנָא וְעַל מַדְבְּחָא יְכַפַּר וְעַל כַּהֲנַיָּא וְעַל כָּל עַמָּא דִקְהָלָא יְכַפַּר:",0,0],[16,34,"וּתְהֵי דָא לְכוֹן לִקְיַם עָלָם לְכַפָּרָא עַל בְּנֵי יִשְׂרָאֵל מִכָּל חוֹבֵיהוֹן חֲדָא בְּשַׁתָּא וַעֲבַד כְּמָא דִי פַקֵּיד יְיָ יָת משֶׁה:",0,0],[17,1,"וּמַלִּיל יְיָ עִם משֶׁה לְמֵימָר:",0,0],[17,2,"מַלֵּל עִם אַהֲרֹן וְעִם בְּנוֹהִי וְעִם כָּל בְּנֵי יִשְׂרָאֵל וְתֵימַר לְהוֹן דֵּין פִּתְגָּמָא דִּי פַקִּיד יְיָ לְמֵימָר:",0,0],[17,3,"גְּבַר גְּבַר מִבֵּית יִשְׂרָאֵל דִּי יִכּוֹס תּוֹר אוֹ אִמַּר אוֹ עִזָּא בְּמַשְׁרִיתָא אוֹ דִּי יִכּוֹס מִבָּרָא לְמַשְׁרִיתָא:",0,0],[17,4,"וְלִתְרַע מַשְׁכַּן זִמְנָא לָא אַיְתֵיהּ לְקָרָבָא קֻרְבָּנָא קֳדָם יְיָ קֳדָם מַשְׁכְּנָא דַיְיָ דְּמָא יִתְחַשַּׁב לְגַבְרָא הַהוּא דְּמָא אֲשַׁד וְיִשְׁתֵּיצֵי אֲנָשָׁא הַהוּא מִגּוֹ עַמֵּיהּ:",0,0],[17,5,"בְּדִיל דִּי יַיְתוּן בְּנֵי יִשְׂרָאֵל יָת דִּבְחֵיהוֹן דִּי אִנּוּן דָּבְחִין עַל אַפֵּי חַקְלָא וְיַיְתֻנּוּן לָקֳדָם יְיָ לִתְרַע מַשְׁכַּן זִמְנָא לְוָת כַּהֲנָא וְיִכְּסוּן נִכְסַת קוּדְשִׁין קֳדָם יְיָ יָתְהוֹן:",0,0],[17,6,"וְיִזְרוֹק כַּהֲנָא יָת דְּמָא עַל מַדְבְּחָא דַיְיָ בִּתְרַע מַשְׁכַּן זִמְנָא וְיַסֵּק תַּרְבָּא לְאִתְקַבָּלָא בְרַעֲוָא קֳדָם יְיָ:",0,0],[17,7,"וְלָא יִדְבְּחוּן עוֹד יָת דִּבְחֵיהוֹן לַשֵּׁדִין דִּי אִנּוּן טָעָן בַּתְרֵיהוֹן קְיַם עָלָם תְּהֵי דָא לְהוֹן לְדָרֵיהוֹן:",0,0],[17,8,"וּלְהוֹן תֵּימַר גְּבַר גְּבַר מִבֵּית יִשְׂרָאֵל וּמִן גִּיּוֹרָא דְּיִתְגַּיְּרוּן בֵּינֵיכוֹן דִּי יַסֵּק עֲלָתָא אוֹ נִכְסַת קוּדְשַׁיָּא:",0,0],[17,9,"וְלִתְרַע מַשְׁכַּן זִמְנָא לָא אַיְתִנֵּיהּ לְמֶעְבַּד יָתֵיהּ קֳדָם יְיָ וְיִשְׁתֵּיצֵי אֲנָשָׁא הַהוּא מֵעַמֵּיהּ:",0,0],[17,10,"וּגְבַר גְּבַר מִבֵּית יִשְׂרָאֵל וּמִן גִּיּוֹרָא דְּיִתְגַּיְּרוּן בֵּינֵיכוֹן דִּי יֵיכוּל כָּל דְּמָא וְאֶתֵּן רוּגְזִי בַּאֲנָשָׁא דְּיֵכוּל יָת דְּמָא וֶאֱשֵׁיצֵי יָתֵיהּ מִגּוֹ עַמֵּיהּ:",0,0],[17,11,"אֲרֵי נְפַשׁ בִּסְרָא בִּדְמָא הִיא וַאֲנָא יְהָבִתֵּיהּ לְכוֹן עַל מַדְבְּחָא לְכַפָּרָא עַל נַפְשָׁתֵיכוֹן אֲרֵי דְמָא הוּא עַל נַפְשָׁא מְכַפֵּר:",0,0],[17,12,"עַל כֵּן אֲמָרִית לִבְנֵי יִשְׂרָאֵל כָּל אֱנַשׁ מִנְּכוֹן לָא יֵיכוּל דְּמָא וְגִיּוֹרָא דְּיִתְגַּיְּרוּן בֵּינֵיכוֹן לָא יֵיכוּל דְּמָא:",0,0],[17,13,"וּגְבַר גְּבַר מִן בְּנֵי יִשְׂרָאֵל וּמִין גִּיּוֹרָא דְּיִתְגַּיְּרוּן בֵּינֵיכוֹן דִּי יְצוּד צֵידָא חַיְתָא אוֹ עוֹפָא דִּי מִתְאֲכֵל וְיֵישׁוֹד יָת דְּמֵיהּ וִיכַסִּנֵּיהּ בְּעַפְרָא:",0,0],[17,14,"אֲרֵי נְפַשׁ כָּל בִּסְרָא דְּמֵיהּ בְּנַפְשֵׁיהּ הוּא וַאֲמָרִית לִבְנֵי יִשְׂרָאֵל דַּם כָּל בִּסְרָא לָא תֵיכְלוּן אֲרֵי נְפַשׁ כָּל בִּסְרָא דְּמֵיהּ הִיא כָּל דְּיֵכְלִנֵּיהּ יִשְׁתֵּיצֵי:",0,0],[17,15,"וְכָל אֱנַשׁ דִּי יֵיכוּל נְבִילָא וּתְבִירָא בְּיַצִּיבָא וּבְגִיּוֹרָא וִיצַבַּע לְבוּשׁוֹהִי וְיַסְחֵי בְמַיָּא וִיהֵי מְסָאָב עַד רַמְשָׁא וְיִדְכֵּי:",0,0],[17,16,"וְאִם לָא יְצַבַּע וּבִסְרֵיהּ לָא יַסְחֵי וִיקַבֵּל חוֹבֵיהּ:",0,0],[18,1,"וּמַלִּיל יְיָ עִם משֶׁה לְמֵימָר:",0,0],[18,2,"מַלֵּל עִם בְּנֵי יִשְׂרָאֵל וְתֵימַר לְהוֹן אֲנָא יְיָ אֱלָהָכוֹן:",0,0],[18,3,"כְּעוֹבָדֵי עַמָּא דְאַרְעָא דְמִצְרַיִם דִּי יְתֶבְתּוּן בַּהּ לָא תַעְבְּדוּן וּכְעוֹבָדֵי עַמָּא דְאַרְעָא דִכְנַעַן דִּי אֲנָא מָעֵל יָתְכוֹן תַּמָּן לָא תַעְבְּדוּן וּבְנִימוֹסֵיהוֹן לָא תְהָכוּן:",0,0],[18,4,"יָת דִּינַי תַּעְבְּדוּן וְיָת קְיָמַי תִּטְּרוּן לְהַלָּכָא בְּהוֹן אֲנָא יְיָ אֱלָהָכוֹן:",0,0],[18,5,"וְתִטְּרוּן יָת קְיָמַי וְיָת דִּינַי דִּי יַעְבֵּד יָתְהוֹן אֲנָשָׁא וְיֵחֵי בְהוֹן לְחַיֵּי עָלְמָא אֲנָא יְיָ:",0,0],[18,6,"גְּבַר גְּבַר לְכָל קָרִיב בִּסְרֵיהּ לָא תִקְרְבוּן לְגַלָּאָה עֶרְיָא אֲנָא יְיָ:",0,0],[18,7,"עֶרְיַת אֲבוּךְ וְעֶרְיַת אִמָּךְ לָא תְגַלֵּי אִמָּךְ הִיא לָא תְגַלֵּי עֶרְיְתַהּ:",0,0],[18,8,"עֶרְיַת אִתַּת אָבוּךְ לָא תְגַלֵּי עֶרְיַת אֲבוּךְ הִיא:",0,0],[18,9,"עֶרְיַת אֲחָתָךְ בַּת אֲבוּךְ אוֹ בַת אִמָּךְ דִּילִידָא מִן אֲבוּךְ מִן אִתַּת אָחֳרִי אוֹ מִן אִמָּךְ לִגְבַר אָחֳרָן לָא תְגַלֵּי עֶרְיַתְהֶן:",0,0],[18,10,"עֶרְיַת בַּת בְּרָךְ אוֹ בַת בְּרַתָּךְ לָא תְגַלֵּי עֶרְיַתְהֵן אֲרֵי עֶרְיְתָךְ אִנּוּן:",0,0],[18,11,"עֶרְיַת בַּת אִתַּת אֲבוּךְ דִּילִידָא מִן אֲבוּךְ אֲחָתָךְ הִיא לָא תְגַלֵּי עֶרְיְתַהּ:",0,0],[18,12,"עֶרְיַת אֲחַת אֲבוּךְ לָא תְגַלֵּי קָרִיבַת אֲבוּךְ הִיא:",0,0],[18,13,"עֶרְיַת אֲחַת אִמָּךְ לָא תְגַלֵּי אֲרֵי קָרִיבַת אִמָּךְ הִיא:",0,0],[18,14,"עֶרְיַת אַח אֲבוּךְ לָא תְגַלֵּי לְאִתְּתֵיהּ לָא תִקְרַב אִתַּת אַח אֲבוּךְ הִיא:",0,0],[18,15,"עֶרְיַת כַּלְּתָךְ לָא תְגַלֵּי אִתַּת בְּרָךְ הִיא לָא תְגַלֵּי עֶרְיְתַהּ:",0,0],[18,16,"עֶרְיַת אִתַּת אֲחוּךְ לָא תְגַלֵּי עֶרְיַת אֲחוּךְ הִיא:",0,0],[18,17,"עֶרְיַת אִתְּתָא וּבְרַתַּהּ לָא תְגַלֵּי יָת בַּת בְּרַהּ וְיָת בַּת בְּרַתַּהּ לָא תִסַּב לְגַלָּאָה עֶרְיְתַהּ קָרִיבָן אִנּוּן עֵצַת חִטְאִין הִיא:",0,0],[18,18,"וְאִתְּתָא עִם אֲחָתַהּ לָא תִסָּב לְעָקָאָה לְגַלָּאָה עֶרְיְתַהּ עֲלַהּ בְּחַיָּיהָא:",0,0],[18,19,"וּלְאִתְּתָא בְּרִחוּק סוֹבְתַהּ לָא תִקְרַב לְגַלָּאָה עֶרְיְתַהּ:",0,0],[18,20,"וּבְאִתַּת חַבְרָךְ לָא תִתֵּן שְׁכֻבְתָּךְ לְזַרְעָא לְאִסְתָּאָבָא בַהּ:",0,0],[18,21,"וּמִבְּנָיךְ לָא תִתֵּן לְאַעְבָּרָא לְמוֹלֶךְ וְלָא תַחֵל יָת שְׁמָא דֶאֱלָהָךְ אֲנָא יְיָ:",0,0],[18,22,"וְעִם דְּכוּרָא לָא תִשְׁכּוּב מִשְׁכְּבֵי אִתְּתָא תּוֹעֶבְתָּא הִיא:",0,0],[18,23,"וּבְכָל בְּעִירָא לָא תִתֵּן שְׁכֻבְתָּךְ לְאִסְתָּאָבָא בַהּ וְאִתְּתָא לָא תְקוּם קֳדָם בְּעִירָא לְמִשְׁלַט בַּהּ תִּבְלָא הוּא:",0,0],[18,24,"לָא תִסְתַּאֲבוּן בְּכָל אִלֵּין אֲרֵי בְכָל אִלֵּין אִסְתָּאָבוּ עַמְמַיָּא דִּי אֲנָא מַגְלֵי מִן קֳדָמֵיכוֹן:",0,0],[18,25,"וְאִסְתָּאָבַת אַרְעָא וְאַסְעָרִית חוֹבַהּ עֲלַהּ וְרוֹקֵינַת אַרְעָא יָת יָתְבָהָא:",0,0],[18,26,"וְתִטְּרוּן אַתּוּן יָת קְיָמַי וְיָת דִּינַי וְלָא תַעְבְּדוּן מִכֹּל תּוֹעֶבְתָּא הָאִלֵּין יַצִּיבָא וְגִיּוֹרָא דְּיִתְגַּיְּרוּן בֵּינֵיכוֹן:",0,0],[18,27,"אֲרֵי יָת כָּל תּוֹעֶבְתָּא הָאִלֵּין עֲבָדוּ אֱנָשֵׁי אַרְעָא דִּי קֳדָמֵיכוֹן וְאִסְתָּאָבַת אַרְעָא:",0,0],[18,28,"וְלָא תְרוֹקֵן אַרְעָא יָתְכוֹן בְּסָאֳבֵיכוֹן יָתַהּ כְּמָא דְרוֹקֵינַת יָת עַמְמַיָּא דִּי קֳדָמֵיכוֹן:",0,0],[18,29,"אֲרֵי כָּל דִּי יַעְבֵּד מִכֹּל תּוֹעֶבְתָּא הָאִלֵּין וְיִשְׁתֵּיצוּן נַפְשָׁתָא דִיַעְבְּדוּן מִגּוֹ עַמְּהוֹן:",0,0],[18,30,"וְתִטְּרוּן יָת מַטְּרַת מֵימְרִי בְּדִיל דְּלָא לְמֶעְבַּד מִנִּימוֹסֵי תוֹעֶבְתָּא דְּאִתְעֲבָדָא קֳדָמֵיכוֹן וְלָא תִסְתַּאֲבוּן בְּהוֹן אֲנָא יְיָ אֱלָהָכוֹן:",0,0],[19,1,"וּמַלִּיל יְיָ עִם משֶׁה לְמֵימָר:",0,0],[19,2,"מַלֵּל עִם כָּל כְּנִשְׁתָּא דִבְנֵי יִשְׂרָאֵל וְתֵימַר לְהוֹן קַדִּישִׁין תְּהוֹן אֲרֵי קַדִּישׁ אֲנָא יְיָ אֱלָהָכוֹן:",0,0],[19,3,"גְּבַר מִן אִמֵּיהּ וּמִן אֲבוּהִי תְּהוֹן דָּחֲלִין וְיָת יוֹמֵי שַׁבַּיָּא דִילִי תִּטְרוּן אֲנָא יְיָ אֱלָהָכוֹן:",0,0],[19,4,"לָא תִתְפְּנוּן בָּתַר טַעֲוָן וְדַחֲלָן דְּמַתְּכָא לָא תַעְבְּדוּן לְכוֹן אֲנָא יְיָ אֱלָהָכוֹן:",0,0],[19,5,"וַאֲרֵי תִכְּסוּן נִכְסַת קוּדְשַׁיָּא קֳדָם יְיָ לְרַעֲוָא לְכוֹן תִּכְּסֻנֵּיהּ:",0,0],[19,6,"בְּיוֹמָא דְיִתְנְכֵס יִתְאֲכֵל וּבְיוֹמָא דְבַתְרוֹהִי וּדְאִשְׁתָּאַר עַד יוֹמָא תְלִיתָאָה בְּנוּרָא יִתּוֹקָד:",0,0],[19,7,"וְאִם אִתְאֲכָלָא יִתְאֲכֵל בְּיוֹמָא תְלִיתָאָה מְרָחָק הוּא לָא יְהֵי לְרַעֲוָא:",0,0],[19,8,"וּדְיֵיכְלִנֵּיהּ חוֹבֵיהּ יְקַבֵּל אֲרֵי יָת קוּדְשָׁא דַיְיָ אַחֵל וְיִשְׁתֵּיצֵי אֲנָשָׁא הַהוּא מְעַמֵּיהּ:",0,0],[19,9,"וּבְמֶחְצָדְכוֹן יָת חֲצָדָא דְאַרְעֲכוֹן לָא תְשֵׁיצֵי פָּאתָא דְחַקְלָךְ לְמֶחְצָד וּלְקָטָא דַחֲצָדָךְ לָא תְלַקֵּט:",0,0],[19,10,"וְכַרְמָךְ לָא תְעָלֵל וְנִתְרָא דְכַרְמָךְ לָא תְלַקֵּט לְעַנְיֵי וּלְגִיּוֹרֵי תִּשְׁבּוֹק יָתְהוֹן אֲנָא יְיָ אֱלָהָכוֹן:",0,0],[19,11,"לָא תִּגְנְבוּן וְלָא תְכַדְּבוּן וְלָא תְשַׁקְּרוּן אֱנַשׁ בְּחַבְרֵיהּ:",0,0],[19,12,"וְלָא תִשָּׁבְעוּן בִּשְׁמִי לְשִׁקְרָא וְתַחֵל יָת שְׁמָא דֶאֱלָהָךְ אֲנָא יְיָ:",0,0],[19,13,"לָא תַעֲשׁוֹק יָת חַבְרָךְ וְלָא תְאַנֵּס לָא תְבִית אַגְרָא דַאֲגִירָא לְוָתָךְ עַד צַפְרָא:",0,0],[19,14,"לָא תְלוּט דְּלָא שָׁמַע וְקֳדָם דְּלָא חָזֵי לָא תְשִׂים תַּקְלָא וְתִדְחַל מֵאֱלָהָךְ אֲנָא יְיָ:",0,0],[19,15,"לָא תַעְבְּדוּן שְׁקַר בְּדִינָא לָא תִסַּב אַפֵּי מַסְכֵּנָא וְלָא תֶהְדַּר אַפֵּי רַבָּא בְּקוּשְׁטָא תְּדִינֵיהּ לְחַבְרָךְ:",0,0],[19,16,"לָא תֵיכוּל קוּרְצִין בְּעַמָּךְ לָא תְקוּם עַל דְּמָא דְחַבְרָךְ אֲנָא יְיָ:",0,0],[19,17,"לָא תִשְׂנֵי יָת אֲחוּךְ בְּלִבָּךְ אוֹכָחָא תוֹכַח יָת חַבְרָךְ וְלָא תְקַבֵּל עַל דִּי לֵיהּ חוֹבָא:",0,0],[19,18,"לָא תִקּוֹם וְלָא תִטַּר דְּבָבוּ לִבְנֵי עַמָּךְ וּתְרַחֵם לְחַבְרָךְ כְּוָתָךְ אֲנָא יְיָ:",0,0],[19,19,"יָת קְיָמַי תִּטְּרוּן בְּעִירָךְ לָא תַרְכֵּב עֵרוּבִין חַקְלָךְ לָא תִזְרַע עֵרוּבִין וּלְבוּשׁ עֵרוּבִין שַׁעַטְנֵזָא לָא יִסַּק עֲלָךְ:",0,0],[19,20,"וּגְבַר אֲרֵי יִשְׁכּוּב עִם אִתְּתָא שִׁכְבַת זַרְעָא וְהִיא אַמְתָא אֲחִידָא לִגְבַר וְאִתְפְּרָקָא לָא אִתְפְּרִיקַת בְּכַסְפָּא אוֹ חֵרוּתָא לָא אִתְיְהִיבַת לַהּ בִּשְׁטָר בִּקֻּרְתָּא תְהֵי לָא יוּמְתוּן אֲרֵי לָא אִתְחָרָרַת:",0,0],[19,21,"וְיַיְתִי יָת אַשְׁמֵיהּ קֳדָם יְיָ לִתְרַע מַשְׁכַּן זִמְנָא דְּכַר לַאֲשָׁמָא:",0,0],[19,22,"וִיכַפֵּר עֲלוֹהִי כַהֲנָא בְּדִכְרָא דַאֲשָׁמָא קֳדָם יְיָ עַל חוֹבְתֵיהּ דִּי חָב וְיִשְׁתְּבֵק לֵיהּ מֵחוֹבְתֵיהּ דִּי חָב:",0,0],[19,23,"וַאֲרֵי תֵעֲלוּן לְאַרְעָא וְתִצְּבוּן כָּל אִלַּן דְּמֵיכַל וּתְרַחֲקוּן רָחָקָא יָת אִבֵּיהּ תְּלַת שְׁנִין יְהֵי לְכוֹן מְרָחָק לַאֲבָדָא לָא יִתְאֲכֵל:",0,0],[19,24,"וּבְשַׁתָּא רְבִיעֵתָא יְהֵי כָּל אִבֵּיהּ קֹדֶשׁ תֻּשְׁבְּחָן קֳדָם יְיָ:",0,0],[19,25,"וּבְשַׁתָּא חֲמִשֵּׁתָא תֵּיכְלוּן יָת אִבֵּיהּ לְאוֹסָפָא לְכוֹן עֲלַלְתֵּיהּ אֲנָא יְיָ אֱלָהָכוֹן:",0,0],[19,26,"לָא תֵיכְלוּן עַל דְּמָא לָא תְנַחֲשׁוּן וְלָא תְעוֹנוּן:",0,0],[19,27,"לָא תַקְּפוּן פָּאתָא דְרֵישְׁכוֹן וְלָא תְחַבֵּל יָת פָּאתָא דְדִקְנָךְ:",0,0],[19,28,"וְחִבּוּל עַל מִית לָא תִתְּנוּן בְּבִסְרְיכוֹן וְרוּשְׁמִין חֲרִיתִין לָא תִתְּנוּן בְּכוֹן אֲנָא יְיָ:",0,0],[19,29,"לָא תַחֵל יָת בְּרַתָּךְ לְאַטְעֲיוּתַהּ וְלָא תִטְעֵי אַרְעָא וְתִתְמְלֵי אַרְעָא עֵצַת חִטְאִין:",0,0],[19,30,"יָת יוֹמֵי שַׁבַּיָּא דִילִי תִּטְרוּן וּלְבֵית מַקְדְּשִׁי תְּהוֹן דַּחֲלִין אֲנָא יְיָ:",0,0],[19,31,"לָא תִתְפְּנוּן בָּתַר בִּדִּין וּדְכוּרוּ לָא תִתְבְּעוּן לְאִסְתָּאָבָא בְּהוֹן אֲנָא יְיָ אֱלָהָכוֹן:",0,0],[19,32,"מִן קֳדָם דְּסַבַּר בְּאוֹרַיְתָא תְּקוּם וּתְהַדַּר אַפֵּי סָבָא וְתִדְחַל מֵאֱלָהָךְ אֲנָא יְיָ:",0,0],[19,33,"וַאֲרֵי יִתְגַּיַּר עִמָּךְ גִּיּוֹרָא בְּאַרְעֲכוֹן לָא תוֹנוּן יָתֵיהּ:",0,0],[19,34,"כְּיַצִּיבָא מִנְּכוֹן יְהֵי לְכוֹן גִּיּוֹרָא דְּיִתְגַּיַּר בֵּינֵיכוֹן וּתְרַחֵם לֵיהּ כְּוָתָךְ אֲרֵי דַיָּרִין הֲוֵיתוּן בְּאַרְעָא דְמִצְרָיִם אֲנָא יְיָ אֱלָהָכוֹן:",0,0],[19,35,"לָא תַעְבְּדוּן שְׁקַר בְּדִין בִּמְשַׁחְתָּא בְּמַתְקְלָא וּבִמְכִלְתָּא:",0,0],[19,36,"מֹאזְנָוָן דִּקְשׁוֹט מַתְקְלָן דִּקְשׁוֹט מְכִילָן דִּקְשׁוֹט וְהִינִין דִּקְשׁוֹט יְהוֹן לְכוֹן אֲנָא יְיָ אֱלָהָכוֹן דִּי אַפֵּקִית יָתְכוֹן מֵאַרְעָא דְמִצְרָיִם:",0,0],[19,37,"וְתִטְּרוּן יָת כָּל קְיָמַי וְיָת כָּל דִּינַי וְתַעְבְּדוּן יָתְהוֹן אֲנָא יְיָ:",0,0],[20,1,"וּמַלִּיל יְיָ עִם משֶׁה לְמֵימָר:",0,0],[20,2,"וְעִם בְּנֵי יִשְׂרָאֵל תֵּימַר גְּבַר גְּבַר מִבְּנֵי יִשְׂרָאֵל וּמִין גִּיּוֹרָא דְּיִתְגַּיְרוּן בְּיִשְׂרָאֵל דִּי יִתֵּן מִזַּרְעֵיהּ לְמוֹלֶךְ אִתְקְטָלָא יִתְקְטֵל עַמָּא בֵית יִשְׂרָאֵל יִרְגְּמֻנֵּיהּ בְּאַבְנָא:",0,0],[20,3,"וַאֲנָא אֶתֵּן יָת רוּגְזִי בְּגַבְרָא הַהוּא וֶאֱשֵׁיצֵי יָתֵיהּ מִגּוֹ עַמֵּיהּ אֲרֵי מִזַּרְעֵיהּ יְהַב לְמוֹלֶךְ בְּדִיל לְסָאֲבָא יָת מַקְדְּשִׁי וּלְאַחַלָּא יָת שְׁמָא דְקוּדְשִׁי:",0,0],[20,4,"וְאִם מִכְבַּשׁ יִכְבְּשׁוּן עַמָּא בֵית יִשְׂרָאֵל יָת עֵינֵיהוֹן מִן גַּבְרָא הַהוּא בִּדְיָהֵב מִזַּרְעֵיהּ לְמוֹלֶךְ בְּדִיל דְּלָא לְקַטָּלָא יָתֵיהּ:",0,0],[20,5,"וֶאֱשַׁוֵּי אֲנָא יָת רוּגְזִי בְּגַבְרָא הַהוּא וּבִסְעָדוֹהִי וֶאֱשֵׁיצֵי יָתֵיהּ וְיָת כָּל דְּטָעָן בַּתְרוֹהִי לְמִטְעֵי בָּתַר מוֹלֶךְ מִגּוֹ עַמְּהוֹן:",0,0],[20,6,"וֶאֱנַשׁ דִּי יִתְפְּנֵי בָּתַר בִּדִּין וּדְכוּרוּ לְמִטְעֵי בַתְרֵיהוֹן וְאֶתֵּן יָת רוּגְזִי בַּאֲנָשָׁא הַהִיא וֶאֱשֵׁיצֵי יָתֵיהּ מִגּוֹ עַמֵּיהּ:",0,0],[20,7,"וְתִתְקַדְּשׁוּן וּתְהוֹן קַדִּישִׁין אֲרֵי אֲנָא יְיָ אֱלָהָכוֹן:",0,0],[20,8,"וְתִטְּרוּן יָת קְיָמַי וְתַעְבְּדוּן יָתְהוֹן אֲנָא יְיָ מְקַדִּשְׁכוֹן:",0,0],[20,9,"אֲרֵי גְבַר גְּבַר דִּי יְלוּט יָת אֲבוּהִי וְיָת אִמֵּיהּ אִתְקְטָלָא יִתְקְטֵל אֲבוּהִי וְאִמֵּיהּ לַט קְטָלָא חַיָּב:",0,0],[20,10,"וּגְבַר דִּי יְגוּף יָת אִתַּת גְּבַר דִּי יְגוּף יָת אִתַּת חַבְרֵיהּ אִתְקְטָלָא יִתְקְטֵל גַּיָּפָא וְגַיַּפְתָּא:",0,0],[20,11,"וּגְבַר דִּי יִשְׁכּוּב עִם אִתַּת אֲבוּהִי עֶרְיְתָא דַאֲבוּהִי גַּלִּי אִתְקְטָלָא יִתְקַטְּלוּן תַּרְוֵיהוֹן קְטָלָא חַיָּבִין:",0,0],[20,12,"וּגְבַר דִּי יִשְׁכּוּב יָת כַּלְּתֵיהּ אִתְקְטָלָא יִתְקַטְּלוּן תַּרְוֵיהוֹן תִּבְלָא עֲבָדוּ קְטָלָא חַיָּבִין:",0,0],[20,13,"וּגְבַר דִּי יִשְׁכּוּב יָת דְּכוּרָא מִשְׁכְּבֵי אִתְּתָא תּוֹעֶבְתָּא עֲבָדוּ תַּרְוֵיהוֹן אִתְקְטָלָא יִתְקַטְּלוּן קְטָלָא חַיָּבִין:",0,0],[20,14,"וּגְבַר דִּי יִסַּב יָת אִתְּתָא וְיָת אִמַּהּ עֵצַת חִטְאִין הִיא בְּנוּרָא יוֹקְדוּן יָתֵיהּ וְיָתְהֶן וְלָא תְהֵי עֵצַת חִטְאִין בֵּינֵיכוֹן:",0,0],[20,15,"וּגְבַר דִּי יִתֵּן שְׁכָבְתֵּיהּ בִּבְעִירָא אִתְקְטָלָא יִתְקְטֵל וְיָת בְּעִירָא תִּקְטְלוּן:",0,0],[20,16,"וְאִתְּתָא דִּי תִקְרַב לְכָל בְּעִירָא לְמִשְׁלַט בַּהּ וְתִקְטוֹל יָת אִתְּתָא וְיָת בְּעִירָא אִתְקְטָלָא יִתְקַטְּלוּן קְטָלָא חַיָּבִין:",0,0],[20,17,"וּגְבַר דִּי יִסַּב יָת אֲחָתֵיהּ בַּת אֲבוּהִי אוֹ בַת אִמֵּיהּ וְיֶחֱזֵי יָת עֶרְיְתַהּ וְהִיא תֶחֱזֵי יָת עֶרְיְתֵיהּ קְלָנָא הוּא וְיִשְׁתֵּיצוּן לְעֵינֵי בְּנֵי עַמְּהוֹן עֶרְיַת אֲחָתֵיהּ גַּלִּי חוֹבֵיהּ יְקַבֵּל:",0,0],[20,18,"וּגְבַר דִּי יִשְׁכּוּב יָת אִתְּתָא סוֹאֲבָתָא וִיגַלִּי יָת עֶרְיְתַהּ יָת קְלָנַהּ גַּלִּי וְהִיא תְגַלֵּי יָת סוֹאֲבַת דְּמָהָא וְיִשְׁתֵּיצוּן תַּרְוֵיהוֹן מִגּוֹ עַמְּהוֹן:",0,0],[20,19,"וְעֶרְיַת אֲחַת אִמָּךְ וַאֲחַת אָבוּךְ לָא תְגַלֵּי אֲרֵי יָת קָרִיבֵיהּ גַּלִּי חוֹבְהֶן יְקַבְּלוּן:",0,0],[20,20,"וּגְבַר דִּי יִשְׁכּוּב יָת אִתַּת אַח אֲבוּהִי עֶרְיַת אַח אֲבוּהִי גַּלִּי חוֹבְהֶן יְקַבְּלוּן בְּלָא וְלָד יְמוּתוּן:",0,0],[20,21,"וּגְבַר דִּי יִסַּב יָת אִתַּת אֲחוּהִי מְרָחָקָא הִיא עֶרְיְתָא דַאֲחוּהִי גַּלִּי בְּלָא וְלָד יְהוֹן:",0,0],[20,22,"וְתִטְּרוּן יָת כָּל קְיָמַי וְיָת כָּל דִּינַי וְתַעְבְּדוּן יָתְהוֹן וְלָא תְרוֹקֵן יָתְכוֹן אַרְעָא דִּי אֲנָא מַעֵיל יָתְכוֹן תַּמָּן לְמִתַּב בַּהּ:",0,0],[20,23,"וְלָא תְהָכוּן בְּנִימוֹסֵי עַמְמַיָּא דִּי אֲנָא מַגְלֵי מִן קֳדָמֵיכוֹן אֲרֵי יָת כָּל אִלֵּין עֲבָדוּ וְרָחִיק מֵימְרִי יָתְהוֹן:",0,0],[20,24,"וַאֲמָרִית לְכוֹן אַתּוּן תִּירְתוּן יָת אַרְעֲהוֹן וַאֲנָא אֶתְּנִנַּהּ לְכוֹן לְמֵירַת יָתַהּ אַרְעָא עָבְדָא חֲלָב וּדְבָשׁ אֲנָא יְיָ אֱלָהָכוֹן דִּי אַפְרֵשִׁית יָתְכוֹן מִן עַמְמַיָּא:",0,0],[20,25,"וְתַפְרְשׁוּן בֵּין בְּעִירָא דַכְיָא לִמְסָאָבָא וּבֵין עוֹפָא מְסָאָבָא לִדְכֵי וְלָא תְשַׁקְּצוּן יָת נַפְשָׁתֵיכוֹן בִּבְעִירָא וּבְעוֹפָא וּבְכֹל דִּי תַרְחֵשׁ אַרְעָא דִּי אַפְרֵשִׁית לְכוֹן לְסָאָבָא:",0,0],[20,26,"וּתְהוֹן קֳדָמַי קַדִּישִׁין אֲרֵי קַדִּישׁ אֲנָא יְיָ וְאַפְרֵשִׁית יָתְכוֹן מִן עַמְמַיָּא לְמֶהֱוֵי פָלְחִין קֳדָמָי:",0,0],[20,27,"וּגְבַר אוֹ אִתְּתָא אֲרֵי יְהֵי בְהוֹן בִּדִּין אוֹ דְּכוּר אִתְקְטָלָא יִתְקַטְּלוּן בְּאַבְנָא יִרְגְּמוּן יָתְהוֹן קְטָלָא חַיָּבִין:",0,0],[21,1,"וַאֲמַר יְיָ לְמשֶׁה אֱמַר לְכַהֲנַיָּא בְּנֵי אַהֲרֹן וְתֵימַר לְהוֹן עַל מִית לָא יִסְתָּאַב בְּעַמֵּיהּ:",0,0],[21,2,"אֶלָּהֵן לְקָרִיבֵיהּ דְּקָרִיב לֵיהּ לְאִמֵּיהּ וְלַאֲבוּהִי וְלִבְרֵיהּ וְלִבְרַתֵּיהּ וְלַאֲחוּהִי:",0,0],[21,3,"וְלַאֲחָתֵיהּ בְּתֻלְתָּא דְּקָרִיבָא לֵיהּ דִּי לָא הֲוַת לִגְבָר לַהּ יִסְתָּאָב:",0,0],[21,4,"לָא יִסְתָּאַב רַבָּא בְעַמֵּיהּ לְאַחֲלוּתֵיהּ:",0,0],[21,5,"לָא יִמְרְטוּן מְרַט בְּרֵישְׁהוֹן וּפָאתָא דְדִקְנְהוֹן לָא יְגַלְּחוּן וּבְבִשְׂרְהוֹן לָא יְחַבְּלוּן חִבּוּל:",0,0],[21,6,"קַדִּישִׁין יְהוֹן קֳדָם אֱלָהֲהוֹן וְלָא יְחַלּוּן שְׁמָא דֶּאֱלָהֲהוֹן אֲרֵי יָת קֻרְבְּנַיָּא דַיְיָ קֻרְבָּן אֱלָהֲהוֹן אִנּוּן מַקְרִיבִין וִיהוֹן קַדִּישִׁין:",0,0],[21,7,"אִתְּתָא מַטְעֲיָא וּמְחַלְּלָא לָא יִסְּבוּן וְאִתְּתָא דִּמְתָרְכָא מִבַּעְלַהּ לָא יִסְּבוּן אֲרֵי קַדִּישׁ הוּא קֳדָם אֱלָהֵיהּ:",0,0],[21,8,"וּתְקַדְּשִׁנֵּיהּ אֲרֵי יָת קֻרְבַּן אֱלָהָךְ הוּא מְקָרֵב קַדִּישׁ יְהֵי לָךְ אֲרֵי קַדִּישׁ אֲנָא יְיָ מְקַדִּשְׁכוֹן:",0,0],[21,9,"וּבַת גְּבַר כָּהֵן אֲרֵי תִתְחַל לְמִטְעֵי מִקְּדֻשַּׁת אֲבוּהָ הִיא מִתַּחֲלָא בְּנוּרָא תִּתּוֹקָד:",0,0],[21,10,"וְכַהֲנָא דְאִתְרַבָּא מֵאֲחוֹהִי דְּ יִתָּרִיק עַל רֵישֵׁיהּ מִשְׁחָא דִרְבוּתָא וְדִי קָרִיב יָת קֻרְבָּנֵיהּ לְמִלְבַּשׁ יָת לְבוּשַׁיָּא יָת רֵישֵׁיהּ לָא יְרַבֵּי פֵרוּעַ וּלְבוּשׁוֹהִי לָא יִבְזַע:",0,0],[21,11,"וְעַל כָּל נַפְשַׁת מֵתָא לָא יֵיעוֹל לַאֲבוּהִי וּלְאִמֵּיהּ לָא יִסְתָּאָב:",0,0],[21,12,"וּמִין מַקְדְּשָׁא לָא יִפּוֹק וְלָא יַחֵל יָת מַקְדְּשָׁא דֶאֱלָהֵיהּ אֲרֵי כְּלִיל מְשַׁח רְבוּתָא דֶאֱלָהֵיהּ עֲלוֹהִי אֲנָא יְיָ:",0,0],[21,13,"וְהוּא אִתְּתָא בִּבְתֻלְתָּהָא יִסָּב:",0,0],[21,14,"אַרְמְלָא וּמְתָרְכָא וְחַלִּילָא מַטְעֲיָא יָת אִלֵּין לָא יִסָּב אֱלָהֵן בְּתֻלְתָּא מֵעַמֵּיהּ יִסַּב אִתְּתָא:",0,0],[21,15,"וְלָא יַחֵל זַרְעֵיהּ בְּעַמֵּיהּ אֲרֵי אֲנָא יְיָ מְקַדְּשֵׁיהּ:",0,0],[21,16,"וּמַלִּיל יְיָ עִם משֶׁה לְמֵימָר:",0,0],[21,17,"מַלֵּל עִם אַהֲרֹן לְמֵימָר גְּבַר מִבְּנָיךְ לְדָרֵיהוֹן דִּי יְהֵי בֵיהּ מוּמָא לָא יִקְרַב לְקָרָבָא קֻרְבָּנָא קֳדָם אֱלָהֵיהּ:",0,0],[21,18,"אֲרֵי כָל גְּבַר דִּי בֵיהּ מוּמָא לָא יִקְרָב גְּבַר עַוִּיר אוֹ חֲגִיר אוֹ חָרִים אוֹ שְׂרִיעַ:",0,0],[21,19,"אוֹ גְבַר דִּי יְהֵי בֵיהּ תְּבַר רַגְלָא אוֹ תְּבַר יְדָא:",0,0],[21,20,"אוֹ גְבִין אוֹ דֻקָּא אוֹ חִלִּיז בְּעֵינֵיהּ אוֹ גַרְבָן אוֹ חֲזָזָן אוֹ מְרַס פַּחֲדִין:",0,0],[21,21,"כָּל גְּבַר דִּי בֵיהּ מוּמָא מִזַּרְעָא דְּאַהֲרֹן כַּהֲנָא לָא יִקְרַב לְקָרָבָא יָת קֻרְבָּנַיָּא דַיְיָ מוּמָא בֵיהּ יָת קֻרְבַּן אֱלָהֵיהּ לָא יִקְרַב לְקָרָבָא:",0,0],[21,22,"קֻרְבַּן אֱלָהֵיהּ מִקֹּדֶשׁ קוּדְשַׁיָּא וּמִן קוּדְשַׁיָּא יֵיכוּל:",0,0],[21,23,"בְּרַם לְפָרֻכְתָּא לָא יֵיעוֹל וּלְמַדְבְּחָא לָא יִקְרַב אֲרֵי מוּמָא בֵיהּ וְלָא יַחֵל יָת מַקְדְּשַׁי אֲרֵי אֲנָא יְיָ מְקַדִּשְׁהוֹן:",0,0],[21,24,"וּמַלִּיל משֶׁה עִם אַהֲרֹן וְעִם בְּנוֹהִי וְעִם כָּל בְּנֵי יִשְׂרָאֵל:",0,0],[22,1,"וּמַלִּיל יְיָ עִם משֶׁה לְמֵימָר:",0,0],[22,2,"מַלֵּיל עִם אַהֲרֹן וְעִם בְּנוֹהִי וְיִפָּרְשׁוּן מִקּוּדְשַׁיָּא דִבְנֵי יִשְׂרָאֵל וְלָא יְחַלּוּן יָת שְׁמָא דְקוּדְשִׁי דִּי אִנּוּן מְקַדְּשִׁין קֳדָמַי אֲנָא יְיָ:",0,0],[22,3,"אֱמַר לְהוֹן לְדָרֵיכוֹן כָּל גְּבַר דִּי יִקְרַב מִכָּל בְּנֵיכוֹן לְקוּדְשַׁיָּא דִּי יְקַדְּשׁוּן בְּנֵי יִשְׂרָאֵל קֳדָם יְיָ וְסֹאבְתֵיהּ עֲלוֹהִי וְיִשְׁתֵּיצֵי אֲנָשָׁא הַהִיא מִן קֳדָמַי אֲנָא יְיָ:",0,0],[22,4,"גְּבַר גְּבַר מִזַּרְעָא דְאַהֲרֹן וְהוּא סְגִיר אוֹ דָאִיב בְּקוּדְשַׁיָּא לָא יֵיכוּל עַד דִּי יִדְכֵּי וּדְיִקְרַב בְּכָל טְמֵא נַפְשָׁא אוֹ גְבַר דִּי תִפּוֹק מִנֵּיהּ שִׁכְבַת זַרְעָא:",0,0],[22,5,"אוֹ גְבַר דִּי יִקְרַב בְּכָל רִחֲשָׁא דִּי יִסְתָּאַב לֵיהּ אוֹ בַאֲנָשָׁא דִּי יִסְתָּאַב לֵיהּ לְכֹל סֹאבְתֵיהּ:",0,0],[22,6,"אֱנַשׁ דִּי יִקְרַב בֵּיהּ וִיהֵי מְסָאָב עַד רַמְשָׁא וְלָא יֵיכוּל מִן קוּדְשַׁיָּא אֱלָהֵן אַסְחֵי בִשְׂרֵיהּ בְּמַיָּא:",0,0],[22,7,"וּבְמֵעַל שִׁמְשָׁא וְיִדְכֵּי וּבָתַר כֵּן יֵיכוּל מִן קוּדְשַׁיָּא אֲרֵי לַחְמֵיהּ הוּא:",0,0],[22,8,"נְבִילָא וּתְבִירָא לָא יֵיכוּל לְאִסְתָּאָבָא בַהּ אֲנָא יְיָ:",0,0],[22,9,"וְיִטְּרוּן יָת מַטְּרַת מֵימְרִי וְלָא יְקַבְּלוּן עֲלוֹהִי חוֹבָא וִימוּתוּן בֵּיהּ אֲרֵי יְחַלֻּנֵּיהּ אֲנָא יְיָ מְקַדִּשְׁהוֹן:",0,0],[22,10,"וְכָל חִלּוֹנַי לָא יֵיכוּל קוּדְשָׁא תּוֹתָבָא דְכַהֲנָא וַאֲגִירָא לָא יֵיכוּל קוּדְשָׁא:",0,0],[22,11,"וְכָהֵן אֲרֵי יִקְנֵי נְפַשׁ קִנְיַן כַּסְפֵּיהּ הוּא יֵיכוּל בֵּיהּ וִילִיד בֵּיתֵיהּ אִנּוּן יֵיכְלוּן בְּלַחְמֵיהּ:",0,0],[22,12,"וּבַת כָּהֵן אֲרֵי תְהֵי לִגְבַר חִלּוֹנָי הִיא בְּאַפְרָשׁוּת קוּדְשַׁיָּא לָא תֵיכוּל:",0,0],[22,13,"וּבַת כָּהֵן אֲרֵי תְהֵי אַרְמְלָא וּמְתָרְכָא וּבַר לֵית לַהּ וּתְתוּב לְבֵית אֲבוּהָא כְּרַבְיוּתָהָא מִלַּחְמָא דַאֲבוּהָא תֵּיכוּל וְכָל חִלּוֹנַי לָא יֵיכוּל בֵּיהּ:",0,0],[22,14,"וּגְבַר אֲרֵי יֵיכוּל קוּדְשָׁא בְּשָׁלוּ וְיוֹסֵף חוּמְשֵׁיהּ עֲלוֹהִי וִיתֵּן לְכַהֲנָא יָת קוּדְשָׁא:",0,0],[22,15,"וְלָא יְחַלּוּן יָת קוּדְשַׁיָּא דִּבְנֵי יִשְׂרָאֵל יָת דִּי יַפְרְשׁוּן קֳדָם יְיָ:",0,0],[22,16,"וִיקַבְּלוּן עֲלֵיהוֹן עֲוָיָן וְחוֹבִין בְּמֵיכָלְהוֹן בְּסוֹאַבָא יָת קוּדְשֵׁיהוֹן אֲרֵי אֲנָא יְיָ מְקַדִּשְׁהוֹן:",0,0],[22,17,"וּמַלִּיל יְיָ עִם משֶׁה לְמֵימָר:",0,0],[22,18,"מַלֵּיל עִם אַהֲרֹן וְעִם בְּנוֹהִי וְעִם כָּל בְּנֵי יִשְׂרָאֵל וְתֵימַר לְהוֹן גְּבַר גְּבַר מִבֵּית יִשָׂרָאֵל וּמִן גִּיּוֹרָא בְּיִשְׂרָאֵל דִּי יְקָרֵב קֻרְבָּנֵיהּ לְכָל נִדְרֵיהוֹן וּלְכָל נִדְבַתְהוֹן דִּי יְקָרְבוּן קֳדָם יְיָ לַעֲלָתָא:",0,0],[22,19,"לְרַעֲוָא לְכוֹן שְׁלִים דְּכוּרָא בְּתוֹרֵי בְּאִמְרַיָּא וּבְעִזַּיָּא:",0,0],[22,20,"כֹּל דִּי בֵיהּ מוּמָא לָא תְקָרְבוּן אֲרֵי לָא לְרַעֲוָא יְהֵי לְכוֹן:",0,0],[22,21,"וּגְבַר אֲרֵי יְקָרֵב נִכְסַת קוּדְשַׁיָּא קֳדָם יְיָ לְפָרָשָׁא נִדְרָא אוֹ לִנְדַבְתָּא בְּתוֹרֵי אוֹ בְעָנָא שְׁלִים יְהֵי לְרַעֲוָא כָּל מוּמָא לָא יְהֵי בֵיהּ:",0,0],[22,22,"עַוִּיר אוֹ תְבִיר אוֹ פְסִיק אוֹ יַבְּלָן אוֹ גַרְבָן אוֹ חֲזָזָן לָא תְקָרְבוּן אִלֵּין קֳדָם יְיָ וְקֻרְבָּנָא לָא תִתְּנוּן מִנְּהוֹן עַל מַדְבְּחָא קֳדָם יְיָ:",0,0],[22,23,"וְתוֹר וְאִמַּר יַתִּיר וְחַסִּיר נְדַבְתָּא תַּעְבֵּד יָתֵיהּ וּלְנִדְרָא לָא יְהֵי לְרַעֲוָא:",0,0],[22,24,"וְדִי מְרִיס וְדִי רְסִיס וְדִי שְׁלִיף וְדִי גְזִיר לָא תְקָרְבוּן קֳדָם יְיָ וּבְאַרְעֲכוֹן לָא תַעְבְּדוּן:",0,0],[22,25,"וּמִן בַּר עַמְמִין לָא תְקָרְבוּן יָת קֻרְבַּן אֱלָהָכוֹן מִכָּל אִלֵּין אֲרֵי חִבּוּלְהוֹן בְּהוֹן מוּמָא בְהוֹן לָא לְרַעֲוָא יְהוֹן לְכוֹן:",0,0],[22,26,"וּמַלִּיל יְיָ עִם משֶׁה לְמֵימָר:",0,0],[22,27,"תּוֹר אוֹ אִמָּר אוֹ עִזָּא אֲרֵי יִתְיְלִיד וִיהֵי שִׁבְעָא יוֹמִין בָּתַר אִמֵּיהּ וּמִיּוֹמָא תְמִינָאָה וּלְהַלָּא יִתִּרְעֵי לְקָרָבָא קֻרְבָּנָא קֳדָם יְיָ:",0,0],[22,28,"וְתוֹרְתָּא אוֹ שֵׂיתָא לַהּ וְלִבְרַהּ לָא תִכְּסוּן בְּיוֹמָא חָד:",0,0],[22,29,"וַאֲרֵי תִכְּסוּן נִכְסַת תּוֹדְתָא קֳדָם יְיָ לְרַעֲוָא לְכוֹן תִּכְּסֻנֵּיהּ:",0,0],[22,30,"בְּיוֹמָא הַהוּא יִתְאֲכֵל לָא תַשְׁאֲרוּן מִנֵּיהּ עַד צַפְרָא אֲנָא יְיָ:",0,0],[22,31,"וְתִטְּרוּן פִּקּוֹדַי וְתַעְבְּדוּן יָתְהוֹן אֲנָא יְיָ:",0,0],[22,32,"וְלָא תְחַלְּלוּן יָת שְׁמָא דְקוּדְשַׁי וְאִתְקַדַּשׁ בְּגוֹ בְּנֵי יִשְׂרָאֵל אֲנָא יְיָ מְקַדִּשְׁכוֹן:",0,0],[22,33,"דְּאַפִּיק יָתְכוֹן מֵאַרְעָא דְמִצְרַיִם לְמֶהֱוֵי לְכוֹן לֵאלָהָא אֲנָא יְיָ:",0,0],[23,1,"וּמַלִּיל יְיָ עִם משֶׁה לְמֵימָר:",0,0],[23,2,"מַלֵּיל עִם בְּנֵי יִשְׁרָאֵל וְתֵימַר לְהוֹן מוֹעֲדַיָּא דַיְיָ דִּי תְעָרְעוּן יָתְהוֹן מְעָרְעֵי קַדִּישׁ אִלֵּין אִנּוּן מוֹעֲדָי:",0,0],[23,3,"שִׁתָּא יוֹמִין תִּתְעֲבֵד עִבִידָא וּבְיוֹמָא שְׁבִיעָאָה שְׁבַת שְׁבָתָא מְעָרַע קַדִּישׁ כָּל עִבִידָא לָא תַעְבְּדוּן שַׁבְּתָא הִיא קֳדָם יְיָ בְּכֹל מוֹתְבָנֵיכוֹן:",0,0],[23,4,"אִלֵּין מוֹעֲדַיָּא דַיְיָ מְעָרְעֵי קַדִּישׁ דִּי תְעָרְעוּן יָתְהוֹן בְּזִמְנֵיהוֹן:",0,0],[23,5,"בְּיַרְחָא קַדְמָאָה בְּאַרְבְּעַת עַשְׂרָא לְיַרְחָא בֵּין שִׁמְשַׁיָּא פִּסְחָא קֳדָם יְיָ:",0,0],[23,6,"וּבְחַמְשַׁת עַשְׂרָא יוֹמָא לְיַרְחָא הָדֵין חַגָּא דְּפַטִּירַיָּא קֳדָם יְיָ שִׁבְעָא יוֹמִין פַּטִּיר תֵּיכְלוּן:",0,0],[23,7,"בְּיוֹמָא קַדְמָאָה מְעָרַע קַדִּישׁ יִהֵי לְכוֹן כָּל עִבִידַת פָּלְחַן לָא תַעְבְּדוּן:",0,0],[23,8,"וּתְקָרְבוּן קֻרְבָּנָא קֳדָם יְיָ שִׁבְעָא יוֹמִין בְּיוֹמָא שְׁבִיעָאָה מְעָרַע קַדִּישׁ כָּל עִבִידַת פָּלְחָן לָא תַעְבְּדוּן:",0,0],[23,9,"וּמַלִּיל יְיָ עִם משֶׁה לְמֵימָר:",0,0],[23,10,"מַלֵּיל עִם בְּנֵי יִשְׂרָאֵל וְתֵימַר לְהוֹן אֲרֵי תֵעֲלוּן לְאַרְעָא דִּי אֲנָא יָהֵב לְכוֹן וְתַחְצְדוּן יָת חֲצָדַהּ וְתַיְתוּן יָת עוּמְרָא רֵישׁ חֲצָדְכוֹן לְוָת כַּהֲנָא:",0,0],[23,11,"וִירִים יָת עוּמְרָא קֳדָם יְיָ לְרַעֲוָא לְכוֹן מִבָּתַר יוֹמָא טָבָא יְרִימִנֵּיהּ כַּהֲנָא:",0,0],[23,12,"וְתַעְבְּדוּן בְּיוֹמָא דַאֲרָמוּתְכוֹן יָת עוּמְרָא אִמַּר שְׁלִים בַּר שַׁתֵּיהּ לַעֲלָתָא קֳדָם יְיָ:",0,0],[23,13,"וּמִנְחָתֵיהּ תְּרֵין עֶשְׁרוֹנִין סֻלְתָּא דְּפִילָא בִמְשַׁח קֻרְבָּנָא קֳדָם יְיָ לְאִתְקַבָּלָא בְרַעֲוָא וְנִסְכֵּיהּ חַמְרָא רַבְעוּת הִינָא:",0,0],[23,14,"וּלְחֵם וּקְלִי וּפֵרוּכָן לָא תֵיכְלוּן עַד כְּרַן יוֹמָא הָדֵין עַד אַיְתוֹאֵיכוֹן יָת קֻרְבָּן אֱלָהָכוֹן קְיַם עָלָם לְדָרֵיכוֹן בְּכֹל מוֹתְבָנֵיכוֹן:",0,0],[23,15,"וְתִמְנוּן לְכוֹן מִבָּתַר יוֹמָא טָבָא מִיּוֹם אַיְתוֹאֵיכוֹן יָת עוּמְרָא דַאֲרָמוּתָא שִׁבְעָא שָׁבוּעִין שַׁלְמִין יְהֶוְיָן:",0,0],[23,16,"עַד מִבָּתַר שְׁבוּעֲתָא שְׁבִיעֵתָא תִּמְנוּן חַמְשִׁין יוֹמִין וּתְקָרְבוּן מִנְחָתָא חֲדַתָּא קֳדָם יְיָ:",0,0],[23,17,"מִמּוֹתְבָנֵיכוֹן תַּיְתוּן לְחֵם אֲרָמוּתָא תַּרְתֵּין (גְּרִיצַן) תְּרֵין עֶשְׁרוֹנִין סֻלְתָּא יְהֶוְיָן חֲמִיעַ יִתְאַפְיָן בִּכּוּרִין קֳדָם יְיָ:",0,0],[23,18,"וּתְקָרְבוּן עַל לַחְמָא שִׁבְעָא אִמְּרִין שַׁלְמִין בְּנֵי שְׁנָא וְתוֹר בַּר תּוֹרֵי חַד וְדִכְרִין תְּרֵין יְהוֹן עֲלָתָא קֳדָם יְיָ וּמִנְחָתְהוֹן וְנִסְכֵּיהוֹן קֻרְבַּן דְּמִתְקַבֵּל בְּרַעֲוָא קֳדָם יְיָ:",0,0],[23,19,"וְתַעְבְּדוּן צְפִיר בַּר עִזֵּי חַד לְחַטָּאתָא וּתְרֵין אִמְּרִין בְּנֵי שְׁנָא לְנִכְסַת קוּדְשַׁיָּא:",0,0],[23,20,"וִירִים כַּהֲנָא יָתְהוֹן עַל לְחֵם בִּכּוּרַיָּא אֲרָמוּתָא קֳדָם יְיָ עַל תְּרֵין אִמְּרִין קוּדְשָׁא יְהוֹן קֳדָם יְיָ לְכַהֲנָא:",0,0],[23,21,"וּתְעָרְעוּן בִּכְרַן יוֹמָא הָדֵין מְעָרַע קַדִּישׁ יְהֵי לְכוֹן כָּל עִבִידַת פָּלְחָן לָא תַעְבְּדוּן קְיַם עָלָם בְּכָל מוֹתְבָנֵיכוֹן לְדָרֵיכוֹן:",0,0],[23,22,"וּבְמֶחֱצָדְכוֹן יָת חֲצָדָא דְאַרְעֲכוֹן לָא תְשֵׁיצֵי פָּאתָא דְחַקְלָךְ בְּמֶחֱצָדָךְ וּלְקָטָא דַחֲצָדָךְ לָא תְלַקֵּט לְעַנְיֵי וּלְגִיּוֹרֵי תִּשְׁבּוֹק יָתְהוֹן אֲנָא יְיָ אֱלָהָכוֹן:",0,0],[23,23,"וּמַלִּיל יְיָ עִם משֶׁה לְמֵימָר:",0,0],[23,24,"מַלֵּיל עִם בְּנֵי יִשְׂרָאֵל לְמֵימָר בְּיַרְחָא שְׁבִיעָאָה בְּחַד לְיַרְחָא יְהֵי לְכוֹן נְיָחָא דּוּכְרַן יַבָּבָא מְעָרַע קַדִּישׁ:",0,0],[23,25,"כָּל עִבִידַת פָּלְחָנָא לָא תַעְבְּדוּן וּתְקָרְבוּן קֻרְבָּנָא קֳדָם יְיָ:",0,0],[23,26,"וּמַלִּיל יְיָ עִם משֶׁה לְמֵימָר:",0,0],[23,27,"בְּרַם בְּעַשְׂרָא לְיַרְחָא שְׁבִיעָאָה הָדֵין יוֹמָא דְכִפּוּרַיָּא הוּא מְעָרַע קַדִּישׁ יְהֵי לְכוֹן וּתְעַנּוּן יָת נַפְשָׁתֵיכוֹן וּתְקָרְבוּן קֻרְבָּנָא קֳדָם יְיָ:",0,0],[23,28,"וְכָל עִבִידָא לָא תַעְבְּדוּן בִּכְרַן יוֹמָא הָדֵין אֲרֵי יוֹמָא דְכִפּוּרַיָּא הוּא לְכַפָּרָא עֲלֵיכוֹן קֳדָם יְיָ אֱלָהָכוֹן:",0,0],[23,29,"אֲרֵי כָל אֲנָשָׁא דִּי לָא מִתְעַנֵּי בִּכְרַן יוֹמָא הָדֵין וְיִשְׁתֵּיצֵי מֵעַמָּהָא:",0,0],[23,30,"וְכָל אֱנַשׁ דִּי תַעְבֵּד כָּל עִבִידָא בִּכְרַן יוֹמָא הָדֵין וְאוֹבֵד יָת אֲנָשָׁא הַהִיא מִגּוֹ עַמַּהּ:",0,0],[23,31,"כָּל עִבִידָא לָא תַעְבְּדוּן קְיַם עָלָם לְדָרֵיכוֹן בְּכֹל מוֹתְבָנֵיכוֹן:",0,0],[23,32,"שְׁבַת שְׁבָתָא הוּא לְכוֹן וּתְעַנּוּן יָת נַפְשָׁתֵיכוֹן בְּתִישְׁעָא לְיַרְחָא בְּרַמְשָׁא מֵרַמְשָׁא עַד רַמְשָׁא תְּנוּחוּן נְיַחֲכוֹן:",0,0],[23,33,"וּמַלִּיל יְיָ עִם משֶׁה לְמֵימָר:",0,0],[23,34,"מַלֵּיל עִם בְּנֵי יִשְׂרָאֵל לְמֵימָר בְּחַמְשָׁא עַשְׁרָא יוֹמָא לְיַרְחָא שְׁבִיעָאָה הָדֵין חַגָּא דִמְטַלַּיָּא שִׁבְעַת יוֹמִין קֳדָם יְיָ:",0,0],[23,35,"בְּיוֹמָא קַדְמָאָה מְעָרַע קַדִּישׁ כָּל עִבִידַת פָּלְחָן לָא תַעְבְּדוּן:",0,0],[23,36,"שִׁבְעָא יוֹמִין תְּקָרְבוּן קֻרְבָּנָא קֳדָם יְיָ בְּיוֹמָא תְמִינָאָה מְעָרַע קַדִּישׁ יְהֵי לְכוֹן וּתְקָרְבוּן קֻרְבָּנָא קֳדָם יְיָ כְּנֵשׁ תְּהוֹן כָּל עִבִידַת פָּלְחָן לָא תַעְבְּדוּן:",0,0],[23,37,"אִלֵּין מוֹעֲדַיָּא דַיְיָ דִּי תְעָרְעוּן יָתְהוֹן מְעָרְעֵי קַדִּישׁ לְקָרָבָא קֻרְבָּנָא קֳדָם יְיָ עֲלָתָא וּמִנְחָתָא נִכְסַת קוּדְשִׁין וְנִסּוּכִין פִּתְגַם יוֹם בְּיוֹמֵיהּ:",0,0],[23,38,"בַּר שַׁבַּיָּא דַיְיָ וּבַר מַתְּנָתֵיכוֹן וּבַר כָּל נִדְרֵיכוֹן וּבַר כָּל נִדְבָתֵיכוֹן דִּי תִתְּנוּן קֳדָם יְיָ:",0,0],[23,39,"בְּרַם בְּחַמְשָׁא עֲשַׁר יוֹמָא לְיַרְחָא שְׁבִיעָאָה בְּמִכְנְשֵׁיכוֹן יָת עֲלַלַת אַרְעָא תְּחַגּוּן יָת חַגָּא קֳדָם יְיָ שִׁבְעָא יוֹמִין בְּיוֹמָא קַדְמָאָה נְיָחָא וּבְיוֹמָא תְמִינָאָה נְיָחָא:",0,0],[23,40,"וְתִסְּבוּן לְכוֹן בְּיוֹמָא קַדְמָאָה פֵּרֵי אִילָנָא אֶתְרוֹגִין וְלֻלַּבִּין וַהֲדַסִּין וְעַרְבִין דִּנְחָל וְתֶחֱדוּן קֳדָם יְיָ אֱלָהָכוֹן שַׁבְעַת יוֹמִין:",0,0],[23,41,"וּתְחַגּוּן יָתֵיהּ חַגָּא קֳדָם יְיָ שַׁבְעַת יוֹמִין בְּשַׁתָּא קְיַם עָלָם לְדָרֵיכוֹן בְּיַרְחָא שְׁבִיעָאָה תְּחַגּוּן יָתֵיהּ:",0,0],[23,42,"בִּמְטַלַּיָּא תֵיתְבוּן שַׁבְעַת יוֹמִין כָּל יַצִּיבָא בְּיִשְׂרָאֵל יֵתְבוּן בִּמְטַלַּיָּא:",0,0],[23,43,"בְּדִיל דִּיִדְּעוּן דָּרֵיכוֹן אֲרֵי בִמְטַלָּיוּת עֲנָנֵי אוֹתֵבִית יָת בְּנֵי יִשְׂרָאֵל בְּאַפָּקוּתִי יָתְהוֹן מֵאַרְעָא דְמִצְרָיִם אֲנָא יְיָ אֱלָהָכוֹן:",0,0],[23,44,"וּמַלִּיל משֶׁה יָת סְדַר מוֹעֲדַיָּא דַיְיָ וְאַלֵּפִנּוּן לִבְנֵי יִשְׂרָאֵל:",0,0],[24,1,"וּמַלִּיל יְיָ עִם משֶׁה לְמֵימָר:",0,0],[24,2,"פַּקֵּד יָת בְּנֵי יִשְׂרָאֵל וְיִסְּבוּן לָךְ מְשַׁח זֵיתָא דַכְיָא כָּתִישָׁא לְאַנְהָרָא לְאַדְלָקָא בוֹצִינַיָּא תְּדִירָא:",0,0],[24,3,"מִבָּרָא לְפָרֻכְתָּא דְסַהֲדוּתָא בְּמַשְׁכַּן זִמְנָא יַסְדַּר יָתֵיהּ אֲהֲרֹן מֵרַמְשָׁא עַד צַפְרָא קֳדָם יְיָ תְּדִירָא קְיָם עָלָם לְדָרֵיכוֹן:",0,0],[24,4,"עַל מְנַרְתָּא דָכִיתָא יַסְדַּר יָת בּוֹצִינַיָּא קֳדָם יְיָ תְּדִירָא:",0,0],[24,5,"וְתִסַּב סֻלְתָּא וְתֵיפֵי יָתַהּ תַּרְתָּא עַשְׂרֵי גְּרִיצָן תְּרֵין עֶשְׂרוֹנִין תְּהֵי גְּרִצְתָּא חֲדָא:",0,0],[24,6,"וּתְשַׁוִּי יָתְהוֹן תַּרְתֵּין סִדְרִין שִׁית סִדְרָא עַל פָּתוֹרָא דַכְיָא קֳדָם יְיָ:",0,0],[24,7,"וְתִתֵּן עַל סִדְרָא לְבֻנְתָּא דָכִיתָא וּתְהֵי לִלְחֵם לְאִדְכַּרְתָּא קֻרְבָּנָא קֳדָם יְיָ:",0,0],[24,8,"בְּיוֹמָא דְשַׁבְּתָא בְּיוֹמָא דְשַׁבְּתָא יַסְדְּרִנֵּיהּ קֳדָם יְיָ תְּדִירָא מִן קֳדָם בְּנֵי יִשְׂרָאֵל קְיַם עָלָם:",0,0],[24,9,"וּתְהֵי לְאַהֲרֹן וְלִבְנוֹהִי וְיֵכְלֻנֵּיהּ בַּאֲתַר קַדִּישׁ אֲרֵי קֹדֶשׁ קוּדְשִׁין הוּא לֵיהּ מִקֻּרְבָּנַיָּא דַיְיָ קְיַם עָלָם:",0,0],[24,10,"וּנְפַק בַּר אִתְּתָא בַת יִשְׂרָאֵל וְהוּא בַּר גְּבַר מִצְרָאָה בְּגוֹ בְּנֵי יִשְׂרָאֵל וּנְצוֹ בְּמַשְׁרִיתָא בַּר אִתְּתָא בַת יִשְׂרָאֵל וְגַבְרָא בַּר יִשְׂרָאֵל:",0,0],[24,11,"וּפָרֵשׁ בַּר אִתְּתָא בַת יִשְׂרָאֵל יָת שְׁמָא וְאַרְגֵּז וְאַיְתִיאוּ יָתֵיהּ לְוָת משֶׁה וְשׁוּם אִמֵּיהּ שְׁלֹּמִית בַּת דִּבְרִי לְשִׁבְטָא דְדָן:",0,0],[24,12,"וְאַסְּרוֹהִי בְּבֵית מַטְּרָא עַד דְּיִתְפָּרַשׁ לְהוֹן עַל גְּזֵרַת מֵימְרָא דַיְיָ:",0,0],[24,13,"וּמַלִּיל יְיָ עִם משֶׁה לְמֵימָר:",0,0],[24,14,"אַפֵּק יָת דְּאַרְגֵּז לְמִבָּרָא לְמַשְׁרִיתָא וְיִסְמְכוּן כָּל דִּי שְׁמָעוּ יָת יְדֵיהוֹן עַל רֵישֵׁיהּ וְיִרְגְּמוּן יָתֵיהּ כָּל כְּנִשְׁתָּא:",0,0],[24,15,"וְעִם בְּנֵי יִשְׂרָאֵל תְּמַלֵּל לְמֵימָר גְּבַר גְּבַר דִּי יַרְגֵּז קֳדָם אֱלָהֵיהּ וִיקַבֵּל חוֹבֵיהּ:",0,0],[24,16,"וְדִי פָרֵשׁ שְׁמָא דַיְיָ אִתְקְטָלָא יִתְקְטֵל מִרְגַּם יִרְגְּמוּן בֵּיהּ כָּל כְּנִשְׁתָּא כְּגִיּוֹרָא כְּיַצִּיבָא בְּפָרָשׁוּתֵיהּ שְׁמָא יִתְקְטֵל:",0,0],[24,17,"וּגְבַר אֲרֵי יִקְטוֹל כָּל נַפְשָׁא דַאֲנָשָׁא אִתְקְטָלָא יִתְקְטֵל:",0,0],[24,18,"וּדְיִקְטוֹל נְפַשׁ בְּעִירָא יְשַׁלְּמִנַּהּ נַפְשָׁא חֲלַף נַפְשָׁא:",0,0],[24,19,"וּגְבַר אֲרֵי יִתֵּן מוּמָא בְּחַבְרֵיהּ כְּמָא דִי עֲבַד כֵּן יִתְעֲבֶד לֵיהּ:",0,0],[24,20,"תַּבְרָא חֳלַף תַּבְרָא עֵינָא חֳלַף עֵינָא שִׁנָּא חֳלַף שִׁנָּא כְּמָא דִי יִתֵּן מוּמָא בַּאֲנָשָׁא כֵּן יִתְיְהֶב בֵּיהּ:",0,0],[24,21,"וּדְיִקְטוֹל בְּעִירָא יְשַׁלְּמִנַּהּ וּדְיִקְטוֹל אֲנָשָׁא יִתְקְטֵל:",0,0],[24,22,"דִּינָא חֲדָא יְהֵי לְכוֹן כְּגִיּוֹרָא כְיַצִּיבָא יְהֵי אֲרֵי אֲנָא יְיָ אֱלָהָכוֹן:",0,0],[24,23,"וּמַלִּיל משֶׁה עִם בְּנֵי יִשְׂרָאֵל וְאַפִּיקוּ יָת דְּאַרְגֵּז לְמִבָּרָא לְמַשְׁרִיתָא וּרְגָמוּ יָתֵיהּ אַבְנָא וּבְנֵי יִשְׂרָאֵל עֲבָדוּ כְּמָא דִי פַקֵּיד יְיָ יָת משֶׁה:",0,0],[25,1,"וּמַלִּיל יְיָ עִם משֶׁה בְּטוּרָא דְסִינַי לְמֵימָר:",0,0],[25,2,"מַלֵּיל עִם בְּנֵי יִשְׂרָאֵל וְתֵימַר לְהוֹן אֲרֵי תֵעֲלוּן לְאַרְעָא דִּי אֲנָא יָהֵב לְכוֹן וְתַשְׁמֵט אַרְעָא שְׁמִטְּתָא קֳדָם יְיָ:",0,0],[25,3,"שִׁית שְׁנִין תִּזְרַע חַקְלָךְ וְשִׁית שְׁנִין תִּכְסַח כַּרְמָךְ וְתִכְנוֹשׁ יָת עֲלַלְתַּהּ:",0,0],[25,4,"וּבְשַׁתָּא שְׁבִיעֲתָא נְיַח שְׁמִטְּתָא יְהֵי לְאַרְעָא דְּתַשְׁמֵט קֳדָם יְיָ חַקְלָךְ לָא תִזְרַע וְכַרְמָךְ לָא תִכְסָח:",0,0],[25,5,"יָת כַּתֵּי דַחֲצָדָךְ לָא תֶחֱצַד וְיָת עִנְּבֵי שִׁבְקָךְ לָא תִקְטוֹף שְׁנַת שְׁמִטְּתָא יְהֵי לְאַרְעָא:",0,0],[25,6,"וּתְהֵי שְׁמִטַּת אַרְעָא לְכוֹן לְמֵיכַל לָךְ וּלְעַבְדָּךְ וּלְאַמְתָךְ וְלַאֲגִירָךְ וּלְתוֹתָבָךְ דְּדָיְרִין עִמָּךְ:",0,0],[25,7,"וְלִבְעִירָךְ וּלְחַיְתָא דִּי בְאַרְעָךְ תְּהֵי כָל עֲלַלְתַּהּ לְמֵיכָל:",0,0],[25,8,"וְתִמְנֵי לָךְ שְׁבַע שְׁמִטִּין דִּשְׁנִין שְׁבַע שְׁנִין שְׁבַע זִמְנִין וִיהוֹן לָךְ יוֹמֵי שְׁבַע שְׁמִטִּין דִּשְׁנִין אַרְבְּעִין וְתֵשַׁע שְׁנִין:",0,0],[25,9,"וְתַעֲבַר שׁוֹפַר יַבָּבָא בְּיַרְחָא שְׁבִיעָאָה בְּעַשְׂרָא לְיַרְחָא בְּיוֹמָא דְכִפּוּרַיָּא תַּעַבְּרוּן שׁוֹפָרָא בְּכָל אַרְעֲכוֹן:",0,0],[25,10,"וּתְקַדְּשׁוּן יָת שְׁנַת חַמְשִׁין שְׁנִין וְתַקְרוּן חֵרוּתָא בְּאַרְעָא לְכָל יָתְבָהָא יוֹבֵלָא הִיא תְּהֵי לְכוֹן וּתְתוּבוּן גְּבַר לְאַחֲסַנְתֵּיהּ וּגְבַר לְזַרְעִיתֵיהּ תְּתוּבוּן:",0,0],[25,11,"יוֹבֵלָא הִיא שְׁנַת חַמְשִׁין שְׁנִין תְּהֵי לְכוֹן לָא תִזְרְעוּן וְלָא תַחְצְדוּן יָת כַּתָּהָא וְלָא תִקְטְפוּן יָת שִׁבְקָהָא:",0,0],[25,12,"אֲרֵי יוֹבֵלָא הִיא קוּדְשָׁא תְהֵי לְכוֹן מִן חַקְלָא תֵּיכְלוּן יָת עֲלַלְתַּהּ:",0,0],[25,13,"בְּשַׁתָּא דְיוֹבֵלָא הָדָא תְּתוּבוּן גְּבַר לְאַחֲסַנְתֵּיהּ:",0,0],[25,14,"וַאֲרֵי תְזַבֵּן זְבִינִין לְחַבְרָךְ אוֹ תִזְבֵּן מִידָא דְחַבְרָךְ לָא תוֹנוּן גְּבַר יָת אֲחוֹהִי:",0,0],[25,15,"בְּמִנְיַן שְׁנַיָּא בָּתַר יוֹבֵלָא תִּזְבֵּן מִן חַבְרָךְ בְּמִנְיַן שְׁנֵי עֲלַלְתָּא יְזַבֶּן לָךְ:",0,0],[25,16,"לְפוּם סְגִיאוּת שְׁנַיָּא תַּסְגֵּי זְבִינוֹהִי וּלְפוּם זְעֵרוּת שְׁנַיָּא תַּזְעֵר זְבִינוֹהִי אֲרֵי מִנְיַן עֲלַלְתָּא הוּא מְזַבֵּן לָךְ:",0,0],[25,17,"וְלָא תוֹנוּן גְּבַר יָת חַבְרֵיהּ וְתִדְחַל מֵאֱלָהָךְ אֲרֵי אֲנָא יְיָ אֱלָהָכוֹן:",0,0],[25,18,"וְתַעְבְּדוּן יָת קְיָמַי וְיָת דִּינַי תִּטְּרוּן וְתַעְבְּדוּן יָתְהוֹן וְתֵיתְבוּן עַל אַרְעָא לְרָחְצָן:",0,0],[25,19,"וְתִתֵּן אַרְעָא אִבַּהּ וְתֵיכְלוּן לְמִשְׂבָּע וְתֵיתְבוּן לְרָחֲצָן עֲלַהּ:",0,0],[25,20,"וַאֲרֵי תֵימְרוּן מָא נֵיכוּל בְּשַׁתָּא שְׁבִיעֵתָא הָא לָא נִזְרָע וְלָא נִכְנוֹשׁ יָת עֲלַלְתָּנָא:",0,0],[25,21,"וֶאֱפַקֵּד יָת בִּרְכָתִי לְכוֹן בְּשַׁתָּא שְׁתִיתֵתָא וְתַעְבֵּד יָת עֲלַלְתָּא לִתְלַת שְׁנִין:",0,0],[25,22,"וְתִזְרְעוּן יָת שַׁתָּא תְמִינֵתָא וְתֵיכְלוּן מִן עֲלַלְתָּא עַתִּיקָא עַד שַׁתָּא תְשִׁיעֵתָא עַד מֵעַל עֲלַלְתַּהּ תֵּיכְלוּן עַתִּיקָא:",0,0],[25,23,"וְאַרְעָא לָא תִזְדַּבַּן לַחֲלוּטִין אֲרֵי דִילִי אַרְעָא אֲרֵי דַיָּרִין וְתוֹתָבִין אַתּוּן קֳדָמַי:",0,0],[25,24,"וּבְכֹל אַרְעָא אַחֲסַנְתְּכוֹן פֻּרְקָנָא תִּתְּנוּן לְאַרְעָא:",0,0],[25,25,"אֲרֵי יְתְמַסְכַּן אָחוּךְ וִיזַבֵּן מֵאַחֲסַנְתֵּהּ וְיֵיתֵי פָרִיקֵיהּ דְּקָרִיב לֵיהּ וְיִפְרוֹק יָת זְבִינֵי אֲחוּהִי:",0,0],[25,26,"וּגְבַר אֲרֵי לָא יְהֵי לֵהּ פָּרִיק וְתַדְבֵּק יְדֵהּ וְיַשְׁכַּח כְּמִסַּת פֻּרְקָנֵהּ:",0,0],[25,27,"וִיחַשֵּׁב יָת שְׁנֵי זְבִינוֹהִי וְיָתֵב יָת מוֹתָרָא לִגְבַר דִּי זַבֶּן לֵיהּ וִיתוּב לְאַחֲסַנְתֵּהּ:",0,0],[25,28,"וְאִם לָא תַשְׁכַּח יְדֵהּ כְּמִסַּת אֲתֵב לֵיהּ וִיהֵי זְבִינוֹהִי בִּידָא דִּזְבַן יָתֵיהּ עַד שַׁתָּא דְיוֹבֵלָא וְיִפּוֹק בְּיוֹבֵלָא וִיתוּב לְאַחֲסַנְתֵּיהּ:",0,0],[25,29,"וּגְבַר אֲרֵי יְזַבֵּן בֵּית מוֹתַב קַרְתָּא מַקְּפָא שׁוּר וּתְהֵי פֻרְקָנֵיהּ עַד מִשְׁלַם שַׁתָּא דִזְבִינוֹהִי עִדָּן בְּעִדָּן תְּהֵי פֻרְקָנֵיהּ:",0,0],[25,30,"וְאִם לָא יִתְפָּרַק עַד מִשְׁלַם לֵיהּ שַׁתָּא שְׁלֶמְתָּא וִיקוּם בֵּיתָא דִי בְקַרְתָּא דִּי לֵיהּ שׁוּרָא לַחֲלוּטִין לְדִי זְבַן יָתֵיהּ לְדָרוֹהִי לָא יִפּוֹק בְּיוֹבֵלָא:",0,0],[25,31,"וּבָתֵּי פַצְחַיָּא דִּי לֵית לְהוֹן שׁוּר מַקַּף סְחוֹר סְחוֹר עַל חֲקַל אַרְעָא יִתְחַשָּׁב פֻּרְקָנָא תְּהֵי לֵיהּ וּבְיוֹבֵלָא יִפּוֹק:",0,0],[25,32,"וְקִרְוֵי לֵיוָאֵי בָּתֵּי קִרְוֵי אַחֲסַנְתְּהוֹן פֻּרְקַן עָלָם תְּהֵי לְלֵיוָאֵי:",0,0],[25,33,"וְדִי יִפְרוֹק מִן לֵיוָאֵי וְיִפּוֹק זְבִין בֵּיתָא וְקַרְתָּא אַחֲסַנְתֵּיהּ בְּיוֹבֵלָא אֲרֵי בָתֵּי קִרְוֵי לֵיוָאֵי הִיא אַחֲסַנְתְּהוֹן בְּגוֹ בְּנֵי יִשְׂרָאֵל:",0,0],[25,34,"וַחֲקַל רְוַח קִרְוֵיהוֹן לָא יִזְדַּבָּן אֲרֵי אַחֲסָנַת עָלָם הוּא לְהוֹן:",0,0],[25,35,"וַאֲרֵי יִתְמַסְכַּן אָחוּךְ וּתְמוּט יְדֵיהּ עִמָּךְ וְתַתְקֵף בֵּיהּ דַּיַּר וְתוֹתָב וִיחֵי עִמָּךְ:",0,0],[25,36,"לָא תִסַּב מִנֵּיהּ חִבּוּלְיָא וְרִבִּיתָא וְתִדְחַל מֵאֱלָהָךְ וִיחֵי אָחוּךְ עִמָּךְ:",0,0],[25,37,"יָת כַּסְפָּךְ לָא תִתֵּן לֵיהּ בְּחִבּוּלְיָא וּבְרִבִּיתָא לָא תִתֵּן מֵיכְלָךְ:",0,0],[25,38,"אֲנָא יְיָ אֱלָהָכוֹן דִּי אַפֵּקִית יָתְכוֹן מֵאַרְעָא דְמִצְרָיִם לְמִתַּן לְכוֹן יָת אַרְעָא דִכְנַעַן לְמֶהֱוֵי לְכוֹן לֶאֱלָהּ:",0,0],[25,39,"וַאֲרֵי יִתְמַסְכַּן אָחוּךְ עִמָּךְ וְיִזְדַּבַּן לָךְ לָא תִפְלַח בֵּיהּ פָּלְחַן עַבְדִּין:",0,0],[25,40,"כַּאֲגִירָא כְתוֹתָבָא יְהֵי עִמָּךְ עַד שַׁתָּא דְיוֹבֵלָא יִפְלַח עִמָּךְ:",0,0],[25,41,"וְיִפּוֹק מֵעִמָּךְ הוּא וּבְנוֹהִי עִמֵּיהּ וִיתוּב לְזַרְעִיתֵיהּ וּלְאַחֲסָנַת אֲבָהָתוֹהִי יְתוּב:",0,0],[25,42,"אֲרֵי עַבְדַּי אִנּוּן דִּי אַפֵּקִית יָתְהוֹן מֵאַרְעָא דְמִצְרָיִם לָא יִזְדַּבְּנוּן זְבוּן עַבְדִּין:",0,0],[25,43,"לָא תִפְלַח בֵּיהּ בְּקַשְׁיוּ וְתִדְחַל מֵאֱלָהָךְ:",0,0],[25,44,"וְעַבְדָּךְ וְאַמְתָךְ דִּי יְהוֹן לָךְ מִן עַמְמַיָּא דִּי בְסַחֲרָנֵיכוֹן מִנְּהוֹן תִּקְנוּן עַבְדִּין וְאַמְהָן:",0,0],[25,45,"וְאַף מִבְּנֵי תוֹתָבַיָּא עָרְלַיָּא דְּדָיְרִין עִמְּכוֹן מִנְּהוֹן תִּקְנוּן וּמִזַּרְעִיתְהוֹן דְּעִמְּכוֹן דִּי אִתְיְלִידוּ בְּאַרְעֲכוֹן וִיהוֹן לְכוֹן לְאַחֲסָנָא:",0,0],[25,46,"וְתַחְסְנוּן יָתְהוֹן לִבְנֵיכוֹן בַּתְרֵיכוֹן לִירוּתַת אַחֲסָנָא לְעָלָם בְּהוֹן תִּפְלְחוּן וּבְאַחֵיכוֹן בְּנֵי יִשְׂרָאֵל גְּבַר בַּאֲחוּהִי לָא תִפְלַח בֵּיהּ בְּקַשְׁיוּ:",0,0],[25,47,"וַאֲרֵי תַדְבֵּק יַד עָרֵל וְתוֹתָב עִמָּךְ וְיִתְמַסְכַּן אָחוּךְ עִמֵּיהּ וְיִזְדַּבַּן לְעָרֵל תּוֹתָב עִמָּךְ אוֹ לְאַרְמַי זַרְעִית גִּיּוֹרָא:",0,0],[25,48,"בָּתַר דְּיִזְדַּבַּן פֻּרְקָנָא תְּהֵי לֵיהּ חַד מֵאֲחוֹהִי יִפְרְקִנֵּיהּ:",0,0],[25,49,"אוֹ אַח אֲבוּהִי אוֹ בַר אַח אֲבוּהִי יִפְרְקִנֵּיהּ אוֹ מִקָּרִיב בִּשְׂרֵיהּ מִזַּרְעִיתֵיהּ יִפְרְקִנֵּיהּ אוֹ דְתַדְבֵּק יְדֵיהּ וְיִתְפָּרָק:",0,0],[25,50,"וִיחַשֵּׁב עִם זָבְנֵיהּ מִשַּׁתָּא דְּאִזְדַּבַּן לֵיהּ עַד שַׁתָּא דְיוֹבֵלָא וִיהֵי כְּסַף זְבִינוֹהִי בְּמִנְיַן שְׁנַיָא כְּיוֹמֵי אֲגִירָא יְהֵי עִמֵּיהּ:",0,0],[25,51,"אִם עוֹד סְגִיּוּת בִּשְׁנַיָּא לְפוּמְהֵן יָתֵיב פֻּרְקָנֵיהּ מִכְּסַף זְבִינוֹהִי:",0,0],[25,52,"וְאִם זְעֵר יִשְׁתָּאַר בִּשְׁנַיָּא עַד שַׁתָּא דְיוֹבֵלָא וִיחַשֵּׁב לֵיהּ כְּפוּם שְׁנוֹהִי יָתֵב יָת פֻּרְקָנֵיהּ:",0,0],[25,53,"כַּאֲגִיר שְׁנָא בִּשְׁנָא יְהֵי עִמֵּיהּ לָא יִפְלַח בֵּיהּ בְּקַשְׁיוּ לְעֵינָיךְ:",0,0],[25,54,"וְאִם לָא יִתְפָּרַק בְּאִלֵּין וְיִפּוֹק בְּשַׁתָּא דְיוֹבֵלָא הוּא וּבְנוֹהִי עִמֵּיהּ:",0,0],[25,55,"אֲרֵי דִילִי בְנֵי יִשְׂרָאֵל עַבְדִּין עַבְדַּי אִנּוּן דִּי אֲפֵּיקִית יָתְהוֹן מֵאַרְעָא דְמִצְרָיִם אֲנָא יְיָ אֱלָהָכוֹן:",0,0],[26,1,"לָא תַעְבְּדוּן לְכוֹן טַעֲוָן וְצֶלֶם וְקָמָא לָא תְקִימוּן לְכוֹן וְאֶבֶן סָגְדָא לָא תִתְּנוּן בְּאַרְעֲכוֹן לְמִסְגֻּד עֲלַהּ אֲרֵי אֲנָא יְיָ אֱלָהָכוֹן:",0,0],[26,2,"יָת יוֹמֵי שַׁבַּיָּא דִילִי תִטְּרוּן וּלְבֵית מַקְדְּשִׁי תְּהוֹן דָּחֲלִין אֲנָא יְיָ:",0,0],[26,3,"אִם בִּקְיָמַי תְּהָכוּן וְיָת פִּקּוֹדַי תִּטְּרוּן וְתַעְבְּדוּן יָתְהוֹן:",0,0],[26,4,"וְאֶתֵּן מַטְרֵיכוֹן בְּעִדָּנְהוֹן וְתִתֵּן אַרְעָא עֲלַלְתָּא וְאִילַן חַקְלָא יִתֵּן אִבֵּיהּ:",0,0],[26,5,"וִיעָרַע לְכוֹן דְּיָשָׁא יָת קְטָפָא וּקְטָפָא יְעָרַע לְאַפּוֹקֵי בַר זַרְעָא וְתֵיכְלוּן לַחְמְכוֹן לְמִשְׂבַּע וְתֵיתְבוּן לְרָחְצָן בְּאַרְעֲכוֹן:",0,0],[26,6,"וְאֶתֵּן שְׁלָמָא בְּאַרְעָא וְתִשְׁרוּן וְלֵית דְּמָנִיד וֶאֱבַטֵּל חַיְתָא בִשְׁתָּא מִן אַרְעָא וּדְקָטְלִין בְּחַרְבָּא לָא יְעִדּוּן בְּאַרְעֲכוֹן:",0,0],[26,7,"וְתִרְדְּפוּן יָת בַּעֲלֵי דְבָבֵיכוֹן וְיִפְּלוּן קֳדָמֵיכוֹן לְחַרְבָּא:",0,0],[26,8,"וְיִרְדְּפוּן מִנְּכוֹן חַמְשָׁא מְאָה וּמְאָה מִנְּכוֹן לְרִבּוֹתָא יֵעִירְקוּן וְיִפְּלוּן בַּעֲלֵי דְבָבֵיכוֹן קֳדָמֵיכוֹן לְחַרְבָּא:",0,0],[26,9,"וְאֶתְפְּנִי בְמֵימְרִי לְאוֹטָבָא לְכוֹן וְאַפֵּשׁ יָתְכוֹן וְאַסְגֵּי יָתְכוֹן וַאֲקֵם יָת קְיָמִי עִמְּכוֹן:",0,0],[26,10,"וְתֵיכְלוּן עַתִּיקָא דְּעַתִּיק וְעַתִּיקָא מִן קֳדָם חֲדַתָּא תְּפַנּוּן:",0,0],[26,11,"וְאֶתֵּן מַשְׁכְּנִּי בֵּינֵיכוֹן וְלָא יְרַחֵק מֵימְרִי יָתְכוֹן:",0,0],[26,12,"וְאַשְׁרֵי שְׁכִינְתִּי בֵּינֵיכוֹן וְאֶהֱוֵי לְכוֹן לֶאֱלָהּ וְאַתּוּן תְּהוֹן קֳדָמַי לְעָם:",0,0],[26,13,"אֲנָא יְיָ אֱלָהָכוֹן דִּי אַפֵּקִית יָתְכוֹן מֵאַרְעָא דְמִצְרַיִם מִלְּמֶהֱוֵי לְהוֹן עַבְדִּין וְתַבָּרִית נִיר עַמְמַיָּא מִנְּכוֹן וְדַבָּרִית יָתְכוֹן לְחֵרוּתָא:",0,0],[26,14,"וְאִם לָא תְקַבְּלוּן לְמֵימְרִי וְלָא תַעְבְּדוּן יָת כָּל פִּקּוּדַיָּא הָאִלֵּין:",0,0],[26,15,"וְאִם בִּקְיָמַי תְּקוֹצוּן וְאִם יָת דִּינַי תְּרַחֵק נַפְשְׁכוֹן בְּדִיל דְּלָא לְמֶעְבַּד יָת כָּל פִּקּוֹדַי לְאַשְׁנָיוּתְכוֹן יָת קְיָמִי:",0,0],[26,16,"אַף אֲנָא אֶעְבַּד דָּא לְכוֹן וְאַסְעַר עֲלֵיכוֹן בַּהֶלְתָּא יָת שַׁחֶפְתָּא וְיָת קַדַּחְתָּא מְחַשְּׁכָן עַיְנִין וּמַפְּחַן נְפָשׁ וְתִזְרְעוּן לְרֵיקָנוּן זַרְעֲכוֹן וְיֵיכְלֻנֵּיהּ בַּעֲלֵי דְבָבֵיכוֹן:",0,0],[26,17,"וְאֶתֵּן רוּגְזִי בְּכוֹן וְתִתַּבְּרוּן קֳדָם בַּעֲלֵי דְבָבֵיכוֹן וְיִרְדּוּן בְּכוֹן סַנְאֵכוֹן וְתֵעִירְקוּן וְלֵית דְּרָדִיף יָתְכוֹן:",0,0],[26,18,"וְאִם עַד אִלֵּין לָא תְקַבְּלוּן לְמֵימְרִי וְאוֹסֵף לְמִרְדֵּי יָתכוֹן שְׁבַע עַל חוֹבֵיכוֹן:",0,0],[26,19,"וְאֶתְבַּר יָת יְקַר תָּקְפְּכוֹן וְאֶתֵּן יָת שְׁמַיָּא דִי עִלָּוֵיכוֹן תַּקִּיפִין כְּפַרְזְלָא מִלַּאֲחָתָא מִטְרָא וְאַרְעָא דִתְחוֹתֵיכוֹן חֲסִינָא כִנְחָשָׁא מִלְּמֶעְבַּד פֵּירִין:",0,0],[26,20,"וִיסוּפוּן לְרֵיקָנוּ חֵילֵיכוֹן וְלָא תִתֵּן אַרְעֲכוֹן יָת עֲלַלְתַּהּ וְאִילַן אַרְעָא לָא יִתֵּן אִבֵּיהּ:",0,0],[26,21,"וְאִם תְּהָכוּן קֳדָמַי בְּקַשְׁיוּ וְלָא תֵיבוּן לְקַבָּלָא לְמֵימְרִי וְאוֹסֵף לֶאֱתָאָה עֲלֵיכוֹן מָחָא שְׁבַע כְּחוֹבֵיכוֹן:",0,0],[26,22,"וֶאֱגָרֵי בְכוֹן יָת חֵוַת בָּרָא וּתְתַכֵּל יָתְכוֹן וּתְשֵׁיצֵי יָת בְּעִירְכוֹן וְתַזְעֵר יָתְכוֹן וִיצַדְיָן אוֹרְחָתְכוֹן:",0,0],[26,23,"וְאִם בְּאִלֵּין לָא תִתְרְדוּן לְמֵימְרִי וּתְהָכוּן קֳדָמַי בְּקַשְׁיוּ:",0,0],[26,24,"וְאֵהַךְ אַף אֲנָא עִמְּכוֹן בְּקַשְׁיוּ וְאַלְקֵי יָתְכוֹן אַף אֲנָא שְׁבַע עַל חוֹבֵיכוֹן:",0,0],[26,25,"וְאַיְתִי עֲלֵיכוֹן דְּקָטְלִין בְּחַרְבָּא וְיִתְפָּרְעוּן מִנְּכוֹן פֻּרְעֲנוּתָא עַל דַּעֲבַרְתּוּן עַל פִּתְגָּמֵי אוֹרַיְתָא וְתִתְכַּנְּשׁוּן לְקִרְוֵיכוֹן וֶאֱגָרֵי מוֹתָנָא בֵּינֵיכוֹן וְתִתְמַסְּרוּן בִּידָא דְסָנְאָה:",0,0],[26,26,"בִּדְאִתְּבַר לְכוֹן סָעִיד מֵיכְלָא וְיָפְיָן עֲסַר נְשִׁין לַחְמְכוֹן בְּתַנּוּרָא חַד וִיתִיבוּן לַחְמְכוֹן בְּמַתְקְלָא וְתוֹכְלוּן וְלָא תִשְׂבְּעוּן:",0,0],[26,27,"וְאִם בְּדָא לָא תְקַבְּלוּן לְמֵימְרִי וּתְהָכוּן קֳדָמַי בְּקַשְׁיוּ:",0,0],[26,28,"וְאֵהַךְ עִמְּכוֹן בִּתְקוֹף רְגָז וְאִרְדֵּי יָתְכוֹן אַף אֲנָא שְׁבַע עַל חוֹבֵיכוֹן:",0,0],[26,29,"וְתֵיכְלוּן בְּשַׂר בְּנֵיכוֹן וּבְשַׁר בְּנָתֵיכוֹן תֵּיכְלוּן:",0,0],[26,30,"וֶאֱשֵׁיצֵי יָת בָּמָתֵיכוֹן וֶאֱקַצֵּץ יָת חֲנִיסְנְסֵיכוֹן וְאֶתֵּן יָת פִּגְרֵיכוֹן עַל פִּגּוּר טַעֲוָתְכוֹן וִירַחֵק מֵימְרִי יָתְכוֹן:",0,0],[26,31,"וְאֶתֵּן יָת קִרְוֵיכוֹן צָדָא וְאֶצְדֵּי יָת מַקְדְּשֵׁיכוֹן וְלָא אֲקַבֵּל בְּרַעֲוָא קֻרְבַּן כְּנִשָּׁתְכוֹן:",0,0],[26,32,"וְאֶצְדֵּי אֲנָא יָת אַרְעָא וִיצָרְיוּן עֲלַהּ בַּעֲלֵי דְבָבֵיכוֹן דְּיָתְבוּן בַּהּ:",0,0],[26,33,"וְיָתְכוֹן אֲבַדַּר בֵּינֵי עַמְמַיָּא וֶאֱגָרֵי בַתְרֵיכוֹן דְּקָטְלִין בְּחַרְבָּא וּתְהֵי אַרְעֲכוֹן צָדְיָא וְקִרְוֵיכוֹן יְהוֹן חָרְבָּא:",0,0],[26,34,"בְּכֵן תַּרְעֵי אַרְעָא יָת שְׁמִטָּהָא כֹּל יוֹמִין דִּי צְדִיאַת וְאַתּוּן בְּאַרַע בַּעֲלֵי דְבָבֵיכוֹן בְּכֵן תַּשְׁמֵט אַרְעָא וְתַרְעֵי יָת שְׁמִטָּהָא:",0,0],[26,35,"כָּל יוֹמִין דִּי צְדִיאַת תַּשְׁמֵט יָת דִּי לָא שְׁמֵטַת בִּשְׁמִטֵּיכוֹן כַּד הֲוֵיתוּן יָתְבִין עֲלַהּ:",0,0],[26,36,"וּדְיִשְׁתַּאֲרוּן בְּכוֹן וְאָעֵל תַּבְרָא בְּלִבְּהוֹן בְּאַרְעֲתָא דְּסַנְאֵיהוֹן וְיִרְדּוֹף יָתְהוֹן קַל טַרְפָּא דְשַׁקִּיף וְיֵעַרְקוּן כְּמֵעִירוֹק מִן קֳדָם דְּקָטְלִין בְּחַרְבָּא וְיִפְּלוּן וְלֵית דְּרָדִיף:",0,0],[26,37,"וְיִתַּקְלוּן גְּבַר בְּאָחוּהִי כְּמִקָּדָם דְקָטְלִין בְּחַרְבָּא וְרָדִיף לָיִת וְלָא תְהֵי לְכוֹן תְּקוּמָה קֳדָם בַּעֲלֵי דְבָבֵיכוֹן:",0,0],[26,38,"וְתֵבְדוּן בֵּינֵי עַמְמַיָּא וּתְגַמַּר יָתְכוֹן אֲרַע בַּעֲלֵי דְבָבֵיכוֹן:",0,0],[26,39,"וּדְיִשְׁתָּאֲרוּן בְּכוֹן יִתִּמְסוּן בְּחוֹבֵיהוֹן בְּאַרְעֲתָא בַּעֲלֵי דְבָבֵיכוֹן וְאַף בְּחוֹבֵי אֲבָהַתְהוֹן בִּישַׁיָּא דַּאֲחִידִין בִּידֵיהוֹן יִתִּמְסוּן:",0,0],[26,40,"וִיוַדּוּן יָת חוֹבֵיהוֹן וְיָת חוֹבֵי אֲבָהַתְהוֹן בְּשִׁקְרְהוֹן דְּשַׁקָּרוּ קֳדָמָי וְאַף דִּי הַלִּיכוּ קֳדָמַי בְּקַשְׁיוּ:",0,0],[26,41,"אַף אֲנָא אֱהַךְ עִמְּהוֹן בְּקַשְׁיוּ וְאָעֵיל יָתְהוֹן בְּאַרַע בַּעֲלֵי דְבָבֵיהוֹן אוֹ בְכֵן יִתָּבַר לִבְּהוֹן טַפְשָׁא וּבְכֵן יִרְעוּן יָת חוֹבֵיהוֹן:",0,0],[26,42,"וְדָכִירְנָא יָת קְיָמִי דְעִם יַעֲקוֹב וְאַף יָת קְיָמִי דְעִם יִצְחָק וְאַף יָת קְיָמִי דְעִם אַבְרָהָם אֲנָא דָכִיר וְאַרְעָא אֲנָא דָכִיר:",0,0],[26,43,"וְאַרְעָא תִתְרְטֵשׁ מִנְּהוֹן וְתַרְעֵי יָת שְׁמִטָּהָא בְּדִצְדִיאַת מִנְּהוֹן וְאִנּוּן יִרְעוּן יָת חוֹבֵיהוֹן לְוָטִין חֳלַף בִּרְכָן אַיְתִי עֲלֵיהוֹן בְּדִיל דִּבְדִינַי קָצוּ וְיָת קְיָמַי רְחֵקַת נַפְשְׁהוֹן:",0,0],[26,44,"וְאַף בְּרַם דָּא בְּמֵהֱוֵיהוֹן בְּאַרַע בַּעֲלֵי דְבָבֵיהוֹן לָא אַרְטֵשִׁנּוּן וְלָא אַרְחֵקִנּוּן לְשֵׁיצָיוּתְהוֹן לְאַשְׁנָאָה קְיָמִי עִמְּהוֹן אֲרֵי אֲנָא יְיָ אֱלָהֲהוֹן:",0,0],[26,45,"וְדָכִירְנָא לְהוֹן קְיַם קַדְמָאֵי דִּי אַפֵּקִית יָתְהוֹן מֵאַרְעָא דְמִצְרַיִם לְעֵינֵי עַמְמַיָּא לְמֵהֱוֵי לְהוֹן לֵאלָהָא אֲנָא יְיָ:",0,0],[26,46,"אִלֵּין קְיָמַיָּא וְדִינַיָּא וְאוֹרָיָתָא דִּי יְהַב יְיָ בֵּין מֵימְרֵיהּ וּבֵין בְּנֵי יִשְׂרָאֵל בְּטוּרָא דְסִינַי בִּידָא דְמשֶׁה:",0,0],[27,1,"וּמַלִּיל יְיָ עִם משֶׁה לְמֵימָר:",0,0],[27,2,"מַלֵּיל עִם בְּנֵי יִשְׂרָאֵל וְתֵימַר לְהוֹן גְּבַר אֲרֵי יַפְרֵשׁ נְדַר בְּפֻרְסַן נַפְשָׁתָא קֳדָם יְיָ:",0,0],[27,3,"וִיהֵי פֻרְסָנֵיהּ דְּכוּרָא מִבַּר עֶסְרִין שְׁנִין וְעַד בַּר שִׁתִּין שְׁנִין וִיהֵי פֻרְסָנֵיהּ חַמְשִׁין סִלְעִין דִּכְסַף בְּסִלְעֵי קוּדְשָׁא:",0,0],[27,4,"וְאִם נְקוּבְתָא הִיא וִיהֵי פֻרְסָנֵיהּ תְּלָתִין סִלְעִין:",0,0],[27,5,"וְאִם מִבַּר חֲמֵשׁ שְׁנִין וְעַד בַּר עֶסְרִין שְׁנִין וִיהֵי פֻרְסָנֵיהּ דְּכוּרָא עֶסְרִין סִלְעִין וְלִנְקוּבְתָּא עֲסַר סִלְעִין:",0,0],[27,6,"וְאִם מִבַּר יַרְחָא וְעַד בַּר חֲמֵשׁ שְׁנִין וִיהֵי פֻרְסָנֵיהּ דְּכוּרָא חֲמֵשׁ סִלְעִין דִּכְסָף וְלִנְקוּבְתָא פֻרְסָנַהּ תְּלַת סִלְעִין דִּכְסָף:",0,0],[27,7,"וְאִם מִבַּר שִׁתִּין שְׁנִין וּלְעֵלָּא אִם דְּכוּרָא וִיהֵי פֻרְסָנֵיהּ חֲמֵשׁ עֶסְרֵי סִלְעִין וְלִנְקוּבְתָא עֲסַר סִלְעִין:",0,0],[27,8,"וְאִם מִסְכֵּן הוּא מִפֻּרְסָנֵּיהּ וִיקִימִנֵּיהּ קֳדָם כַּהֲנָא וְיִפְרוֹס יָתֵיהּ כַּהֲנָא עַל מֵימַר דִּי תַדְבֵּק יְדָא דְנוֹדֵרָא יִפְרְסִנֵּיהּ כַּהֲנָא:",0,0],[27,9,"וְאִם בְּעִירָא דִּי יְקָרְבוּן מִנַּהּ קֻרְבָּנָא קֳדָם יְיָ כֹּל דִּי יִתֵּן מִנֵּיהּ קֳדָם יְיָ יְהֵי קוּדְשָׁא:",0,0],[27,10,"לָא יְחַלְּפִנֵּיהּ וְלָא יְעִבַּר יָתֵיהּ טַב בְּבִישׁ אוֹ בִישׁ בְּטָב וְאִם חַלָּפָא יְחַלֵּף בְּעִירָא בִּבְעִירָא וִיהֵי הוּא וְחִלּוּפֵיהּ יְהֵי קַדִּישׁ:",0,0],[27,11,"וְאִם כָּל בְּעִירָא מְסָאָבָא דִּי לָא יְקָרְבוּן מִנַּהּ קֻרְבָּנָא קֳדָם יְיָ וִיקִים יָת בְּעִירָא קֳדָם כַּהֲנָא:",0,0],[27,12,"וְיִפְרוֹס כַּהֲנָא יָתַהּ בֵּין טַב וּבֵין בִּישׁ כְּפֻרְסָנָא דְכַהֲנָא כֵּן יְהֵי:",0,0],[27,13,"וְאִם מִפְרַק יִפְרְקֻנַּהּ וְיוֹסֵף חֻמְשֵׁיהּ עַל פֻּרְסָנֵיהּ:",0,0],[27,14,"וּגְבַר אֲרֵי יַקְדֵּשׁ יָת בֵּיתֵיהּ קוּדְשָׁא קֳדָם יְיָ וְיִפְרְסִנֵּיהּ כַּהֲנָא בֵּין טַב וּבֵין בִּישׁ כְּמָא דִּי יִפְרוֹס יָתֵיהּ כַּהֲנָא כֵּן יְקוּם:",0,0],[27,15,"וְאִם דְּאַקְדֵּשׁ יִפְרוֹק יָת בֵּיתֵיהּ וְיוֹסֵף חֹמֶשׁ כְּסַף פֻּרְסָנֵיהּ עֲלוֹהִי וִיהֵי לֵיהּ:",0,0],[27,16,"וְאִם מֵחֲקַל אַחֲסַנְתֵּיהּ יַקְדִּישׁ גְּבַר קָדָם יְיָ וִיהֵי פֻרְסָנֵיהּ לְפוּם זַרְעֵיהּ בַּר זְרַע כּוּר שְׂעוֹרִין בְּחַמְשִׁין סִלְעִין דִּכְסָף:",0,0],[27,17,"אִם מִשַּׁתָּא דְיוֹבֵלָא יַקְדֵּשׁ חַקְלֵיהּ כְּפֻרְסָנֵיהּ יְקוּם:",0,0],[27,18,"וְאִם בָּתַר יוֹבֵלָא יַקְדֵּשׁ חַקְלֵיהּ וִיחַשֵּׁב לֵיהּ כַּהֲנָא יָת כַּסְפָּא עַל מֵימַר שְׁנַיָּא דְּאִשְׁתָּאָרָן עַד שַׁתָּא דְיוֹבֵלָא וְיִתִּמְנַע מִפֻּרְסָנֵיהּ:",0,0],[27,19,"וְאִם מִפְרַק יִפְרוֹק יָת חַקְלָא דְּאַקְדֵּשׁ יָתֵיהּ וְיוֹסֵף חֹמֶשׁ כְּסַף פֻּרְסָנֵיהּ עֲלוֹהִי וִיקוּם לֵיהּ:",0,0],[27,20,"וְאִם לָא יִפְרוֹק יָת חַקְלָא וְאִם זַבִּין יָת חַקְלָא לִגְבַר אָחֳרָן לָא יִתְפָּרָק עוֹד",0,0],[27,21,"וִיהֵי חַקְלָא בְּמִפְּקֵיהּ בְּיוֹבֵלָא קוּדְשָׁא קֳדָם יְיָ כַּחֲקַל חֶרְמָא לְכַהֲנָא תְּהֵי אַחֲסַנְתֵּיהּ:",0,0],[27,22,"וְאִם יָת חֲקַל זְבִינוֹהִי דִּי לָא מֵחֲקַל אַחֲסַנְתֵּיהּ יַקְדֵּשׁ קֳדָם יְיָ:",0,0],[27,23,"וִיחַשֶּׁב לֵיהּ כַּהֲנָא יָת מִנְיַן פֻּרְסָנֵּיהּ עַד שַׁתָּא דְיוֹבֵלָא וְיִתֵּן יָת פֻּרְסָנֵיהּ בְּיוֹמָא הַהוּא קוּדְשָׁא קֳדָם יְיָ:",0,0],[27,24,"בְּשַׁתָּא דְיוֹבֵלָא יְתוּב חַקְלָא לְדִזְבָּנֵיהּ מִנֵּיהּ לְדְדִילֵיהּ אַחֲסָנַת אַרְעָא:",0,0],[27,25,"וְכָל פֻּרְסָנֵיהּ יְהֵי בְּסִלְעֵי קוּדְשָׁא עֶסְרִין מָעִין יְהֵי סִלְעָא:",0,0],[27,26,"בְּרַם בּוּכְרָא דִּי יִתְבַּכַּר קֳדָם יְיָ בִּבְעִירָא לָא יַקְדֵּשׁ גְּבַר יָתֵיהּ אִם תּוֹר אִם אִמַּר דַּיְיָ הוּא:",0,0],[27,27,"וְאִם בִּבְעִירָא מְסָאָבָא וְיִפְרוֹק בְּפֻרְסָנֵיהּ וְיוֹסֵף חֻמְשֵׁיהּ עֲלוֹהִי וְאִם לָא יִתְפָּרַק וְיִזְדַּבַּן בְּפֻרְסָנֵיהּ:",0,0],[27,28,"בְּרַם כָּל חֶרְמָא דִּי יַחֲרֵם גְּבַר קֳדָם יְיָ מִכָּל דִּי לֵיהּ מֵאֲנָשָׁא וּבְעִירָא וּמֵחֲקַל אַחֲסַנְתֵּיהּ לָא יִזְדַּבַּן וְלָא יִתְפָּרָק כָּל חֶרְמָא קֹדֶשׁ קוּדְשִׁין הוּא קֳדָם יְיָ:",0,0],[27,29,"כָּל חֶרְמָא דִּי יִתַּחְרַם מִן אֱנָשָׁא לָא יִתְפָּרָק אִתְקְטָלָא יִתְקְטֵל:",0,0],[27,30,"וְכָל מַעְשְׂרָא דְאַרְעָא מִזַּרְעָא דְאַרְעָא מִפֵּרֵי אִילָנָא דַּיְיָ הוּא קוּדְשָׁא קֳדָם יְיָ:",0,0],[27,31,"וְאִם מִפְרַק יִפְרוֹק גְּבַר מִמַּעַשְׂרֵיהּ חֻמְשֵׁיהּ יוֹסֵף עֲלוֹהִי:",0,0],[27,32,"וְכָל מַעֲשַׂר תּוֹרִין וְעָן כֹּל דְּיֵעִבַּר תְּחוֹת חֻטְרָא עֲשִׂירָאָה יְהֵי קַדִּישׁ קֳדָם יְיָ:",0,0],[27,33,"לָא יְבַקַּר בֵּין טַב לְבִישׁ וְלָא יְחַלְּפִנֵּיהּ וְאִם חַלָּפָא יְחַלְּפִנֵּיהּ וִיהֵי הוּא וְחִלּוּפֵיהּ יְהֵי קוּדְשָׁא לָא יִתְפָּרָק:",0,0],[27,34,"אִלֵּין פִּקּוֹדַיָּא דִּי פַקִּיד יְיָ יָת משֶׁה לְוָת בְּנֵי יִשְׂרָאֵל בְּטוּרָא דְּסִינָי:",0,0]]);
